window.__SUM[14]={"LR005397":{"pair":"ADAM2 -> ITGA4","headline":"Cell adhesion to ADAM2 is blocked by anti-ITGA4 antibody in human HT1080 cells; full-text read.","interaction_type":"direct binding","direction_and_effect":"HT1080 cells (ITGA4-ITGB1) adhere to ADAM2, and adhesion is inhibited by an anti-ITGA4 function-blocking antibody and by the ECD disintegrin-loop and MLD peptides [PMID:21060781].","molecular_requirements":"ITGA4 acts with ITGB1 in HT1080 cells; in RPMI 8866 cells (ITGA4-ITGB7) the anti-ITGA4 antibody only partially inhibited adhesion [PMID:21060781].","affinity_potency":[],"species_and_systems":"Recombinant ADAM2 at 50 \u00b5g/ml as substrate; human HT1080, Tera-2 and RPMI 8866 cell lines; mouse eggs examined for ITGB1 [PMID:21060781].","localisation_and_range":"ADAM2 flagged non-secreted [flag]; adhesion to immobilised ADAM2.","caveats":"Adhesion assays with blocking antibodies, not purified-protein binding. The paper's abstract/evidence concerns ITGA9 more than ITGA4.","key_references":[{"PMID":"21060781","why":"ADAM2 adhesion by ITGA4/ITGA9 integrins, antibody inhibition"}],"covers":["LR002071","LR005397"]},"LR003579":{"pair":"ADCYAP1 -> VIPR2","headline":"PACAP binds VPAC2 and stimulates adenylate cyclase in recombinant systems; abstract-level evidence from three papers.","interaction_type":"direct binding","direction_and_effect":"Recombinant mouse PACAPR-3 bound VIP as well as PACAP-38 and -27, with slightly higher affinity for PACAP-38, and was positively coupled to adenylate cyclase [PMID:8146174]. Human VPAC2 cAMP and calcium responses to PACAP were characterised in CHO cells [PMID:16930633]. GtoPdb lists Agonist [DB:GtoPdb].","molecular_requirements":"Single receptor chain. The carboxy-terminal helical structure of related peptides is needed for VIP2 recognition [PMID:9928018].","affinity_potency":[],"species_and_systems":"Recombinant mouse receptor in mammalian cells [PMID:8146174]; human recombinant receptor in CHO cells [PMID:16930633]. The mouse pair is ortholog-inferred in the dossier.","localisation_and_range":"Ligand flagged secreted [flag]; peptide acting on a membrane receptor.","caveats":"All read as abstracts only; no numeric affinity in our evidence. Two pending and one different_entity row not shown. PMID:9928018 concerns related peptides, not PACAP itself. Structures exist [DB:PDB 7VQX].","key_references":[{"PMID":"8146174","why":"cloned mouse VPAC2 binds PACAP-38, PACAP-27 and VIP and couples to adenylate cyclase"},{"PMID":"16930633","why":"PACAP potency at human VPAC2"}],"covers":["LR000029","LR003579"]},"LR008484":{"pair":"AFDN -> NECTIN3","headline":"Database-only protein interaction between AFDN and NECTIN3; no paper supports a ligand-receptor role.","interaction_type":"database-asserted only","direction_and_effect":"BioGRID lists reconstituted complex and two-hybrid records; IntAct lists co-immunoprecipitation and two-hybrid [DB:BioGRID][DB:IntAct]. UniProt says NECTIN3 interacts via its cytoplasmic domain with AFDN, connecting to the actin cytoskeleton [DB:UniProt].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Species of the database experiments is not reported in our evidence.","localisation_and_range":"No localisation flag for AFDN; NECTIN3 flagged receptor and transmembrane [flag].","caveats":"No papers support this pair; all judged papers were different_entity or inconclusive, so it may be a partner-binding interaction rather than ligand-receptor.","key_references":[],"covers":["LR008484"]},"LR009681":{"pair":"AFDN -> NECTIN4","headline":"Database-only protein interaction between AFDN and NECTIN4; no paper supports a ligand-receptor role.","interaction_type":"database-asserted only","direction_and_effect":"BioGRID and IntAct list a two-hybrid interaction between NECTIN4 and AFDN; UniProt says NECTIN4 interacts via its C-terminus with AFDN [DB:BioGRID][DB:IntAct][DB:UniProt].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Species of the database experiments is not reported in our evidence.","localisation_and_range":"No localisation flag for AFDN; NECTIN4 flagged receptor and transmembrane [flag].","caveats":"No papers support this pair; all judged papers were different_entity or inconclusive, so it may be a partner-binding interaction rather than ligand-receptor.","key_references":[],"covers":["LR009681"]},"LR003588":{"pair":"AGRN -> ATP1A3","headline":"Agrin binds the alpha3 subunit of Na+/K+-ATPase in CNS neurons and inhibits its activity; one abstract, with the pair ortholog-inferred.","interaction_type":"direct binding","direction_and_effect":"Biochemical evidence shows agrin binds alpha3NKA; agrin inhibits alpha3NKA activity, depolarising membranes and raising action potential frequency in cultured and slice cortical neurons. A competitive-antagonist agrin fragment lowers frequency [PMID:16630822].","molecular_requirements":"Only the alpha3 subunit of NKA is reported [PMID:16630822]. Other partners are not reported in our evidence.","affinity_potency":[],"species_and_systems":"Cultured and acute-slice cortical neurons [PMID:16630822]; the animal species is not stated in the abstract. Both listed pairs are ortholog-inferred.","localisation_and_range":"AGRN is flagged secreted and transmembrane [flag]; ATP1A3 is flagged receptor [flag].","caveats":"Abstract-only; ATP1A3 is an enzyme and the effect is inhibitory, so it differs from a usual receptor activation. Binding is described as biochemical evidence, with no affinity in our evidence.","key_references":[{"PMID":"16630822","why":"agrin binds alpha3 Na+/K+-ATPase and inhibits it in CNS neurons"}],"covers":["LR000038","LR003588"]},"LR007089":{"pair":"AGRN -> LRP4:MUSK","headline":"Agrin signalling through an LRP4:MuSK complex has database support and one 2026 rat in vivo study that does not test binding.","interaction_type":"functional only","direction_and_effect":"Database records say the AGRN-LRP4 complex induces phosphorylation and activation of MUSK [DB:UniProt]. In a rat envenomation model, venom suppressed Agrin and p-MuSK/MuSK (P < 0.01), and glutamine treatment upregulated Agrin, Chrne, LRP4, MuSK and Rapsyn expression [PMID:42520945].","molecular_requirements":"Reactome and PDB 8S9P describe a 1:1:1 agrin/LRP4/MuSK complex, so both chains appear to be part of the receptor [DB:Reactome] [DB:PDB 8S9P]. The paper did not distinguish LRP4 from MuSK in the cited result [PMID:42520945].","affinity_potency":[],"species_and_systems":"Rat in vivo and ex vivo diaphragm; curation tags species as human, which the abstract contradicts [PMID:42520945].","localisation_and_range":"Not reported beyond annotation: the receptor complex is flagged as transmembrane [flag].","caveats":"Abstract-only evidence, a toxicology and rescue model measuring pathway expression, not a direct ligand-receptor test [PMID:42520945]. Review-only paper not shown.","key_references":[{"PMID":"42520945","why":"Venom and glutamine change Agrin-MuSK pathway readouts in rats"}],"covers":["LR007089"]},"LR003597":{"pair":"AGT -> LRP2","headline":"One paper shows purified megalin binds angiotensin II by SPR; megalin acts as an uptake receptor for the peptide, not full-length AGT.","interaction_type":"direct binding","direction_and_effect":"Megalin and, to a lesser extent, cubilin act as receptors for Ang II: antisera interfered with Ang II uptake in BN-16 cells, and with binding to mouse brush-border membrane vesicles, and purified megalin bound Ang II directly in SPR [PMID:15467006]. Effect is internalisation (clearance).","molecular_requirements":"Cubilin, described as megalin's chaperone, contributes to a lesser extent [PMID:15467006]. Uptake was only partly blocked by AT1 antagonists, so other receptors contribute.","affinity_potency":[],"species_and_systems":"Curator records human ligand and mouse receptor; the abstract names BN-16 yolk sac cells and mouse proximal tubule vesicles [PMID:15467006].","localisation_and_range":"Megalin is an endocytic membrane receptor; the ligand is secreted [flag].","caveats":"Single paper, abstract only. No affinity reported. Ligand is Ang II, not full-length AGT. Mouse pair is ortholog-inferred. No database records.","key_references":[{"PMID":"15467006","why":"Four lines of evidence including SPR binding of purified megalin to Ang II"}],"covers":["LR000047","LR003597"]},"LR008565":{"pair":"ANXA1 -> EGFR","headline":"Only database interaction records (IntAct, UniProt); no paper shows ANXA1 acting as an EGFR ligand.","interaction_type":"database-asserted only","direction_and_effect":"IntAct lists physical associations by ubiquitin reconstruction, tandem affinity purification and co-immunoprecipitation [DB:IntAct], and UniProt states ANXA1 interacts with EGFR 'By similarity' [DB:UniProt]. Direction and effect are not reported in our evidence.","molecular_requirements":"not reported in our evidence.","affinity_potency":[],"species_and_systems":"Species not reported in our evidence; human pair only.","localisation_and_range":"ANXA1 is flagged secreted and not transmembrane; EGFR transmembrane receptor [flag].","caveats":"No papers judged beyond one 'different_entity' outcome. These records show association, not activation.","key_references":[],"covers":["LR008565"]},"LR007098":{"pair":"APLP2 -> PLXNA4","headline":"Supported only by one IntAct surface plasmon resonance record; no curator-verified paper.","interaction_type":"database-asserted only","direction_and_effect":"Direction and effect are not reported in our evidence. IntAct lists a surface plasmon resonance record (Q9HCM2-Q06481) citing PMID 35922511 [DB:IntAct].","molecular_requirements":"not reported in our evidence.","affinity_potency":[],"species_and_systems":"Species and system not reported in our evidence.","localisation_and_range":"Both partners carry transmembrane and receptor flags [flag], so a contact-dependent interaction would be expected, but this is not shown.","caveats":"The one paper judged was classed abstract_insufficient, so no curator-verified evidence exists. Rests on a single database record.","key_references":[],"covers":["LR007098"]},"LR005469":{"pair":"APP -> APLP1","headline":"APP-APLP1 association shown by FRET and co-IP in cis on the same membrane; a family interaction, not classical signalling.","interaction_type":"direct binding","direction_and_effect":"APP and APLP1 formed heterotypic cis interactions (same membrane) detected by FRET and co-immunoprecipitation; coexpression with APP diminished Abeta42 generation [PMID:19126676]. Only APLP1, not APP or APLP2, also forms trans (cell-cell) interactions [PMID:19126676].","molecular_requirements":"The N-terminal half of the ectodomain is crucial for the interaction [PMID:19126676].","affinity_potency":[],"species_and_systems":"Human proteins in cell imaging [PMID:19126676]. Mouse pair is ortholog-inferred.","localisation_and_range":"Both partners flagged secreted and receptor; the evidence is cis, same-membrane [flag] [PMID:19126676].","caveats":"Abstract only. Cis association is not a classical secreted ligand to receptor signalling event; direction not applicable.","key_references":[{"PMID":"19126676","why":"APP family cis interactions by FRET and co-IP"}],"covers":["LR002154","LR005469"]},"LR005478":{"pair":"APP -> LRP6","headline":"One paper reports APP physically binding LRP6 and co-activating canonical Wnt signalling; full text read.","interaction_type":"direct binding","direction_and_effect":"APP binds LRP6 and enhances Wnt3a-driven canonical (TCF/LEF) signalling; LRP6 overexpression enhanced APP's effect on that pathway, labelled agonist/co-activator [PMID:30232325].","molecular_requirements":"LRP6 extracellular domain bound four sites in the APP extracellular domain (two in E1, two in E2) by peptide array [PMID:30232325]. A second co-receptor, Vangl2, binds APP separately [PMID:30232325].","affinity_potency":[],"species_and_systems":"Co-immunoprecipitation from primary rat cortical neurons, peptide array with recombinant human LRP6 ECD, and reporter assays in HEK293A cells [PMID:30232325]. Human and mouse pairs are both listed; the dossier's experiments are human/rat.","localisation_and_range":"APP is flagged secreted, receptor and transmembrane [flag]; the binding is described through the extracellular domains, and the paper's role for APP is as a Wnt co-receptor partner, not a classical secreted ligand [PMID:30232325].","caveats":"Single paper. The ligand/receptor direction is a database convention, since APP is itself described as interacting with a Wnt co-receptor.","key_references":[{"PMID":"30232325","why":"Co-IP, peptide-array mapping and reporter assays for APP-LRP6"}],"covers":["LR002163","LR005478"]},"LR008907":{"pair":"APP -> NCSTN","headline":"Supported only by database records of APP-nicastrin association; no paper was verified for this pair.","interaction_type":"database-asserted only","direction_and_effect":"No curator-verified paper. Records describe nicastrin (NCSTN) as a gamma-secretase subunit that binds APP C-terminal fragments C83 and C99 [DB:UniProt].","molecular_requirements":"NCSTN is an essential subunit of the gamma-secretase complex [DB:UniProt]; it binds processed C-terminal fragments rather than full-length APP [DB:UniProt].","affinity_potency":[],"species_and_systems":"BioGRID lists affinity-capture-Western [DB:BioGRID]; PDB lists four structures containing both chains [DB:PDB 6IYC] [DB:PDB 8X52].","localisation_and_range":"Not reported in our evidence.","caveats":"This looks like an enzyme-substrate relationship, not a signalling ligand-receptor pair; the receptor flags are absent for NCSTN in the dossier.","key_references":[],"covers":["LR008907"]},"LR009672":{"pair":"B2M -> TFRC","headline":"B2M-TFRC appears only through an HFE-transferrin receptor structure; no verified paper.","interaction_type":"database-asserted only","direction_and_effect":"Direction and effect are not reported in our evidence; PDB 1DE4 is the HFE-transferrin receptor complex [DB:PDB 1DE4] with a pull-down entry [DB:IntAct P02786-P61769].","molecular_requirements":"B2M appears as a chain of the HFE-TfR structure [DB:PDB 1DE4]; direct B2M-TFRC contact is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human proteins in database records.","localisation_and_range":"B2M is flagged secreted and TFRC a transmembrane receptor [flag].","caveats":"Rests on 2 database records only (1 row review_only); B2M probably co-occurs as HFE's partner chain.","key_references":[],"covers":["LR009672"]},"LR005487":{"pair":"BGLAP -> GPR37","headline":"Osteocalcin binds and activates GPR37 in HEK293 cells with Kd 14.1 +/- 1.8 nM; a mouse myelination phenotype supports it.","interaction_type":"direct binding","direction_and_effect":"Biotinylated osteocalcin bound GPR37, not GPR37L1, with a dissociation constant (Kd) of 14.1 \u00b1 1.8 nM; co-immunoprecipitation also showed direct interaction [PMID:34678058]. Osteocalcin triggered calcium rise, beta-arrestin recruitment (EC50 10.2 \u00b1 2.5 nM), reduced cAMP and raised ERK phosphorylation in GPR37-transfected cells, blocked by GPR37 antibody or pertussis toxin [PMID:34678058]. In mice, OCN deletion gave hypermyelination, so OCN via GPR37 restrains oligodendrocyte differentiation [PMID:34678058].","molecular_requirements":"Gi/o coupling indicated by pertussis toxin sensitivity [PMID:34678058]. No co-receptor reported in our evidence.","affinity_potency":[{"value":"Kd 14.1 \u00b1 1.8 nM","assay":"biotinylated OCN saturation binding","system":"GPR37-transfected HEK293 cells","cite":"PMID:34678058"},{"value":"EC50 10.2 \u00b1 2.5 nM","assay":"beta-arrestin recruitment (PRESTO-Tango)","system":"GPR37-transfected HTLA cells","cite":"PMID:34678058"}],"species_and_systems":"Human GPR37 overexpressed in HEK293-based cells; primary rat oligodendrocytes; OCN-knockout mice [PMID:34678058].","localisation_and_range":"Osteocalcin has a secreted flag [flag]; GPR37 is highly expressed in mature oligodendrocytes [PMID:34678058].","caveats":"Single paper (abstract plus full-text excerpts). Binding measured in overexpressing HEK293 cells. The curator effect label 'antagonist' conflicts with the paper, where OCN activates GPR37 signalling.","key_references":[{"PMID":"34678058","why":"OCN binds and activates GPR37 (Kd, EC50) and regulates myelination"}],"covers":["LR002173","LR005487"]},"LR006783":{"pair":"BMP2 -> ACVRL1","headline":"Rests on a GtoPdb agonist record alone; no papers confirmed this pair.","interaction_type":"database-asserted only","direction_and_effect":"GtoPdb lists BMP2 as agonist at ACVRL1 [DB:GtoPdb]. No paper evidence in our evidence.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human pair; experimental species and system not reported in our evidence.","localisation_and_range":"BMP2 is flagged secreted and not transmembrane [flag]; ACVRL1 is flagged as a receptor, with no transmembrane flag reported [flag].","caveats":"Five papers were judged abstract_insufficient and none confirmed the pair. The BioGRID and IntAct examples attached name BMP2-BMPR1B and other partners, not ACVRL1 [DB:BioGRID][DB:IntAct]; Reactome is a generic receptor-complex binding record [DB:Reactome].","key_references":[],"covers":["LR006783"]},"LR003669":{"pair":"BMP2 -> BMPR1B","headline":"BMP2 binds the type I receptor BMPR1B (ALK6) directly; well supported by SPR, cell cross-linking and cloning.","interaction_type":"direct binding","direction_and_effect":"BMP2 is the ligand and BMPR1B a type I receptor; BMP2 activity was competitively inhibited by the BMPR1B ectodomain in C2C12 cells [PMID:19956691]. GtoPdb lists it as agonist [DB:GtoPdb].","molecular_requirements":"BMP2 formed heteromeric complexes with type II receptors ActRII and ActRIIB in P19 cells, alongside ALK3 and ALK6 binding [PMID:9748228]. Endoglin binding of BMP-2 required the type I receptors ALK3/ALK6 [PMID:9872992]. Whether BMPR1B alone suffices for signalling is not reported in our evidence.","affinity_potency":[{"value":"apparent KD 2.7 nM","assay":"SPR, BMP2 over immobilized receptor ectodomain","system":"recombinant ligand and receptor ectodomains","cite":"PMID:19735544"}],"species_and_systems":"Binding data come from recombinant proteins (SPR) and P19 embryonic carcinoma cells [PMID:19735544][PMID:9748228]; the receptor was cloned and shown to bind BMP-2 in an early study [PMID:7811286]. The dossier covers human and mouse pairs; the species of each experiment is mostly not reported in our evidence.","localisation_and_range":"BMP2 is flagged secreted [flag]; ligand acts on cell-surface receptors (paracrine).","caveats":"Two of the supporting papers were read only as abstracts [PMID:9872992][PMID:7811286]. The endoglin paper concerns binding within an accessory-protein complex.","key_references":[{"PMID":"19735544","why":"SPR affinities of BMP2 for BMPR-IB, full text"},{"PMID":"9748228","why":"[125I]BMP2 affinity labelling shows ALK6 binding and type II receptor complexes"},{"PMID":"19956691","why":"BMPR1B ectodomain competitively inhibits BMP2 activity"}],"covers":["LR000120","LR003669"]},"LR003678":{"pair":"BMP4 -> BMPR1B","headline":"BMP4 binds BMPR1B (ALK-6) in cloned-receptor binding assays; three abstract-only papers, no affinity.","interaction_type":"direct binding","direction_and_effect":"A cloned receptor, CFK-43a (ALK6), specifically binds BMP-2 and BMP-4 [PMID:7811286]. BMP-4 bound ALK-3 and ALK-6 efficiently in transfected COS cells [PMID:8006002]. BMP-4 induced osteoblast differentiation through Smad1/5/8, and type I receptors acted synergistically on alkaline phosphatase induction [PMID:11282024]. GtoPdb lists agonist [DB:GtoPdb].","molecular_requirements":"Binding was enhanced by a type II co-receptor (C. elegans DAF-4) in COS cells [PMID:8006002]. BMP-4 did not bind ALK-2 (ACVR1) per the curator note [PMID:8006002].","affinity_potency":[],"species_and_systems":"Transfected COS cells [PMID:8006002]; osteoprogenitor cells [PMID:11282024]; species unspecified in the cloning paper [PMID:7811286].","localisation_and_range":"BMP4 flagged secreted [flag]; BMPR1B transmembrane status not stated.","caveats":"All three papers are abstract only; the Smad paper does not name BMPR1B in the evidence shown [PMID:11282024]. The human pair record is ortholog-inferred per the dossier. A DB BioGRID record is a reconstituted BMP4-BMPR1B complex [DB:BioGRID 282659].","key_references":[{"PMID":"7811286","why":"Cloned ALK6 receptor specifically binds BMP-4"},{"PMID":"8006002","why":"BMP-4 binds ALK-6 efficiently in COS cells"}],"covers":["LR000129","LR003678"]},"LR005496":{"pair":"BMP5 -> RGMA","headline":"BMP5 binds RGMA in SPR with Kd 83 nM; single paper, human/human labels, abstract-level curation.","interaction_type":"direct binding","direction_and_effect":"RGMA is an RGM-family BMP co-receptor; curators label the effect agonist [PMID:23029472]. RGMA showed lower affinity than HJV (17 nM) and RGMB (33 nM) for BMP5 [PMID:23029472].","molecular_requirements":"Not reported in our evidence for this pair (no co-receptor or complex requirement tested for BMP5 in the excerpts).","affinity_potency":[{"value":"Kd 83 nM","assay":"SPR","system":"RGMA vs BMP5, mean of 4-9 experiments","cite":"PMID:23029472"}],"species_and_systems":"Curators label both partners human; SPR with recombinant proteins, 4-9 experiments per interaction [PMID:23029472]. Mouse pair is projected from human evidence.","localisation_and_range":"BMP5 is flagged secreted and not transmembrane [flag], so signalling would be paracrine or endocrine. RGMA is flagged secreted [flag].","caveats":"One paper, read as an abstract by the curators with full-text excerpts available. No functional assay for BMP5 with this receptor is shown in the excerpts. None of the RGMs bound BMP9 [PMID:23029472].","key_references":[{"PMID":"23029472","why":"SPR affinity matrix of RGMs for BMP ligands"}],"covers":["LR002182","LR005496"]},"LR003687":{"pair":"BMP6 -> BMPR2","headline":"BMP-6 binds BMPR-II less efficiently than ActR-II/IIB in one full-text paper (data not shown).","interaction_type":"direct binding","direction_and_effect":"BMP-6 bound BMPR-II, less efficiently than ActR-II and ActR-IIB; curated effect is agonist [PMID:10504300]. GtoPdb lists BMP6 as agonist at BMPR2 [DB:GtoPdb].","molecular_requirements":"Type II receptors alone bound BMP-6; with type I receptors co-transfected, BMP-6 bound various type I receptors with affinities that varied by combination [PMID:10504300].","affinity_potency":[],"species_and_systems":"125I-BMP-6 (recombinant human) cross-linking in transfected COS-7 cells; endogenous binding in mouse MC3T3-E1 and C2C12 lines [PMID:10504300]. Human pair not ortholog-inferred; mouse pair is.","localisation_and_range":"BMP6 is flagged as secreted [flag], so action would be paracrine or endocrine; the receptor is flagged as a transmembrane receptor [flag].","caveats":"The BMPR-II binding result is stated as data not shown in the paper, so it is weakly documented. One more paper is pending and unused. No affinity value.","key_references":[{"PMID":"10504300","why":"BMP-6 binds BMPR-II less efficiently, data not shown"}],"covers":["LR000138","LR003687"]},"LR008277":{"pair":"BMP8B -> ACVR2A:BMPR1B","headline":"BMP8B -> ACVR2A:BMPR1B rests on GtoPdb agonist records only; no paper confirmed it.","interaction_type":"database-asserted only","direction_and_effect":"GtoPdb lists BMP8B as an agonist at ACVR2A and BMPR1B [DB:GtoPdb]; no verified paper supports the effect.","molecular_requirements":"Complex is assembled from separate chain records; subunit requirements are not reported in our evidence.","affinity_potency":[],"species_and_systems":"No experimental system reported in our evidence.","localisation_and_range":"Not reported in our evidence; the ligand has no secretion flag in the dossier.","caveats":"Judged papers were abstract-insufficient, review-only or about a different entity; none confirmed this pair. No affinity.","key_references":[],"covers":["LR008277"]},"LR003696":{"pair":"BTC -> ERBB2","headline":"BTC -> ERBB2 is supported only by heterodimer activation and phosphorylation papers, not by binding to ERBB2 alone.","interaction_type":"functional only","direction_and_effect":"BTC and AREG show similar affinity for EGFR/ErbB2 heterodimers and EGFR homodimers (balanced agonists), in luciferase-fragment-complementation and radioligand-binding assays [PMID:25086039]. In MIN-6 beta cells BTC induced phosphorylation of ErbB-1 and ErbB-2 [PMID:21897861].","molecular_requirements":"ErbB2 acts as a heterodimer partner of EGFR in the first paper, so activation is via the EGFR/ErbB2 heterodimer rather than ErbB2 alone [PMID:25086039]. PDB 8U4K has BTC and ERBB2 chains [DB:PDB 8U4K].","affinity_potency":[],"species_and_systems":"Human cell systems [PMID:25086039]; MIN-6 mouse beta cell line and mice [PMID:21897861].","localisation_and_range":"BTC is flagged secreted and transmembrane; ERBB2 flagged transmembrane [flag].","caveats":"Evidence is for heterodimer activity, not binding to ERBB2 alone; two further papers are pending and not shown. Abstract-level reading.","key_references":[{"PMID":"25086039","why":"BTC affinity for EGFR/ErbB2 heterodimers versus EGFR homodimers."},{"PMID":"21897861","why":"BTC induces ErbB-1 and ErbB-2 phosphorylation in beta cells."}],"covers":["LR000147","LR003696"]},"LR009069":{"pair":"CALM1 -> KCNQ3","headline":"Calmodulin-KCNQ3 is supported by structures and UniProt, mainly a chimeric Kv7.2-Kv7.3 fragment.","interaction_type":"direct binding","direction_and_effect":"A crystal structure of a chimeric Kv7.2-Kv7.3 proximal C-terminal domain with calmodulin is listed [DB:PDB 5J03]. UniProt says KCNQ3 interacts with calmodulin [DB:UniProt].","molecular_requirements":"The structure is a Kv7.2-Kv7.3 chimera, so KCNQ3 alone is not shown [DB:PDB 5J03].","affinity_potency":[],"species_and_systems":"Human, X-ray.","localisation_and_range":"Intracellular calmodulin; no secreted flag in our evidence. Not reported in our evidence beyond the entity annotation flags.","caveats":"No papers were confirmed; support is from curated database records only.","key_references":[],"covers":["LR009069"]},"LR009645":{"pair":"CALM1 -> KCNQ5","headline":"Calmodulin-KCNQ5 is supported by crystal and cryo-EM structures.","interaction_type":"direct binding","direction_and_effect":"Structures are the Mg2+/CaM:Kv7.5 AB domain complex [DB:PDB 6B8Q] and human KCNQ5-CaM in apo state [DB:PDB 9J38]. UniProt says KCNQ5 interacts via its C-terminus with calmodulin/CALM1 [DB:UniProt].","molecular_requirements":"C-terminal region (AB domain) binds calmodulin [DB:PDB 6B8Q][DB:UniProt].","affinity_potency":[],"species_and_systems":"Human, X-ray and cryo-EM.","localisation_and_range":"Intracellular calmodulin; no secreted flag in our evidence. Not reported in our evidence beyond the entity annotation flags.","caveats":"No papers were confirmed; support is from curated database records only.","key_references":[],"covers":["LR009645"]},"LR006819":{"pair":"CALM1 -> MYLK2","headline":"Calmodulin activates MYLK2 per GtoPdb, with an NMR/SAXS structure.","interaction_type":"database-asserted only","direction_and_effect":"GtoPdb lists calmodulin as activator of MYLK2 [DB:GtoPdb]. A Ca-calmodulin complex with skeletal muscle myosin light chain kinase was solved by NMR and SAXS [DB:PDB 2LV6].","molecular_requirements":"Ca-bound calmodulin [DB:PDB 2LV6].","affinity_potency":[],"species_and_systems":"Human, from databases.","localisation_and_range":"Intracellular calmodulin; no secreted flag in our evidence. Not reported in our evidence beyond the entity annotation flags.","caveats":"No papers were confirmed; support is from curated database records only. One row was review_only.","key_references":[],"covers":["LR006819"]},"LR005559":{"pair":"CBLN4 -> DCC","headline":"CBLN4 binds DCC directly in several assays, with lower affinity than Netrin-1; supported by one full-text paper.","interaction_type":"direct binding","direction_and_effect":"Protein-microarray screening, cell-surface binding and SPR show CBLN4 binds DCC; CBLN1, CBLN2 and CBLN3 did not bind DCC [PMID:24400119]. Netrin-1 competes with CBLN4 at an overlapping site and binds with about 5-fold higher affinity [PMID:24400119]. Curators label it agonist, but DCC activation by CBLN4 is not shown in the abstract or excerpts.","molecular_requirements":"Binding maps to the membrane-proximal fibronectin domains 4-6 of DCC [PMID:24400119].","affinity_potency":[{"value":"K 117\u00b134 nM","assay":"125I-CBLN4-Fc radioligand cell-binding assay","system":"DCC-transfected HEK293T cells","cite":"PMID:24400119"},{"value":"K 22\u00b16 nM (Netrin-1, for comparison)","assay":"125I-gD-Netrin-1 radioligand assay","system":"DCC-transfected HEK293T cells","cite":"PMID:24400119"}],"species_and_systems":"Recombinant proteins on transfected COS-7 and HEK293T cells; CBLN4-null mice for the in vivo phenotype [PMID:24400119]. The human pair is direct; the mouse pair is projected.","localisation_and_range":"CBLN4 is flagged secreted [flag].","caveats":"CBLN4 also binds the DCC homolog NEO1 with lower affinity, and CBLN4-null mice showed no commissural-axon defect, only a transient increase in wandering brachial-plexus axons [PMID:24400119]. Single paper.","key_references":[{"PMID":"24400119","why":"Microarray, SPR and radioligand data for CBLN4-DCC and comparison with Netrin-1"}],"covers":["LR002249","LR005559"]},"LR001689":{"pair":"CCL18 -> PITPNM3","headline":"Supported by binding, co-IP and functional data in one full-text paper: PITPNM3 as a CCL18 receptor in breast cancer cells.","interaction_type":"direct binding","direction_and_effect":"CCL18 acts as an agonist: recombinant CCL18 induced calcium responses in PITPNM3-transfected HEK293 cells (not rCCL20) and tyrosine phosphorylation of PITPNM3; PITPNM3 suppression abrogated CCL18-driven xenograft invasion and metastasis [PMID:21481794].","molecular_requirements":"Not reported in our evidence beyond PITPNM3 alone being sufficient in transfected HEK293 cells for calcium response [PMID:21481794].","affinity_potency":[],"species_and_systems":"Human CCL18 and human PITPNM3; MDA-MB-231 cells (membrane immunoprecipitation with mass spectrometry, confocal colocalisation), HEK293 transfectants, breast cancer xenografts [PMID:21481794]. An IntAct co-immunoprecipitation record cites the same paper [DB:IntAct].","localisation_and_range":"Ligand flagged secreted [flag]; PITPNM3 localised to the plasma membrane in transfectants and MDA-MB-231 cells [PMID:21481794].","caveats":"A radioligand binding assay is mentioned in the excerpts but no result is shown in our evidence. Single primary paper; the database record is from the same paper. A review-only paper was also judged.","key_references":[{"PMID":"21481794","why":"Identifies PITPNM3 as CCL18 receptor; binding, calcium signalling, in vivo"}],"covers":["LR001689"]},"LR003759":{"pair":"CCL2 -> CCR4","headline":"Functional-only evidence: one abstract-read paper in a human melanoma-CTL migration model.","interaction_type":"functional only","direction_and_effect":"CTL migration toward tumour cells was mediated by CCR4 on the CTL and CCL2 secreted by tumour cells; blocking with CCL2 or anti-CCL2 or anti-CCR4 antibodies prevented migration, and anti-CCR4 inhibited migration toward isolated CCL2 in Transwell [PMID:16421945].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human melanoma patient CTL and autologous tumour cells; 3D organotypic culture and Transwell [PMID:16421945]. Both listed interactions are flagged ortholog-inferred.","localisation_and_range":"Ligand is flagged as secreted and not transmembrane [flag], so signalling is presumably paracrine or endocrine; receptor is flagged transmembrane [flag].","caveats":"No binding assay; antibody blockade only. One paper, abstract only. No database records.","key_references":[{"PMID":"16421945","why":"CCL2-CCR4-dependent CTL migration toward melanoma cells"}],"covers":["LR000238","LR003759"]},"LR003768":{"pair":"CCL5 -> CCR4","headline":"CCL5 (RANTES) binds CCR4 in competition assays (IC50 9.3 nM, human); functional CCR4 evidence is shared with CCR1.","interaction_type":"direct binding","direction_and_effect":"[125I]RANTES binding to human and murine CC CKR-4 was measured by equilibrium competition [PMID:8573157]. In mast cells CCL5 was the only agonist of seven that induced chemotaxis [PMID:12270118]. Reactome states CCR3, 4 and 5 bind CCL5 [DB:Reactome R-HSA-373061].","molecular_requirements":"Not reported in our evidence. Anti-CCR4 alone only partly blocked mast-cell migration; both CCR1 and CCR4 had to be blocked for complete inhibition [PMID:12270118].","affinity_potency":[{"value":"IC50 9.3 +/- 3.0 nM","assay":"competition for [125I]RANTES binding","system":"human CCR4, transfected HL-60 cells","cite":"PMID:8573157"},{"value":"IC50 5.7 +/- 2.6 nM","assay":"competition for [125I]RANTES binding","system":"murine CCR4, transfected HL-60 cells","cite":"PMID:8573157"}],"species_and_systems":"Human and mouse CCR4 in HL-60 cells [PMID:8573157]; human cord blood mast cells [PMID:12270118]. The mouse pair is inferred from human evidence.","localisation_and_range":"CCL4/CCL5 carry a secreted flag [flag], so paracrine or endocrine range is implied; the receptor carries receptor and transmembrane flags [flag].","caveats":"Both papers were abstract-only reads. The mast-cell data cannot separate CCR4 from CCR1. BioGRID lists a reconstituted complex [DB:BioGRID].","key_references":[{"PMID":"8573157","why":"RANTES binding IC50 to human and murine CCR4"},{"PMID":"12270118","why":"RANTES chemotaxis of mast cells via CCR1 and CCR4"}],"covers":["LR000258","LR003768"]},"LR003777":{"pair":"CCL7 -> CCR10","headline":"One abstract reports MCP-3 binding to the cloned receptor called CCR10 with Kd 1 nM; this is the 1997 receptor, whose identity is not clarified here.","interaction_type":"direct binding","direction_and_effect":"The cloned receptor bound MCP-1 and MCP-3 with highest affinity (KD for MCP-3 1 nM) [PMID:9364936]. Function or signalling was not reported in the abstract.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[{"value":"KD 1 nM","assay":"MCP-3 binding to cloned receptor","system":"cloned human CCR10","cite":"PMID:9364936"}],"species_and_systems":"Human cloned receptor; expression described as primarily placenta and fetal liver [PMID:9364936]. Mouse pair is ortholog-inferred.","localisation_and_range":"CCL7 flagged secreted; CCR10 flagged transmembrane receptor [flag].","caveats":"Abstract only, single paper, no database records. The curated receptor-symbol assignment for this 1997 'CCR10' is not discussed in the dossier.","key_references":[{"PMID":"9364936","why":"Cloning of CCR10; MCP-3 KD 1 nM"}],"covers":["LR000267","LR003777"]},"LR003786":{"pair":"CCL8 -> CCR3","headline":"CCL8 binds CCR3 in vitro (QCM, Kd 1.2 x 10-7 M) and drives CCR3-dependent eosinophil responses; weaker chemoattractant than CCL11 and CCL24.","interaction_type":"direct binding","direction_and_effect":"Purified CCL8 bound CCR3 and induced CCR3 internalization on exposure to 100 nM CCL8; its chemotactic effect on CCR3-expressing cells was weaker than CCL11 and CCL24 [PMID:29281969]. In human eosinophils, >95% of the response to MCP-2 and other chemokines was mediated through CCR3, as shown with a blocking antibody [PMID:9005985]. GtoPdb lists a full agonist [DB:GtoPdb].","molecular_requirements":"CCR3 alone suffices in the tested systems; no co-receptor requirement is reported.","affinity_potency":[{"value":"Kd 1.2 x 10-7 M (120 nM)","assay":"quartz crystal microbalance, purified CCL8 with CCR3","system":"in vitro","cite":"PMID:29281969"}],"species_and_systems":"Recombinant CCL8 made in E. coli, species human [PMID:29281969]; primary human eosinophils and CCR3 transfectants [PMID:9005985]. Mouse pair is ortholog-inferred.","localisation_and_range":"Secreted ligand acting on a transmembrane receptor [flag].","caveats":"The authors note the CCL8 Kd came from QCM while CCL11 and CCL24 values came from SPR, so the methods are not strictly comparable [PMID:29281969]. The eosinophil paper was read as abstract only and shows CCR3 dependence rather than direct binding [PMID:9005985].","key_references":[{"PMID":"29281969","why":"QCM binding Kd, internalization, weaker chemotaxis than CCL11/CCL24"},{"PMID":"9005985","why":"CCR3 antagonist antibody shows >95% of eosinophil response to MCP-2 is CCR3-mediated"}],"covers":["LR000276","LR003786"]},"LR005568":{"pair":"CCL8 -> CCR8","headline":"Mouse CCL8 is a CCR8 agonist in mouse Th2 cells; the human pair is inferred from this mouse evidence.","interaction_type":"functional only","direction_and_effect":"Mouse CCL8 acts as an agonist for CCR8 but not CCR2; it induced pertussis-toxin-sensitive chemotaxis and calcium flux in mouse Th2 cells, and Ccr8- and Ccl8-deficient mice had less eosinophilic skin inflammation [PMID:21217759]. GtoPdb lists CCL8-CCR8 as an agonist [DB:GtoPdb]; UniProt says CCR8 binds a variety of chemokines including CCL8 [DB:UniProt].","molecular_requirements":"CCR8 alone was identified as the receptor on CCL8-responsive Th2 cells; no co-receptor is reported in our evidence.","affinity_potency":[],"species_and_systems":"Experiments used mouse CCL8 and mouse cells and mice [PMID:21217759]. The human pair is ortholog-inferred, so human direct binding is not shown here (the paper does report human CCR8 marks an IL-5-enriched Th2 subset).","localisation_and_range":"Secreted ligand acting on a transmembrane receptor [flag]; skin-homing paracrine axis [PMID:21217759].","caveats":"Evidence is functional (chemotaxis, calcium flux, knockouts), not a direct binding measurement; the paper was read as abstract plus full-text excerpts. No affinity is reported in our evidence.","key_references":[{"PMID":"21217759","why":"Mouse CCL8 is a CCR8 but not CCR2 agonist; Ccl8 and Ccr8 knockout phenotypes"}],"covers":["LR002267","LR005568"]},"LR001698":{"pair":"CCN2 -> FGFR2","headline":"CCN2 binds FGFR2 in a protein-array screen and enhances FGFR2 binding to FGF2 and FGF4; abstract-level, one paper.","interaction_type":"direct binding","direction_and_effect":"CCN2 bound FGFR2 and enhanced FGFR2 binding to FGF2 and FGF4, and CCN2 with FGF2 had a collaborative effect on ERK phosphorylation and osteoblastic differentiation [PMID:23142580]. This points to a positive modulator rather than a competing ligand.","molecular_requirements":"Binding to FGFR2 is also reported for FGFR3, with higher affinity toward FGFR2 [PMID:23142580]. Subunit or domain requirements are not reported in our evidence.","affinity_potency":[],"species_and_systems":"Protein-array screen, then confirmation of binding; osteoblastic cells for function; species not specified in the abstract [PMID:23142580]. IntAct holds the protein-array record [DB:IntAct].","localisation_and_range":"CCN2 is flagged as secreted [flag], so paracrine or autocrine action is plausible; this is annotation, not shown by the papers.","caveats":"Abstract read only. No affinity value reported. Database support is the same paper [DB:IntAct].","key_references":[{"PMID":"23142580","why":"Protein-array binding of CCN2 to FGFR2 and enhancement of FGF binding"}],"covers":["LR001698","LR005067"]},"LR005577":{"pair":"CCN3 -> ITGA5","headline":"CCN3 binds integrin alpha5beta1 directly (EC50-type half-maximal binding 50 nM); supported by full text and databases.","interaction_type":"direct binding","direction_and_effect":"CCN3 is an agonist: it supports HUVEC adhesion and drives migration dependent on alpha5beta1 and alphavbeta3 [PMID:12695522]. CCN3 binds directly to immobilized integrins alphavbeta3 and alpha5beta1 with half-maximal binding at 10 nM and 50 nM CCN3 respectively [PMID:12695522].","molecular_requirements":"The receptor is the alpha5beta1 heterodimer; both UniProt and the paper describe ITGA5:ITGB1 [DB:UniProt][PMID:12695522]. Adhesion also used heparan sulfate proteoglycans [PMID:12695522].","affinity_potency":[{"value":"50 nM","assay":"half-maximal binding (EC50), solid-phase ELISA with immobilized alpha5beta1","system":"purified integrin, recombinant human CCN3","cite":"PMID:12695522"}],"species_and_systems":"Recombinant human CCN3 (baculovirus-expressed) and purified integrins; HUVEC cells; rat cornea angiogenesis assay [PMID:12695522].","localisation_and_range":"CCN3 is a matricellular protein, and its adhesion activity is shown on coated protein [PMID:12695522]; a secretion annotation for CCN3 is not in our dossier.","caveats":"Single primary paper; UniProt and GtoPdb records cite the same paper (and UniProt also PMID 15611078) [DB:UniProt][DB:GtoPdb]. GtoPdb entry reports Action=Binding with pKd units but no value is shown in our evidence [DB:GtoPdb].","key_references":[{"PMID":"12695522","why":"Direct CCN3-integrin binding and HUVEC adhesion, migration and angiogenesis"}],"covers":["LR002276","LR005577"]},"LR006756":{"pair":"Cd200 -> Cd200r3","headline":"One FACS binding report supports mouse Cd200 binding to Cd200r3; abstract only.","interaction_type":"direct binding","direction_and_effect":"FITC-labelled CD200Fc bound COS7 cells transfected with each CD200R isoform [PMID:15187158]. Anti-CD200 R2/R3 mAbs had a significantly lesser functional effect than anti-R1/R4 [PMID:15187158].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Mouse pair; COS7 transfectants [PMID:15187158].","localisation_and_range":"Cd200r3 carries no secreted or transmembrane flag [flag]; otherwise not reported in our evidence.","caveats":"Single paper, abstract only; the claim covers all isoforms collectively. No affinity.","key_references":[{"PMID":"15187158","why":"FACS binding of CD200Fc to all CD200R isoforms"}],"covers":["LR006756"]},"LR007953":{"pair":"CD320 -> JAML","headline":"Supported only by one IntAct solid-phase assay record; no curated papers.","interaction_type":"database-asserted only","direction_and_effect":"Direction and effect not reported in our evidence.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Not reported in our evidence; no experimental species available.","localisation_and_range":"Both partners flagged transmembrane, not secreted [flag].","caveats":"Rests on a single IntAct solid phase assay record [DB:IntAct]; the one paper judged was abstract_insufficient and gave no confirmation.","key_references":[],"covers":["LR007953"]},"LR010968":{"pair":"CD36 -> TLR4","headline":"CD36 co-precipitates with TLR4 and TLR6 after ligand stimulation in human THP-1 monocytes; a co-receptor complex rather than a classic ligand.","interaction_type":"direct binding","direction_and_effect":"Stimulation of THP-1 monocytes with CD36 ligands rapidly induced co-precipitation of CD36 with TLR4 and TLR6 [PMID:20037584]. CD36 increased NF-kB reporter activity 3-fold in TLR4-TLR6 cells, and oxLDL or amyloid-beta signalling needed CD36, TLR4 and TLR6 [PMID:20037584].","molecular_requirements":"Simultaneous expression of CD36, TLR4 and TLR6 was required for maximal responses; CD14 did not substitute for CD36 [PMID:20037584]. Reactome and UniProt describe a TLR4:TLR6:CD36:oxLDL complex [DB:Reactome][DB:UniProt].","affinity_potency":[],"species_and_systems":"Human THP-1 cells (co-IP), HEK293 reporter cells, and mouse knockout macrophages/microglia [PMID:20037584].","localisation_and_range":"Membrane receptors forming a complex at the cell surface or intracellular compartments after oxLDL [PMID:20037584]; CD36 flagged transmembrane [flag].","caveats":"Co-IP is induced by ligand and does not prove a direct CD36-TLR4 contact; the entity pair is Receptor-Receptor, not ligand-receptor [flag]. Needs TLR6 as partner (TLR4 alone not shown sufficient).","key_references":[{"PMID":"20037584","why":"CD36-TLR4-TLR6 complex assembly and signalling"}],"covers":["LR010968"]},"LR005586":{"pair":"CD40LG -> ITGA2B","headline":"Soluble CD40L binds purified integrin alphaIIbbeta3; ITGA2B alone not tested separately.","interaction_type":"direct binding","direction_and_effect":"rsCD40L specifically bound purified integrin alphaIIbbeta3 and activated platelets in a beta3-dependent manner and induced platelet spreading [PMID:11875495]. CD154 bound alphaIIbbeta3 with an affinity about 4-fold higher than for alpha5beta1 [PMID:22461623].","molecular_requirements":"Binding was shown with the alphaIIbbeta3 heterodimer; a KGD integrin-recognition sequence in rsCD40L was needed for in vivo thrombosis [PMID:11875495]. Role of alphaIIb chain alone not reported.","affinity_potency":[],"species_and_systems":"Recombinant soluble proteins, purified integrin, platelets, in vivo mouse thrombosis [PMID:11875495]; mouse pair projected.","localisation_and_range":"CD40LG flagged secreted [flag]; soluble CD40L acts on platelets.","caveats":"Abstracts only. Evidence is for the alphaIIbbeta3 complex, so ITGA2B alone is chain-only attribution.","key_references":[{"PMID":"11875495","why":"rsCD40L binds alphaIIbbeta3 via KGD"},{"PMID":"22461623","why":"CD154 affinity ~4-fold higher for alphaIIbbeta3 than alpha5beta1"}],"covers":["LR002287","LR005586"]},"LR003795":{"pair":"CD40LG -> ITGAM","headline":"CD40L binds the integrin ITGAM (Mac-1) in two papers read as abstracts; one is direct binding, one an in vivo transplant hint.","interaction_type":"direct binding","direction_and_effect":"Flow cytometry, radioactive binding assays and immunoprecipitation showed CD40L interacting with Mac-1, giving Mac-1-dependent adhesion, migration and myeloperoxidase release in vitro; CD40/LDLR double-deficient mice had no smaller lesions, and Mac-1 inhibition reduced lesions, suggesting a CD40-independent route [PMID:17372166]. In a murine allograft model CD154 blockade outperformed CD40 blockade, raising the possibility of a second receptor [PMID:32149455].","molecular_requirements":"The binding evidence is for the Mac-1 (alphaM:beta2) heterodimer, so ITGAM alone is not shown to suffice [PMID:17372166].","affinity_potency":[],"species_and_systems":"Curator-recorded species are human for both partners; the abstracts also use mice (atherosclerosis, thioglycolate peritonitis, allograft) [PMID:17372166][PMID:32149455]. Both human and mouse interactions are listed, neither ortholog-inferred.","localisation_and_range":"Ligand carries secreted and transmembrane flags [flag]; paper localisation details not reported in our evidence.","caveats":"Both papers read as abstracts only. The allograft paper's abstract is truncated, so its ITGAM result is not shown in the dossier text beyond the evidence sentence [PMID:32149455]. Three further papers were judged abstract_insufficient and are not shown.","key_references":[{"PMID":"17372166","why":"Binding assays showing CD40L-Mac-1 interaction"},{"PMID":"32149455","why":"In vivo transplant evidence for a second CD154 receptor"}],"covers":["LR000285","LR003795"]},"LR008196":{"pair":"CD40LG -> ITGAM:ITGB2","headline":"CD40L to the Mac-1 complex (ITGAM:ITGB2) rests on a single abstract that states the binding without testing it.","interaction_type":"database-asserted only","direction_and_effect":"The abstract states that CD154 also binds alphaIIbbeta3, alpha5beta1 and alphaMbeta2 integrins [PMID:22461623]. Direction and effect for alphaMbeta2 are not reported in our evidence.","molecular_requirements":"The receptor is the alphaM:beta2 heterodimer as named in the abstract [PMID:22461623].","affinity_potency":[],"species_and_systems":"Human recorded for both partners; the paper's own experiments used U937 cells and focus on other integrins [PMID:22461623].","localisation_and_range":"Ligand carries secreted and transmembrane flags [flag].","caveats":"The curator notes alphaMbeta2 is asserted in the opening sentence rather than newly shown; the experiments cover alphaIIbbeta3, alpha5beta1 and CD40. Abstract-only read. No database record in the dossier.","key_references":[{"PMID":"22461623","why":"Statement that CD154 binds alphaMbeta2 (not tested in the paper)"}],"covers":["LR008196"]},"LR005595":{"pair":"CD72 -> CD5","headline":"CD72 was reported as a CD5 ligand by direct binding and transfection in 1991, with costimulatory functional follow-up; the evidence is old and abstract-level.","interaction_type":"direct binding","direction_and_effect":"Biotinylated purified human CD5 bound CD72, blocked by anti-CD72 antibodies, and CD72-transfected non-B cells gained CD5 binding [PMID:1711157]. Engagement of CD5 and/or CD72 with agonistic antibodies delivered costimulatory signals in B-1a, B-2 and chronic lymphocytic leukemia B cells [PMID:8757302]. Soluble CD5 raised thymidine uptake 2- to 5-fold in anti-sIgM-activated B cells, and this was abolished by soluble recombinant CD72 [PMID:8806810].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[{"value":"0.15 microM","assay":"lowest effective concentration of soluble CD5 in a B-cell thymidine uptake assay (potency, not Kd)","system":"human B cells activated with immobilized anti-sIgM","cite":"PMID:8806810"}],"species_and_systems":"Human proteins and cells; transfection into mouse L-cell fibroblasts and human Jurkat T cells [PMID:1711157]. The mouse pair is ortholog-inferred from human evidence; Lyb-2 is named as the mouse CD72 in the paper [PMID:1711157].","localisation_and_range":"CD72 is a B-cell surface protein [PMID:1711157]. The annotation flags list CD5 as secreted and CD72 as transmembrane [flag]; contact between T and B cells is suggested for this pair [PMID:8757302].","caveats":"All three papers were read as abstracts only. In the costimulation study, the two anti-CD72 antibodies but not soluble CD5 costimulated with suboptimal anti-CD40 or IL-4 [PMID:8806810]. Functional readouts rely largely on agonistic antibodies [PMID:8757302]. BioGRID, IntAct and UniProt rest on the same 1991 paper [DB:BioGRID] [DB:UniProt]. One further paper is pending and not shown.","key_references":[{"PMID":"1711157","why":"Direct CD5-biotin binding to CD72 and transfectant gain-of-binding"},{"PMID":"8806810","why":"Soluble recombinant CD72 abolished the CD5 costimulatory effect"},{"PMID":"8757302","why":"Costimulatory signalling by CD5/CD72 engagement in B-cell subsets"}],"covers":["LR002296","LR005595"]},"LR008808":{"pair":"CDH1 -> EGFR","headline":"EGFR co-immunoprecipitates with E-cadherin in keratinocytes; complex formation, not shown to be direct.","interaction_type":"functional only","direction_and_effect":"EGFR co-immunoprecipitated with E-cadherin in HaCat cells, indicating higher-order complexes; E-cadherin cell contacts activate MAPK via EGFR recruitment [PMID:10969083]. BioGRID lists affinity capture-western and two-hybrid records [DB:BioGRID].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"HaCat keratinocyte line; species not stated in the dossier [PMID:10969083].","localisation_and_range":"Both membrane proteins; contact-dependent [flag].","caveats":"Record class is Receptor-Receptor; co-IP does not show direct binding; direction not established.","key_references":[{"PMID":"10969083","why":"E-cadherin-EGFR co-IP in HaCat cells"}],"covers":["LR008808"]},"LR006837":{"pair":"CDH1 -> ITGA2:ITGB1","headline":"E-cadherin binds integrin alpha2beta1 (complex entry); one direct-binding paper, abstract only.","interaction_type":"direct binding","direction_and_effect":"Pentameric E-cadherin specifically bound purified alpha2beta1 and the alpha2 A-domain; HT1080 adhesion was blocked by anti-alpha2 and anti-beta1 antibodies [PMID:12392763].","molecular_requirements":"Complex entry alpha2:beta1; both subunits implicated by antibody block, alpha2 A-domain alone binds [PMID:12392763].","affinity_potency":[],"species_and_systems":"Human HT1080 cells and purified integrin [PMID:12392763].","localisation_and_range":"Membrane-bound; adhesion.","caveats":"Monomeric E-cadherin did not bind; classed Adhesion-Adhesion; one paper.","key_references":[{"PMID":"12392763","why":"E-cadherin binds integrin alpha2beta1"}],"covers":["LR006837"]},"LR007179":{"pair":"CGA:LHB -> LHCGR","headline":"LH (CGA:LHB) on LHCGR is supported by curated databases and structures; no verified paper in our evidence.","interaction_type":"database-asserted only","direction_and_effect":"GtoPdb lists LHB-LHCGR and CGA-LHCGR as full agonists [DB:GtoPdb]. Reactome records LH receptor:LH binding [DB:Reactome].","molecular_requirements":"Ligand is the CGA:LHB heterodimer [flag].","affinity_potency":[{"value":"pIC50 9.899999618530273 to 10.899999618530273","assay":"GtoPdb affinity range for LHB","system":"not specified","cite":"PMID:1922095"}],"species_and_systems":"Human; cryo-EM structure listed is of chorionic gonadotropin, not LH [DB:PDB 7FIG].","localisation_and_range":"Secreted heterodimer, transmembrane receptor [flag].","caveats":"Two pending rows. GtoPdb cites PMID:1922095 and PMID:12727981, not judged for this pair here. BioGRID record is on CGA only [DB:BioGRID].","key_references":[],"covers":["LR007179"]},"LR007962":{"pair":"CLU -> TREM2:TYROBP","headline":"Complex-level pair supported only by database records that cite the CLU-TREM2 paper; no paper judged for the complex.","interaction_type":"database-asserted only","direction_and_effect":"UniProt states TREM2 acts as a receptor for apolipoproteins including CLU, enhancing uptake in microglia [DB:UniProt Q9NZC2]. BioGRID lists TREM2-CLU as a reconstituted complex [DB:BioGRID 2593475].","molecular_requirements":"Records name TREM2 only; TYROBP participation is not shown in our evidence.","affinity_potency":[],"species_and_systems":"Database records only; the cited paper is PMID 27477018 (not judged for this row).","localisation_and_range":"TREM2 is flagged secreted and receptor; TYROBP transmembrane [flag].","caveats":"No paper rows; the outcome_counts show one different_entity row. The complex adds TYROBP but evidence concerns TREM2 alone; see the CLU -> TREM2 summary.","key_references":[],"covers":["LR007962"]},"LR008574":{"pair":"CNTF -> CNTFR:IL6ST:LIFR","headline":"CNTF acts through a CNTFR:gp130:LIFR complex; four abstract-only papers, mixture of binding and signalling.","interaction_type":"functional only","direction_and_effect":"Human CNTF induces a receptor complex of CNTFR (non-signaling alpha) with gp130 and LIFR [PMID:12643274]. Deleting the LIFR N-terminal cytokine binding domain abolished CNTF signalling but not LIF or OSM signalling [PMID:16051226]. GtoPdb lists CNTF as an agonist for CNTFR, IL6ST and LIFR [DB:GtoPdb].","molecular_requirements":"All three chains needed: human CNTF cannot directly induce a gp130/LIFR heterodimer [PMID:12643274]; the LIFR N-terminal cytokine binding domain is required [PMID:16051226]. The IL-6R can serve as an alpha-receptor substitute for human CNTF [PMID:12643274].","affinity_potency":[{"value":"IC50 29 nM (human CNTF)","assay":"nonradioactive competitive binding","system":"soluble gp130 and soluble CNTFR, LIFR not included","cite":"PMID:7810882"},{"value":"3-5 x 10(-10)M","assay":"binding of CNTF/alpha CNTF receptor heterocomplex to gp130","system":"transfected human cell lines","cite":"PMID:8627290"}],"species_and_systems":"Human cells and recombinant proteins [PMID:8627290][PMID:12643274][PMID:16051226].","localisation_and_range":"CNTF is flagged secreted [flag]; soluble cytokine acting on cell-surface complex.","caveats":"All four papers read as abstracts only. No single paper measures binding to the whole trimer; PMID 7810882 lacks LIFR [PMID:7810882]. Three further rows were review-only.","key_references":[{"PMID":"12643274","why":"Human CNTF receptor complex: CNTFR, gp130, LIFR; IL-6R can substitute"},{"PMID":"16051226","why":"LIFR N-terminal domain required for CNTF signalling"},{"PMID":"8627290","why":"CNTF/CNTFR heterocomplex binds gp130 at 3-5 x 10(-10)M"}],"covers":["LR008574"]},"LR005649":{"pair":"CNTN3 -> PTPRG","headline":"Direct structural evidence that PTPRG binds CNTN3; one abstract-level paper, with a co-crystal only for mouse CNTN4.","interaction_type":"direct binding","direction_and_effect":"Crystal structures show the carbonic-anhydrase-like domain of PTPRG interacts directly with the second and third Ig repeats of contactins; PTPRG binds CNTN3, 4, 5 and 6, whereas PTPRZ binds only CNTN1 [PMID:20133774]. The effect on signalling is not reported in our evidence.","molecular_requirements":"Binding uses the PTPRG carbonic-anhydrase-like domain and the contactin Ig repeats 2-3 region; the binding site is conserved among CNTN3, 4, 5 and 6 [PMID:20133774].","affinity_potency":[],"species_and_systems":"Crystal structures used mouse CNTN4 (four N-terminal Ig repeats) with mouse PTPRG carbonic-anhydrase-like domain; the specificity result covers the CNTN family [PMID:20133774]. Curator species labels are human for this pair.","localisation_and_range":"CNTN3 is annotated non-secreted and PTPRG non-secreted [flag]; contact-mediated signalling is implied by the annotation, not shown.","caveats":"Abstract-only read. The co-crystal structure is for CNTN4-PTPRG; CNTN3 binding is stated in the abstract as a specificity result, with no detail on assay or affinity in our evidence [PMID:20133774].","key_references":[{"PMID":"20133774","why":"Crystal structures and contactin specificity of PTPRG"}],"covers":["LR002369","LR005649"]},"LR005658":{"pair":"COL13A1 -> ITGA11","headline":"Integrin a11b1 binds collagen XIII by SPR and pull-down and mediates cell adhesion; mouse bone data support function.","interaction_type":"direct binding","direction_and_effect":"Integrin a11b1 is a receptor for collagen XIII: C2C12 cells expressing a11b1 as their only collagen receptor adhered to it, and SPR and pull-down assays confirmed the interaction [PMID:33306155]. a11b1 mediates adhesion to the motifs GPKGER and GF(S)QGEK [PMID:33306155]. Effect labelled agonist.","molecular_requirements":"Binding is by the heterodimer; the a11-I domain recognises the motifs, with docking to a homology model [PMID:33306155].","affinity_potency":[],"species_and_systems":"C2C12 cells expressing human a11b1, recombinant assays and mice (Itga11-/- crossed with Col13a1-overexpressing mice) [PMID:33306155].","localisation_and_range":"COL13A1 is annotated non-secreted and transmembrane [flag]; the paper calls it a transmembrane collagen [PMID:33306155].","caveats":"Abstract-level read plus excerpts; no affinity values in our evidence. The in vivo bone phenotype was milder in double mutants than in Col13a1 overexpression alone [PMID:33306155].","key_references":[{"PMID":"33306155","why":"a11b1 as a collagen XIII receptor with SPR, pull-down and in vivo data"}],"covers":["LR002379","LR005658"]},"LR006873":{"pair":"COL16A1 -> ITGA1:ITGB1","headline":"Supported only by a UniProt subunit annotation; no primary paper in our evidence.","interaction_type":"database-asserted only","direction_and_effect":"UniProt states COL16A1 interacts with integrins ITGA1/ITGB1 and ITGA2/ITGB1 [DB:UniProt Q07092]. Direction and effect are not reported in our evidence.","molecular_requirements":"The annotation names both the ITGA1 and ITGB1 subunits [DB:UniProt Q07092].","affinity_potency":[],"species_and_systems":"Not reported in our evidence; the UniProt record cites PMID 15165854, which is not among our judged papers [DB:UniProt Q07092].","localisation_and_range":"COL16A1 is annotated secreted and not transmembrane [flag].","caveats":"Database assertion only; judged papers were review-only, so no primary evidence was verified.","key_references":[],"covers":["LR006873"]},"LR006882":{"pair":"COL18A1 -> ITGA10:ITGB1","headline":"Database-asserted only: BioGRID and IntAct record COL18A1-ITGB1 binding; no curator-confirmed paper for this specific integrin.","interaction_type":"database-asserted only","direction_and_effect":"Direction and effect: not reported in our evidence.","molecular_requirements":"Databases record binding to ITGB1 only, not to the specific alpha chain, so the alpha subunit requirement is unresolved [DB:BioGRID] [DB:IntAct].","affinity_potency":[],"species_and_systems":"BioGRID lists a reconstituted complex [DB:BioGRID, PMID:19542224]; IntAct lists a pull down [DB:IntAct, PMID:17615292]. Species not reported in our evidence.","localisation_and_range":"Ligand flagged as secreted; receptor is a transmembrane complex [flag].","caveats":"No papers were judged confirmed: curator read counts are review_only and different_entity only. The pair rests on database records alone, and these name ITGB1 and not the alpha chain.","key_references":[],"covers":["LR006882"]},"LR008673":{"pair":"COL1A1 -> CD36","headline":"Platelet CD36 (GPIV) binds type I collagen fibrils with nanomolar affinity; one 1989 abstract-read paper.","interaction_type":"direct binding","direction_and_effect":"Anti-GPIV Fab fragments completely inhibited collagen-induced platelet shape change, aggregation and secretion, and purified GPIV competed with membrane GPIV to inhibit collagen-induced activation [PMID:2468670]. Purified GPIV bound rapidly and reversibly to collagen type I fibrils [PMID:2468670].","molecular_requirements":"Not reported in our evidence beyond GPIV alone. The collagen was type I fibrils, an assembled heterotrimer, not COL1A1 alone.","affinity_potency":[{"value":"Kd 0.34 +/- 0.10 nM","assay":"direct binding of purified GPIV to collagen type I fibrils, single-site fit","system":"purified GPIV, collagen type I fibrils","cite":"PMID:2468670"}],"species_and_systems":"Human platelets [PMID:2468670].","localisation_and_range":"Receptor is a platelet membrane glycoprotein; collagen is matrix.","caveats":"Abstract-only read; the curator classes the assay as functional. Evidence is from 1989 and a single paper. The curator notes a related COL1A2 -> CD36 row was rejected because GPVI was the receptor studied there.","key_references":[{"PMID":"2468670","why":"GPIV/CD36 as a platelet collagen receptor with Kd 0.34 nM"}],"covers":["LR008673"]},"LR006891":{"pair":"COL1A1 -> ITGA11:ITGB1","headline":"Weak support: one abstract states ITGA11 is a collagen I receptor in pancreatic stellate cells; no binding assay in our evidence.","interaction_type":"functional only","direction_and_effect":"The abstract describes ITGA11 as the receptor for collagen type I in pancreatic stellate cells, and ITGA11 knockdown reduced activation, migration and contractility [PMID:30808244].","molecular_requirements":"The paper concerns the ITGA11 subunit; beta1 partnership not reported in our evidence beyond a BioGRID COL1A1-ITGB1 co-purification [DB:BioGRID, PMID:2156854].","affinity_potency":[],"species_and_systems":"Human pancreatic stellate cells and PDAC stroma; abstract only [PMID:30808244].","localisation_and_range":"Receptor is a membrane integrin; collagen is matrix.","caveats":"The receptor role is stated in the abstract, not tested as a binding result; abstract-only read. Chain-level caveat: COL1A1 and COL1A2 form one heterotrimer.","key_references":[{"PMID":"30808244","why":"ITGA11 in stellate cells described as collagen I receptor"}],"covers":["LR006891"]},"LR008583":{"pair":"COL1A2 -> ITGA2:ITGB1","headline":"Platelet adhesion to purified collagen alpha 2(I) chain via alpha2beta1, shown in one 1990 abstract-read paper; direct but old and chain-level.","interaction_type":"direct binding","direction_and_effect":"Purified alpha 2(I) chain of type I collagen, like alpha 1(I), effectively supported Mg2+-dependent platelet adhesion; antibody P1H5 against the integrin alpha 2 subunit inhibited adhesion of platelets and of liposomes bearing the purified receptor to collagen [PMID:2156854]. Collagen is the adhesive substrate, the integrin the receptor; no agonist/antagonist wording beyond adhesion.","molecular_requirements":"The receptor is the alpha2beta1 (GPIa-IIa, VLA-2) complex; the paper reports receptor-complex activity and an alpha 2 subunit antibody block, so both chains are treated as needed [PMID:2156854]. Which subunit contacts collagen is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human platelets and liposomes with purified human receptor [PMID:2156854]. Substrates were denatured collagen chains and fragments.","localisation_and_range":"Ligand COL1A2 is flagged secreted, not transmembrane [flag]; the receptor acts on the cell surface, so signalling is by contact with the secreted matrix protein (inferred from the flags, not stated by the paper).","caveats":"Abstract read only. The chains were tested as adhesive substrates (not in-solution binding), and the fragment mapping was on alpha 1(I). One IntAct biochemical record for this pair exists [DB:IntAct]. Four other papers were judged review-only and are not shown.","key_references":[{"PMID":"2156854","why":"Purified alpha 2(I) chain supports alpha2beta1-dependent platelet adhesion"}],"covers":["LR008583"]},"LR005667":{"pair":"COL1A2 -> OSCAR","headline":"OSCAR binds motifs in fibrillar collagens and costimulates osteoclastogenesis; one 2011 abstract-read paper, collagen chain not resolved.","interaction_type":"direct binding","direction_and_effect":"OSCAR binds specific motifs within fibrillar collagens exposed on bone surfaces, and this binding signalled to increase osteoclast numbers in culture; OSCAR costimulates an FcR-gamma-associated pathway [PMID:21841309]. Curator label: agonist.","molecular_requirements":"OSCAR signals as an FcR gamma-associated ITAM receptor, so the adaptor is needed [PMID:21841309]. The collagen motif, not a specific chain, is the binder.","affinity_potency":[],"species_and_systems":"Samples from mice and from patients deficient in ITAM signalling pathways [PMID:21841309]; curator notes both human and mouse were assayed, although the dossier marks mouse rows as ortholog-inferred.","localisation_and_range":"Ligand COL1A2 is flagged secreted, not transmembrane [flag]; the receptor acts on the cell surface, so signalling is by contact with the secreted matrix protein (inferred from the flags, not stated by the paper).","caveats":"Abstract read only. Fibrillar collagens are tested as a class, so COL1A1 and COL1A2 (chains of one heterotrimer) cannot be separated. No database records. A second confirmed paper is counted but not shown.","key_references":[{"PMID":"21841309","why":"OSCAR binds fibrillar collagen motifs and costimulates osteoclastogenesis"}],"covers":["LR002388","LR005667"]},"LR008547":{"pair":"COL2A1 -> ITGA2:ITGB1","headline":"Alpha2beta1 was isolated from bovine chondrocytes on collagen-Sepharose; one abstract-read paper, with a caveat on in vivo expression.","interaction_type":"direct binding","direction_and_effect":"Affinity chromatography of bovine chondrocyte membrane proteins on collagen-Sepharose followed by immunoprecipitation confirmed collagen-binding alpha2beta1 on chondrocytes [PMID:7688313]. Collagen to integrin; 'Stimulatory' label [flag].","molecular_requirements":"Immunoprecipitation identified the alpha2beta1 heterodimer, so both chains are considered present [PMID:7688313].","affinity_potency":[],"species_and_systems":"Bovine chondrocyte membranes; surface integrin analysis on human fetal chondrocytes [PMID:7688313].","localisation_and_range":"Matrix ligand, cell-surface receptor [flag].","caveats":"Abstract read only. The curator notes that alpha2 is absent from human fetal cartilage sections, an in vivo caveat. Four papers were review-only.","key_references":[{"PMID":"7688313","why":"Collagen-Sepharose isolates alpha2beta1 from chondrocytes"}],"covers":["LR008547"]},"LR003849":{"pair":"COL3A1 -> ITGB1","headline":"Support for collagen III with ITGB1 is indirect: alpha2beta1 loss in COL3A1-mutant fibroblasts; chain-only entity.","interaction_type":"functional only","direction_and_effect":"Fibroblasts from patients with COL3A1 mutations show defective matrix and high reduction of the alpha2beta1 integrin, named as the functional receptor; treating with COLLIII restored the control phenotype [PMID:14970208].","molecular_requirements":"The paper concerns the alpha2beta1 heterodimer; ITGB1 alone is not shown to be sufficient [PMID:14970208].","affinity_potency":[],"species_and_systems":"Human EDS dermal fibroblasts [PMID:14970208]; mouse pair projected.","localisation_and_range":"ITGB1 flagged not secreted [flag].","caveats":"Abstract read only. Patient genetics rather than binding; a second confirmed paper is counted but not shown.","key_references":[{"PMID":"14970208","why":"COL3A1-mutant fibroblasts lose alpha2beta1"}],"covers":["LR000343","LR003849"]},"LR005676":{"pair":"COL4A1 -> DDR2","headline":"Direct but weak collagen IV binding and phosphorylation of DDR2 in one full-text paper.","interaction_type":"direct binding","direction_and_effect":"Collagen IV bound DDR2 and induced receptor phosphorylation, but binding and phosphorylation were consistently weaker than with fibril-forming collagens [PMID:9659900].","molecular_requirements":"DDR2 is a collagen receptor tyrosine kinase; no co-receptor requirement is reported in our evidence. The tested material was commercial type IV collagen [PMID:9659900].","affinity_potency":[],"species_and_systems":"Human-labelled ligand and receptor, slot-blot binding and phosphorylation assays; mouse pair is projected from human [PMID:9659900].","localisation_and_range":"Ligand is flagged secreted, not transmembrane [flag]; as a collagen it is a matrix ligand, but this is not shown by the cited papers.","caveats":"Commercial type IV collagen is a generic preparation, probably mostly the COL4A1/COL4A2 heterotrimer, so binding cannot be assigned to one chain [PMID:9659900]. Binding was consistently weaker than to fibril-forming collagens [PMID:9659900]. No affinity values reported.","key_references":[{"PMID":"9659900","why":"Collagens as ligands of DDR receptors; type IV weaker than fibrillar"}],"covers":["LR002397","LR005676"]},"LR003867":{"pair":"COL5A3 -> SDC3","headline":"Likely mis-assigned: syndecan-3 binds the alpha4(V) chain, not COL5A3.","interaction_type":"direct binding","direction_and_effect":"Syndecan-3 was isolated using the alpha4(V) N-terminal domain, supporting Schwann cell adhesion [PMID:11751872].","molecular_requirements":"Binding depends on a heparin-binding region of alpha4(V)-NTD not present in other type V collagen NTDs [PMID:11751872].","affinity_potency":[{"value":"IC50 ~30 ng/ml","assay":"heparin inhibition of Schwann cell adhesion","system":"rat Schwann cells on alpha4(V)-NTD","cite":"PMID:11751872"}],"species_and_systems":"Rat Schwann cells [PMID:11751872]; other species are projections.","localisation_and_range":"Ligand is flagged secreted, not transmembrane [flag]; as a collagen it is a matrix ligand, but this is not shown by the cited papers.","caveats":"The chain tested is alpha4(V), not COL5A3; abstract only.","key_references":[{"PMID":"11751872","why":"Schwann cell syndecan-3 binds alpha4(V) NTD"}],"covers":["LR000361","LR003867"]},"LR003876":{"pair":"CORT -> SSTR4","headline":"Cortistatin binds SSTR4 with high affinity in two recombinant-receptor binding papers, plus GtoPdb.","interaction_type":"direct binding","direction_and_effect":"Human cortistatin-17 bound all human SSTR subtypes much like rat CST-14 and inhibited forskolin-induced cAMP production through SSTRs [PMID:9125122]. [125I]Tyr10-CST bound all five receptors with high affinity and no marked selectivity versus somatostatin [PMID:9650799]. GtoPdb lists a full agonist [DB:GtoPdb].","molecular_requirements":"No co-receptor reported in our evidence.","affinity_potency":[{"value":"pKd 9.67","assay":"[125I]Tyr10-CST radioligand binding","system":"human sst4 stably expressed in CCL39 cells","cite":"PMID:9650799"},{"value":"pKi 8.600000381469727-8.800000190734863","assay":"GtoPdb full agonist","system":"not reported","cite":"PMID:9650799"}],"species_and_systems":"Human receptors in CCL39 cells [PMID:9650799]; human peptide on human SSTRs [PMID:9125122]; mouse pair ortholog-inferred.","localisation_and_range":"CORT secreted and SSTR4 transmembrane by flags [flag].","caveats":"Abstract-level reads; pan-SSTR binding, so not subtype-specific, and the radioligand is an iodinated CST14 analogue [PMID:9650799]. BioGRID also lists the pair [DB:BioGRID].","key_references":[{"PMID":"9650799","why":"Binding of cortistatin to all five human SSTRs, pKd values"},{"PMID":"9125122","why":"Human cortistatin binds all SSTR subtypes and lowers cAMP"}],"covers":["LR000370","LR003876"]},"LR003885":{"pair":"CSF3 -> CSF3R","headline":"G-CSF binds CSF3R; strongly supported by two crystal structures, mutagenesis and human in vivo receptor downregulation.","interaction_type":"direct binding","direction_and_effect":"Crystal structures of human GCSF with the receptor ligand-binding region show a 2:2 complex [PMID:16492764] [PMID:10537111]. G-CSF infusion in humans downregulated its receptor (CD114) on neutrophils by 75% [PMID:11091218]. Curators label the effect stimulatory; GtoPdb lists agonist [DB:GtoPdb].","molecular_requirements":"Two G-CSF and two receptor molecules form the complex, via Ig-like domain cross-over [PMID:16492764]; the BN-BC domains are the principal ligand-binding region [PMID:10537111]. Arg288 of the receptor interacts with Glu19 of G-CSF; a chimera lacking the Ig domain bound G-CSF but did not signal, consistent with a lost binding site and failed dimerisation [PMID:10364174]. No other co-receptor is reported.","affinity_potency":[],"species_and_systems":"Human proteins in the 2.8 A crystal structure [PMID:16492764] and in vivo in eight healthy human volunteers [PMID:11091218]. A mouse pair is ortholog-inferred.","localisation_and_range":"Ligand annotated secreted, non-transmembrane; receptor transmembrane [flag]; systemic and neutrophil receptor effects are shown in vivo [PMID:11091218].","caveats":"Abstracts only. The receptor is downregulated by G-CSF in vivo, which may matter for expression-based scoring [PMID:11091218]. The 1999 mutagenesis paper species is listed as unspecified.","key_references":[{"PMID":"16492764","why":"2.8 A structure of the human GCSF/GCSF-R complex"},{"PMID":"10537111","why":"Crystal structure of GCSF with BN-BC receptor domains"},{"PMID":"11091218","why":"G-CSF downregulates CD114 in humans"}],"covers":["LR000379","LR003885"]},"LR003894":{"pair":"CTHRC1 -> FZD3","headline":"CTHRC1 co-precipitates with Fzd3 in HEK293 cells and modulates Wnt/PCP signalling; one full-text paper.","interaction_type":"direct binding","direction_and_effect":"Cthrc1 co-precipitated with Fzd3 in HEK293 cells, indicating interaction with multiple Fzd proteins; no binding to Smo or to C-terminally truncated Cthrc1 [PMID:18606138]. In HEK293T cells Cthrc1 activated the PCP pathway but suppressed canonical Wnt signalling [PMID:18606138].","molecular_requirements":"Cthrc1 forms a Cthrc1-Wnt-Fzd/Ror2 complex and enhances Wnt-Fzd/Ror2 interaction; it also bound Wnt3a, Wnt5a and Wnt11 [PMID:18606138]. Cthrc1 did not coprecipitate with LRP6 [PMID:18606138].","affinity_potency":[],"species_and_systems":"Co-IP in HEK293 cells; mouse knockout (Cthrc1 LacZ) and Vangl2 genetic interaction; curator labels list human species for the proteins, mouse pair ortholog-inferred [PMID:18606138].","localisation_and_range":"CTHRC1 flagged secreted [flag]; the paper describes cell-surface-anchored Cthrc1 binding [PMID:18606138].","caveats":"Co-IP shows association, not affinity or direct binding to purified protein; overexpression in cells. Single paper; Fzd paralogs bind similarly, so specificity among Fzd3/5/6 is not shown.","key_references":[{"PMID":"18606138","why":"Cthrc1 binds Fzd proteins and Ror2 and stabilizes the Wnt-receptor complex"}],"covers":["LR000388","LR003894"]},"LR009690":{"pair":"CXCL12 -> SDC4","headline":"One abstract-only paper: syndecan-4 contributes to CXCL12-driven HeLa invasion, probably via heparan sulfate; direct binding is not shown.","interaction_type":"functional only","direction_and_effect":"Down-regulating syndecan-4 decreased SDF-1/CXCL12-mediated HeLa cell invasion; the invasion is dependent on CXCR4 [PMID:19695308]. Syndecan-4 appears to present the chemokine rather than signal.","molecular_requirements":"Needs heparan sulfate chains: heparin, anti-heparan sulfate antibodies or beta-D-xyloside inhibited invasion; the authors say glycosaminoglycans are 'probably on syndecan-4' [PMID:19695308]. CXCR4 remains the signalling receptor.","affinity_potency":[],"species_and_systems":"Human cervix epitheloid carcinoma HeLa cells; knockdown by RNA interference [PMID:19695308].","localisation_and_range":"CXCL12 is flagged secreted [flag]; syndecan-4 is a membrane proteoglycan acting at the cell surface (inferred from heparan sulfate role, not stated).","caveats":"Abstract only; the curator labelled direct_binding but only functional knockdown data are reported. No affinity. Review_only paper also judged.","key_references":[{"PMID":"19695308","why":"Only paper: syndecan-4 knockdown reduces CXCL12 invasion"}],"covers":["LR009690"]},"LR005739":{"pair":"CXCL13 -> ACKR1","headline":"One full-text paper: CXCL13 binds the Duffy antigen (ACKR1) weakly, per the curator; homeostatic chemokines bound poorly.","interaction_type":"direct binding","direction_and_effect":"Duffy antigen on human erythrocytes bound chemokines in radioligand displacement; homeostatic chemokines did not bind with high affinity [PMID:15358176]. The curator records weak binding for this pair; signalling effect is not reported in our evidence.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[{"value":"Ki 304.5 nM","assay":"125I-CXCL8 displacement binding","system":"human erythrocytes","cite":"PMID:15358176"}],"species_and_systems":"Human erythrocytes and synovial tissue; human chemokine and receptor. The mouse pair is projected from human [PMID:15358176].","localisation_and_range":"CXCL13 is flagged secreted and ACKR1 transmembrane [flag].","caveats":"The paper's weak category is Ki 100 nM to 1 uM; the Ki is taken from the curator's note since Table 1 is not in the excerpts. Evidence sentence is generic. Dossier text does not name CXCL13 itself.","key_references":[{"PMID":"15358176","why":"Duffy antigen chemokine binding profile"}],"covers":["LR002465","LR005739"]},"LR005748":{"pair":"DAG1 -> CELSR3","headline":"Dystroglycan binds the Celsr3 LG1 domain in vitro and the pair matters for axon guidance in vivo; one paper.","interaction_type":"direct binding","direction_and_effect":"Dystroglycan is reported to act mainly as an extracellular scaffold, non-cell-autonomously and without its intracellular domain; Celsr3 is a binding partner needed for specific axon guidance events in vivo [PMID:30758284]. Agonist/antagonist role not reported in our evidence.","molecular_requirements":"Dystroglycan-Fc bound Celsr3-LG1 but not Celsr3-LG2; AP-Celsr3-LG1 pulled down endogenous glycosylated Dystroglycan from brain lysate. The full-length Celsr3 extracellular domain could not be produced, so binding used isolated LG domains [PMID:30758284].","affinity_potency":[],"species_and_systems":"Recombinant fusion proteins, brain lysate and COS7 cells expressing full-length Dystroglycan (5 nM AP-Celsr3-LG1); in vivo axon guidance. Curator-recorded experiment species is human; the mouse pair is the species-native record, human is ortholog-projected [PMID:30758284].","localisation_and_range":"Dystroglycan is flagged secreted, transmembrane and receptor [flag]; Celsr3 is flagged transmembrane [flag]. Direction is ambiguous: both partners carry receptor flags.","caveats":"Domain-fragment binding only; no affinity reported in our evidence; one paper (abstract plus excerpts).","key_references":[{"PMID":"30758284","why":"Dystroglycan-Celsr3 LG1 binding and in vivo axon guidance role"}],"covers":["LR002474","LR005748"]},"LR007188":{"pair":"DHH -> GAS1:PTCH1","headline":"No direct evidence for this complex: the one judged paper is a negative, and support is a UniProt statement for PTCH1 alone.","interaction_type":"database-asserted only","direction_and_effect":"UniProt states DHH acts by binding the patched receptor (PTCH1 or PTCH2), relieving smoothened inhibition [DB:UniProt]. A 2026 tilapia paper identified a Dhh/Ptch2 axis, with Ptch2 likely the functional receptor for Dhh [PMID:42371991].","molecular_requirements":"Whether GAS1 and PTCH1 act together as a receptor unit for DHH is not reported in our evidence. UniProt records two PTCH1 molecules engaging one hedgehog (SHH, IHH and DHH) molecule [DB:UniProt].","affinity_potency":[],"species_and_systems":"The judged paper used Nile tilapia, a fish; no human or mouse experiments for this complex are in our evidence [PMID:42371991].","localisation_and_range":"Both partners carry transmembrane flags [flag]; range not addressed in the paper text.","caveats":"The paper was judged pair-absent (abstract only) and a second row was abstract-insufficient [PMID:42371991]. The complex rests on database records of the single chain PTCH1; treat as unsupported.","key_references":[{"PMID":"42371991","why":"Negative: points to Ptch2, not this complex, in tilapia"}],"covers":["LR007188"]},"LR007917":{"pair":"DKK1 -> KREMEN2:LRP6","headline":"No curator-verified paper; support rests on database records for the DKK1-LRP6 chain.","interaction_type":"database-asserted only","direction_and_effect":"Database records show DKK1-LRP6 binding by pull-down, reconstituted complex and crystal structure [DB:BioGRID] [DB:IntAct] [DB:PDB 3S2K]. No verified paper for the KREMEN2 component of this complex is in our evidence.","molecular_requirements":"The records describe DKK1 and LRP6 only; KREMEN2 involvement in this complex is not shown here. Reactome lists KRM:DKK:LRP5/6 [DB:Reactome R-HSA-3769399].","affinity_potency":[],"species_and_systems":"Not reported in our evidence.","localisation_and_range":"Both partners are flagged transmembrane or receptor in the entity annotation; DKK1 secreted [flag].","caveats":"Three paper rows were abstract-insufficient, so no paper verifies this complex.","key_references":[],"covers":["LR007917"]},"LR005757":{"pair":"DKK3 -> KREMEN1","headline":"DKK3 interacts with Krm1 in one 2010 paper using biochemical and functional assays; single-paper support.","interaction_type":"direct binding","direction_and_effect":"Dkk3 interacts with Krm1 and Krm2, contrary to earlier studies; Krm2 abolished Dkk3-mediated potentiation of Wnt signalling [PMID:20370576]. Curator direction is agonist for the Dkk3 pro-Wnt effect.","molecular_requirements":"Dkk3 did not interact with, or alter expression of, LRP6, so LRP6 is not needed for this binding; blocking glycosylation did not change the Dkk3-Krm interaction [PMID:20370576].","affinity_potency":[],"species_and_systems":"Human proteins per the curator record; the mouse pair is listed and the human pair is ortholog-inferred [PMID:20370576]. Specific cell system not recorded.","localisation_and_range":"Membrane-bound Kremen receptor; DKK3 flagged secreted [flag]. Range not otherwise reported.","caveats":"One paper only, no database record. Affinity not reported in our evidence. Earlier studies reported no such interaction, per this paper [PMID:20370576].","key_references":[{"PMID":"20370576","why":"Dkk3 interacts with Krm1 and Krm2, not LRP6"}],"covers":["LR002489","LR005757"]},"LR001779":{"pair":"DKK4 -> KREMEN1","headline":"DKK4 CRD2 binds the Kremen1 extracellular domain with high affinity in a structural/binding study; one paper.","interaction_type":"direct binding","direction_and_effect":"Dkk4 cysteine-rich domain 2 (CRD2) mediates high-affinity binding to the Kremen1 extracellular domain; Dkk and Krm function synergistically to inhibit Wnt signalling [PMID:29925589]. Curator effect: antagonist.","molecular_requirements":"CRD2 is the Krm-binding region; the N-terminal region alone did not interact with Krm proteins [PMID:29925589]. Ternary Dkk-Krm-LRP5/6 complexes are proposed [PMID:29925589].","affinity_potency":[],"species_and_systems":"Human proteins, recombinant NMR/binding study; the human pair is not ortholog-inferred, the mouse pair is [PMID:29925589].","localisation_and_range":"Soluble recombinant domains used; Kremen1 is a transmembrane receptor [flag].","caveats":"One paper. The excerpt gives affinities only for other Dkks from earlier work, not for Dkk4, and no Dkk4 value is stated in our evidence [PMID:29925589]. No database record.","key_references":[{"PMID":"29925589","why":"Dkk4 CRD2 binds Krm1 ectodomain and LRP6 E1E2"}],"covers":["LR001779","LR005135"]},"LR003939":{"pair":"DLK2 -> NOTCH1","headline":"DLK2 interacts with the same NOTCH1 region as DLK1 and inhibits NOTCH signalling; one abstract-read paper.","interaction_type":"direct binding","direction_and_effect":"DLK2 interacts with itself, with DLK1 and with the same NOTCH1 receptor region as DLK1, inhibiting basal NOTCH signalling in preadipocytes and mouse embryo fibroblasts; DLK1 and DLK2 decrease activity even when triggered by canonical ligands, and each reverses the other's effect [PMID:21419176].","molecular_requirements":"DLK1 co-presence modulates the effect: DLK2-induced decrease is reversed by DLK1 overexpression and vice versa [PMID:21419176].","affinity_potency":[],"species_and_systems":"Preadipocytes and mouse embryo fibroblasts; human pair ortholog-inferred, mouse pair direct [PMID:21419176].","localisation_and_range":"DLK2 flagged not secreted [flag]; contact-type action is not stated in our evidence.","caveats":"Abstract only; single paper; no database record; no affinity reported.","key_references":[{"PMID":"21419176","why":"DLK2 binds NOTCH1 region and inhibits NOTCH"}],"covers":["LR000447","LR003939"]},"LR007377":{"pair":"DLL3 -> NOTCH2","headline":"Single abstract-only mouse paper reports DLL3 binding and activating Notch2 in oocytes; no direct binding data.","interaction_type":"functional only","direction_and_effect":"The paper states activated DLL3 binds and activates Notch2, which is cleaved to release NICD2 [PMID:34635817]. Listed effect is stimulatory [flag].","molecular_requirements":"DLL3 is described as needing prior ubiquitination and activation by membrane-anchored MIB2, itself anchored by Gm364 [PMID:34635817]. Receptor-chain requirements not reported in our evidence.","affinity_potency":[],"species_and_systems":"Mouse oocytes/ovary from Gm364 knockout mice; the human pair is the listed record [PMID:34635817].","localisation_and_range":"DLL3 and NOTCH2 are both annotated transmembrane, DLL3 not secreted [flag], so any signalling would be juxtacrine; the paper itself does not address range.","caveats":"Abstract read only. The DLL3-Notch2 step is a mechanistic statement within a knockout study, not a binding assay. Three further papers were review-only and two abstract-insufficient.","key_references":[{"PMID":"34635817","why":"Only paper; Gm364/MIB2/DLL3/Notch2 axis in mouse oocytes"}],"covers":["LR007377"]},"LR001788":{"pair":"DSC2 -> DSG2","headline":"DSC2 -> DSG2: heterophilic desmosomal cadherin binding, supported by a single family-wide paper.","interaction_type":"direct binding","direction_and_effect":"The paper reports that all desmogleins form adhesive dimers with all desmocollins, with affinities characteristic of each Dsg:Dsc pair, so this pair is covered by the family-wise heterophilic result [PMID:27298358]. Binding is trans-cellular and heterodimers are called the fundamental adhesive unit of desmosomes [PMID:27298358].","molecular_requirements":"Ectodomains of one Dsg and one Dsc are sufficient for dimer formation in the reported solution biophysics and bead aggregation; binding uses a strand-swap mechanism with charge-based heterophilic preference [PMID:27298358]. No further subunits or co-receptors reported.","affinity_potency":[],"species_and_systems":"Experiments used human proteins (solution biophysics, SPR and coated-bead aggregation) [PMID:27298358]. Pair is recorded for: human, mouse (ortholog-projected). The mouse entry is projected from human evidence.","localisation_and_range":"Membrane-bound desmosomal cadherins acting in trans between adjacent cells (juxtacrine/contact) [PMID:27298358]; entity flags mark both as receptors and transmembrane where set [flag].","caveats":"Curators read only the abstract; the paper's family-wide statement is applied to this pair, one of 25 companion rows, and no pair-specific affinity is in our dossier. The crystal structures cited cover Dsg2, Dsg3, Dsc1 and Dsc2 only [PMID:27298358]. Database records also exist (BioGRID, IntAct, PDB, UniProt), which are not independent of the evidence above. [DB:BioGRID] [DB:IntAct] [DB:PDB 5J5J] [DB:PDB 7A7D] [DB:UniProt]","key_references":[{"PMID":"27298358","why":"Family-wise Dsg:Dsc heterophilic binding by biophysics, SPR, bead aggregation and crystal structures"}],"covers":["LR001788","LR005144"]},"LR008385":{"pair":"DSCAM -> PTPRM","headline":"DSCAM binds PTPRM by SPR in a high-throughput human IgSF interactome study; single paper.","interaction_type":"direct binding","direction_and_effect":"The study reports binding of DSCAM-CT and DSCAML1-CT to PTPRT and PTPRM by SPR [PMID:32822567]. Signalling direction or effect is not reported in our evidence.","molecular_requirements":"Only the C-terminal ectodomain region (DSCAM-CT) was tested as analyte against PTPRs as ligands; subunit or co-receptor requirements not reported in our evidence [PMID:32822567].","affinity_potency":[],"species_and_systems":"Human recombinant proteins; SPR at 2-fold dilutions from 16 to 2,048 nM, following an ELISA-based pooled screen [PMID:32822567].","localisation_and_range":"Not reported by the paper beyond ectodomain-level binding. Entity flags mark DSCAM as secreted, transmembrane and a receptor, an annotation-only flag [flag].","caveats":"Sensorgram binding only; no Kd is given in our excerpts. Pairs from the same SPR panel (e.g. PTPRK) were untested for lack of protein. The sentence covers both DSCAM and DSCAML1 and both PTPRT and PTPRM, so this row inherits a shared statement [PMID:32822567].","key_references":[{"PMID":"32822567","why":"Human IgSF cell-surface interactome with SPR validation of DSCAM/DSCAML1 with PTPRT/PTPRM"}],"covers":["LR008385"]},"LR005766":{"pair":"DSCAM -> UNC5C","headline":"DSCAM associates with UNC5C, stimulated by netrin-1, in neurons; co-association evidence at abstract level plus UniProt.","interaction_type":"direct binding","direction_and_effect":"DSCAM interacts with UNC5C and netrin-1 stimulates the interaction in primary cortical neurons and postnatal cerebellar granule cells [PMID:22685302]. Knockdown of either, or dominant-negative mutants, suppressed netrin-1-induced growth-cone collapse in mouse cerebellar EGL cells [PMID:22685302].","molecular_requirements":"UniProt records an interaction of the DSCAM extracellular domain with the UNC5C Ig-like C2-type domain, citing this paper [DB:UniProt]. Netrin-1 acts as a stimulus; Src-family kinase inhibition reduced the DSCAM-UNC5C interaction [PMID:22685302].","affinity_potency":[],"species_and_systems":"Primary neurons and brain tissue, with mouse cerebellar EGL cells used for collapse assays [PMID:22685302]. The curator labels both partners as human; the abstract names no species for the co-association, so treat species as unclear. Pair also recorded for mouse (projected).","localisation_and_range":"Transmembrane receptors on neurons, partly co-localised in primary neurons and brain tissue [PMID:22685302]; DSCAM also carries a secreted flag [flag].","caveats":"Abstract read only; the interaction is shown as association in cells (stimulated by netrin-1), not as binding of purified proteins, and may be indirect or netrin-mediated. UniProt's domain assignment rests on the same paper [DB:UniProt].","key_references":[{"PMID":"22685302","why":"DSCAM-UNC5C association and role in netrin-1 growth-cone collapse"}],"covers":["LR002498","LR005766"]},"LR008394":{"pair":"DSCAML1 -> PTPRT","headline":"DSCAML1 binds PTPRT by SPR in a high-throughput human IgSF interactome study; single paper.","interaction_type":"direct binding","direction_and_effect":"The study reports binding of DSCAM-CT and DSCAML1-CT to PTPRT and PTPRM by SPR [PMID:32822567]. Signalling direction or effect is not reported in our evidence.","molecular_requirements":"Only the C-terminal ectodomain region (DSCAML1-CT) was tested as analyte against PTPRs as ligands; subunit or co-receptor requirements not reported in our evidence [PMID:32822567].","affinity_potency":[],"species_and_systems":"Human recombinant proteins; SPR at 2-fold dilutions from 16 to 2,048 nM, following an ELISA-based pooled screen [PMID:32822567].","localisation_and_range":"Not reported by the paper beyond ectodomain-level binding. Entity flags mark the receptor as a receptor [flag]; no flags for the ligand.","caveats":"Sensorgram binding only; no Kd is given in our excerpts. Pairs from the same SPR panel (e.g. PTPRK) were untested for lack of protein. The sentence covers both DSCAM and DSCAML1 and both PTPRT and PTPRM, so this row inherits a shared statement [PMID:32822567].","key_references":[{"PMID":"32822567","why":"Human IgSF cell-surface interactome with SPR validation of DSCAM/DSCAML1 with PTPRT/PTPRM"}],"covers":["LR008394"]},"LR002499":{"pair":"DSG1 -> DSC1","headline":"DSG1 -> DSC1: heterophilic desmosomal cadherin binding, supported by a single family-wide paper.","interaction_type":"direct binding","direction_and_effect":"The paper reports that all desmogleins form adhesive dimers with all desmocollins, with affinities characteristic of each Dsg:Dsc pair, so this pair is covered by the family-wise heterophilic result [PMID:27298358]. Binding is trans-cellular and heterodimers are called the fundamental adhesive unit of desmosomes [PMID:27298358].","molecular_requirements":"Ectodomains of one Dsg and one Dsc are sufficient for dimer formation in the reported solution biophysics and bead aggregation; binding uses a strand-swap mechanism with charge-based heterophilic preference [PMID:27298358]. No further subunits or co-receptors reported.","affinity_potency":[],"species_and_systems":"Experiments used human proteins (solution biophysics, SPR and coated-bead aggregation) [PMID:27298358]. Pair is recorded for: human.","localisation_and_range":"Membrane-bound desmosomal cadherins acting in trans between adjacent cells (juxtacrine/contact) [PMID:27298358]; entity flags mark both as receptors and transmembrane where set [flag].","caveats":"Curators read only the abstract; the paper's family-wide statement is applied to this pair, one of 25 companion rows, and no pair-specific affinity is in our dossier. The crystal structures cited cover Dsg2, Dsg3, Dsc1 and Dsc2 only [PMID:27298358]. Database records also exist (BioGRID, IntAct, UniProt), which are not independent of the evidence above. [DB:BioGRID] [DB:IntAct] [DB:UniProt] UniProt also lists a cytoplasmic-region interaction between these two proteins [DB:UniProt]; that is a different interface from the ectodomain binding above.","key_references":[{"PMID":"27298358","why":"Family-wise Dsg:Dsc heterophilic binding by biophysics, SPR, bead aggregation and crystal structures"}],"covers":["LR002499"]},"LR001797":{"pair":"DSG2 -> DSC3","headline":"DSG2 -> DSC3: heterophilic desmosomal cadherin binding, supported by a single family-wide paper.","interaction_type":"direct binding","direction_and_effect":"The paper reports that all desmogleins form adhesive dimers with all desmocollins, with affinities characteristic of each Dsg:Dsc pair, so this pair is covered by the family-wise heterophilic result [PMID:27298358]. Binding is trans-cellular and heterodimers are called the fundamental adhesive unit of desmosomes [PMID:27298358].","molecular_requirements":"Ectodomains of one Dsg and one Dsc are sufficient for dimer formation in the reported solution biophysics and bead aggregation; binding uses a strand-swap mechanism with charge-based heterophilic preference [PMID:27298358]. No further subunits or co-receptors reported.","affinity_potency":[],"species_and_systems":"Experiments used human proteins (solution biophysics, SPR and coated-bead aggregation) [PMID:27298358]. Pair is recorded for: human, mouse (ortholog-projected). The mouse entry is projected from human evidence.","localisation_and_range":"Membrane-bound desmosomal cadherins acting in trans between adjacent cells (juxtacrine/contact) [PMID:27298358]; entity flags mark both as receptors and transmembrane where set [flag].","caveats":"Curators read only the abstract; the paper's family-wide statement is applied to this pair, one of 25 companion rows, and no pair-specific affinity is in our dossier. The crystal structures cited cover Dsg2, Dsg3, Dsc1 and Dsc2 only [PMID:27298358]. Database records also exist (IntAct), which are not independent of the evidence above. [DB:IntAct]","key_references":[{"PMID":"27298358","why":"Family-wise Dsg:Dsc heterophilic binding by biophysics, SPR, bead aggregation and crystal structures"}],"covers":["LR001797","LR005153"]},"LR003948":{"pair":"EDA -> EDA2R","headline":"The EDA-A2 splice isoform activates EDA2R (XEDAR); evidence is functional plus isoform-specific binding.","interaction_type":"direct binding","direction_and_effect":"EDA-A2 binds only XEDAR (EDA2R), not EDAR [PMID:11039935]. In 293F cells expressing XEDAR, EDA-A2 activated NF-kappaB and JNK [PMID:12270937].","molecular_requirements":"Signalling recruits TRAF3 and TRAF6; NF-kappaB needs IKK1, IKK2 and NEMO, and JNK needs TRAF3, TRAF6 and ASK1 [PMID:12270937]. Only the A2 isoform acts on this receptor.","affinity_potency":[],"species_and_systems":"Human proteins, in situ binding and 293F cells; mouse pair is ortholog-inferred.","localisation_and_range":"Not reported beyond UniProt noting it functions as a ligand [DB:UniProt].","caveats":"PMID:11039935 shows EDA-A1 binds only EDAR and EDA-A2 only XEDAR, so isoform matters. A gene-level EDA->EDA2R row hides this. Both papers abstract only; PMID:12270937 reports no binding assay.","key_references":[{"PMID":"11039935","why":"Isoform-specific binding of EDA-A2 to XEDAR"},{"PMID":"12270937","why":"EDA-A2 activates XEDAR signalling"}],"covers":["LR000457","LR003948"]},"LR005775":{"pair":"EDIL3 -> ITGAL","headline":"Del-1 (EDIL3) interferes with LFA-1-dependent leukocyte-endothelial adhesion; functional only.","interaction_type":"functional only","direction_and_effect":"Antagonist: Del-1 interferes with LFA-1-dependent leukocyte-endothelial adhesion in Del-1 and Del-1/LFA-1 double-deficient mice [PMID:19008446].","molecular_requirements":"Chain-only: LFA-1 is ITGAL plus ITGB2; the partner chain is not reported in this paper's abstract.","affinity_potency":[],"species_and_systems":"Mouse in vitro and in vivo (the mouse pair is the direct one; the human pair is ortholog-inferred).","localisation_and_range":"Not reported in our evidence.","caveats":"Abstract only; a direct binding assay is not stated, and the curator notes it is functional interference.","key_references":[{"PMID":"19008446","why":"Del-1 interferes with LFA-1-dependent adhesion"}],"covers":["LR002507","LR005775"]},"LR003957":{"pair":"EFEMP1 -> EGFR","headline":"EFEMP1 reported to bind EGFR and activate it in pancreatic cancer cells; single abstract-read paper.","interaction_type":"direct binding","direction_and_effect":"EFEMP1 binds EGFR competitively with EGF, suggesting shared or adjacent sites; purified EFEMP1 activates EGFR autophosphorylation at Tyr-992 and Tyr-1068 but not Tyr-1048, and downstream Akt and MAPK, all blocked by the EGFR kinase inhibitor PD153035 [PMID:19804359]. Agonist.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human pancreatic carcinoma cells with purified EFEMP1 [PMID:19804359]; mouse pair ortholog-inferred.","localisation_and_range":"EFEMP1 is annotated secreted [flag]; paracrine ligand acting on a membrane receptor.","caveats":"One paper, abstract only, one lab; no affinity reported and no independent confirmation. Mouse pair untested.","key_references":[{"PMID":"19804359","why":"EFEMP1 binds EGFR and activates MAPK/Akt"}],"covers":["LR000466","LR003957"]},"LR003975":{"pair":"EFNA3 -> EPHA2","headline":"Ephrin-A3 binds EphA2 by ELISA, with a functional readout in dendritic cells; moderately supported.","interaction_type":"direct binding","direction_and_effect":"Ephrin-A3-Fc bound dendritic-cell surface EphA2 and increased adhesion to fibronectin (not poly-L-lysine) via beta1 integrin activation [PMID:12907451]. Ephrin-A3 AP binds EphA2, less well than EphA3, EphA5 and EphA7 [PMID:22568954].","molecular_requirements":"Not reported beyond the recombinant ligand-receptor pair.","affinity_potency":[],"species_and_systems":"ELISA with ephrin-A3 AP and EphA Fc proteins, species unspecified [PMID:22568954]; human CD34+-derived dendritic cells [PMID:12907451]. Mouse pair is ortholog-inferred.","localisation_and_range":"EFNA3 and EPHA2 are both flagged transmembrane [flag]; the dendritic-cell result concerns a ligand-Fc fusion.","caveats":"The adhesion effect is an indirect, substrate-specific readout through integrin activation, and one paper was a browser read with an unverifiable quote [PMID:22568954]. BioGRID lists affinity capture-MS and Western records [DB:BioGRID]. One further judgement is pending.","key_references":[{"PMID":"22568954","why":"ELISA ranking of ephrin-A3 binding across EphA receptors"},{"PMID":"12907451","why":"Ephrin-A3-Fc binds EphA2 on dendritic cells and alters adhesion"}],"covers":["LR000484","LR003975"]},"LR003984":{"pair":"EFNA4 -> EPHA3","headline":"No verified paper; only a BioGRID reconstituted-complex record supports the pair.","interaction_type":"database-asserted only","direction_and_effect":"BioGRID lists an EPHA3-EFNA4 reconstituted complex [DB:BioGRID, PMID:9195962]. Effect not reported in our evidence.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Experimental species not reported in our evidence; the human pair is ortholog-inferred from mouse.","localisation_and_range":"Both flagged secreted and transmembrane [flag]; annotation only.","caveats":"All judged papers were review-only or abstract-insufficient, so no paper confirms it.","key_references":[],"covers":["LR000493","LR003984"]},"LR003993":{"pair":"EFNA5 -> EPHA4","headline":"Ephrin-A5 binds and activates EphA4, supported by crystal structures and mouse cochlea genetics.","interaction_type":"direct binding","direction_and_effect":"EphA4 is activated by both A- and B-class ephrins; crystal structures of the EphA4 ectodomain with ephrin-A5 show ligand binding induces conformational changes [PMID:23959867]. Complementary ephrin-A5 and EphA4 expression controls afferent fibre targeting in mouse cochlea; loss of either causes overshooting [PMID:23385583]. Ephrin-A5 Fc binds most EphA receptors with high apparent affinity [PMID:22568954].","molecular_requirements":"An EphA4 ligand-binding-domain interaction with its own fibronectin domain matters for efficient activation [PMID:23959867].","affinity_potency":[],"species_and_systems":"Human structures [PMID:23959867]; mouse in vivo [PMID:23385583]; ELISA, species unspecified [PMID:22568954]. Mouse pair listed as direct.","localisation_and_range":"Both flagged membrane-bound [flag].","caveats":"Mostly abstract-only reads; 22568954 was a browser read with unverifiable quote. IntAct and PDB records exist [DB:PDB 4BK5].","key_references":[{"PMID":"23959867","why":"EphA4-ephrin-A5 crystal structures"},{"PMID":"23385583","why":"Ephrin-A5/EphA4 repulsion in cochlear afferent targeting"},{"PMID":"22568954","why":"ELISA across EphA receptors"}],"covers":["LR000502","LR003993"]},"LR005793":{"pair":"EGFL7 -> ITGAV","headline":"EGFL7 is reported as an alpha-v beta-3 integrin ligand supporting T-cell adhesion; abstract-level evidence.","interaction_type":"functional only","direction_and_effect":"Activated T cells adhere to EGFL7 through integrin alphavbeta3; EGFL7 loss worsens and recombinant EGFL7 improves EAE in mice, so EGFL7 limits CNS immune infiltration [PMID:29483510]. Curators label it antagonist.","molecular_requirements":"The receptor is the alphaVbeta3 heterodimer; both ITGAV and ITGB3 are needed [PMID:29483510].","affinity_potency":[],"species_and_systems":"Human and mouse activated T cells; MS patient tissue and EAE mice [PMID:29483510].","localisation_and_range":"EGFL7 is ECM-bound and secreted by endothelial cells (matrix, contact range) [PMID:29483510][flag].","caveats":"Single paper, abstract only; adhesion rather than a binding measurement; no affinity. Support is functional, not biophysical.","key_references":[{"PMID":"29483510","why":"T cell adhesion to EGFL7 through alphavbeta3; EAE phenotypes"}],"covers":["LR002525","LR005793"]},"LR005829":{"pair":"EPHA5 -> EFNA5","headline":"Eph/ephrin-A pair supported only by two IntAct co-purification records and a UniProt statement; no verified paper.","interaction_type":"database-asserted only","direction_and_effect":"UniProt states that the interaction of EFNA5 with EPHA5 mediates communication between pancreatic islet cells to regulate glucose-stimulated insulin secretion [DB:UniProt]. Direction and agonist/antagonist role are not reported beyond this. Both partners carry the receptor annotation flag [flag], so ligand/receptor direction is not established by our evidence.","molecular_requirements":"Subunit or co-receptor requirements: not reported in our evidence.","affinity_potency":[],"species_and_systems":"No paper was verified for this pair; species and experimental system of the database records are not reported in our evidence.","localisation_and_range":"Both partners are annotated as transmembrane [flag], so any interaction would be juxtacrine (cell contact); this comes from annotation flags only.","caveats":"No curator-verified paper; support is database records only. IntAct lists association by affinity chromatography [DB:IntAct EBI-32717888] and by anti-tag coimmunoprecipitation [DB:IntAct EBI-54501476], which show association rather than a defined direct binding. Affinity not reported in our evidence.","key_references":[],"covers":["LR002561","LR005829"]},"LR005838":{"pair":"EPHA7 -> EFNA4","headline":"Database-only pair: IntAct comigration in SDS-PAGE records; no verified paper.","interaction_type":"database-asserted only","direction_and_effect":"Direction and effect are not reported. Both partners carry the receptor annotation flag [flag], so ligand/receptor direction is not established by our evidence.","molecular_requirements":"Requirements: not reported in our evidence.","affinity_potency":[],"species_and_systems":"No paper was verified for this pair; species and experimental system of the database records are not reported in our evidence.","localisation_and_range":"Both partners carry secreted and transmembrane flags [flag]; range is unclear.","caveats":"No curator-verified paper; support is database records only. IntAct records one entry described as direct interaction by comigration in SDS-PAGE [DB:IntAct EBI-5241581] and a second comigration entry [DB:IntAct Q15375-P52798]; this is a weak assay type for binding. Affinity not reported in our evidence.","key_references":[],"covers":["LR002570","LR005838"]},"LR005847":{"pair":"EPHB1 -> EFNB2","headline":"UniProt-only claim that EFNB2 is a cognate ligand for EPHB1; no verified paper.","interaction_type":"database-asserted only","direction_and_effect":"UniProt (EPHB1 entry) states cognate/functional ephrin ligands include EFNB1, EFNB2 and EFNB3 [DB:UniProt]. Effect is not reported. Both partners carry the receptor annotation flag [flag], so ligand/receptor direction is not established by our evidence.","molecular_requirements":"Requirements: not reported in our evidence.","affinity_potency":[],"species_and_systems":"No paper was verified for this pair; species and experimental system of the database records are not reported in our evidence.","localisation_and_range":"Both partners are annotated as transmembrane [flag], so any interaction would be juxtacrine (cell contact); this comes from annotation flags only.","caveats":"No curator-verified paper; support is database records only. Only one UniProt sentence; no assay or affinity in our evidence. Four papers were review-only.","key_references":[],"covers":["LR002579","LR005847"]},"LR005856":{"pair":"EPHB2 -> EFNB3","headline":"EphB2-ephrin-B3 supported by one ELISA paper (weak binding) and one neuronal functional paper; no database records.","interaction_type":"functional only","direction_and_effect":"Ephrin-B3 Fc binds most weakly of the ephrin-Bs to all EphB receptors in ELISA [PMID:22568954]. In cultured cortical neurons, a trans-synaptic EphB2 (presynaptic) to ephrin-B3 (postsynaptic) interaction regulates excitatory synapse density; ephrin-B3 is reported to limit synapse density by directly binding Erk1/2 and inhibiting Ras/MAPK signalling [PMID:20410461]. The curator labels the effect antagonist.","molecular_requirements":"Not reported in our evidence beyond the two partners. Ephrin-B3 is reported to bind heparan sulfate proteoglycans [PMID:22568954].","affinity_potency":[],"species_and_systems":"Cultured cortical neurons; curator records human for both partners, but the abstract does not state the species [PMID:20410461]. ELISA with Fc proteins, species unspecified [PMID:22568954].","localisation_and_range":"Trans-synaptic, contact-dependent signalling [PMID:20410461]. Both partners transmembrane-flagged [flag].","caveats":"Both papers were read as abstracts or by browser; the ELISA quote is marked unverifiable pending spot-check. The binding paper reports the weakest binding for this ephrin; apparent KD values are in a figure not in our evidence. The functional paper's output runs through ephrin-B3 intracellular binding of Erk1/2, so it does not by itself test EphB2 binding.","key_references":[{"PMID":"20410461","why":"Trans-synaptic EphB2-ephrin-B3 regulation of synapse density, abstract."},{"PMID":"22568954","why":"ELISA: ephrin-B3 Fc binds EphB receptors most weakly."}],"covers":["LR002588","LR005856"]},"LR002589":{"pair":"EPHB2 -> EPHB2","headline":"EphB2 self-association evidence is structural database records; the one paper concerns EphB2-ephrinB1 repulsion, not homotypic binding.","interaction_type":"conflicting","direction_and_effect":"In cell-culture and simulation work, EphB2-, kinase-inactive EphB2- and ephrinB1-expressing cells show strong heterotypic and weak homotypic repulsion [PMID:28747399]. This paper therefore reports weak homotypic EphB2-EphB2 repulsion rather than a ligand-receptor signal.","molecular_requirements":"N-cadherin suppresses homotypic repulsion and enables homotypic cohesion in this system [PMID:28747399]. Kinase activity was not required for segregation (kinase-inactive EphB2 also segregated) [PMID:28747399].","affinity_potency":[],"species_and_systems":"Cell culture assays plus computer simulations; the curator records human for both partners [PMID:28747399].","localisation_and_range":"Membrane-bound receptor on both sides [flag]; the paper describes contact-mediated repulsion between cells [PMID:28747399].","caveats":"Full text was available but the paper does not test a ligand-receptor role for EphB2 with itself. BioGRID lists a co-crystal structure [DB:BioGRID 301995, PMID 9933164] and a biochemical activity record [DB:BioGRID 677324], which show EphB2 self-association but not a ligand-receptor mechanism.","key_references":[{"PMID":"28747399","why":"Weak homotypic versus strong heterotypic repulsion in EphB2 and ephrinB1 cells."}],"covers":["LR002589","LR005857"]},"LR005874":{"pair":"F11R -> ITGB2","headline":"JAM-A binds LFA-1; ITGB2 row inherits evidence for the ITGAL:ITGB2 heterodimer.","interaction_type":"direct binding","direction_and_effect":"JAM-1 is a ligand of LFA-1 [PMID:11812992]; recombinant JAM-A binds the immobilised locked-open alphaL I domain directly [PMID:15528364].","molecular_requirements":"The binding site is on alphaL, not ITGB2 [PMID:15528364]. Beta chain contribution not shown in our evidence; the curator notes subunit rows inherit heterodimer evidence.","affinity_potency":[],"species_and_systems":"Human proteins and cells [PMID:15528364][PMID:11812992]; mouse pair ortholog-inferred [flag]. Reactome records the complex [DB:Reactome].","localisation_and_range":"JAM-A needs redistribution from tight junctions [PMID:11812992].","caveats":"Chain-only caveat: ITGB2 alone is not shown to bind JAM-A. Abstract-level reads.","key_references":[{"PMID":"15528364","why":"Binding site is on alphaL I domain"},{"PMID":"11812992","why":"JAM-1 as LFA-1 ligand"}],"covers":["LR002607","LR005874"]},"LR008187":{"pair":"FCER2 -> ITGAV:ITGB5","headline":"Human CD23 RKC peptides bind alphaVbeta5 by SPR; one paper.","interaction_type":"direct binding","direction_and_effect":"CD23 peptides bind alphaVbeta5 and alphaVbeta3 with biphasic binding; they stimulate pre-B cell growth and monocyte cytokine release [PMID:22560905]. Curator labels effect agonist.","molecular_requirements":"RKC motif from arg172 required; both basic residues needed to abolish activity [PMID:22560905]. Binding is cation-independent, chloride-sensitive.","affinity_potency":[],"species_and_systems":"Human CD23 peptides, purified integrin, human cell lines [PMID:22560905].","localisation_and_range":"CD23 flagged secreted and transmembrane [flag].","caveats":"Single paper; peptides rather than full-length CD23 in SPR; no affinity reported.","key_references":[{"PMID":"22560905","why":"SPR of CD23 RKC peptides with alphaVbeta5"}],"covers":["LR008187"]},"LR007197":{"pair":"FCER2 -> ITGAX:ITGB2","headline":"CD23 binds the CD11c-CD18 complex in transfected cells and activates monocytes; single 1995 paper.","interaction_type":"direct binding","direction_and_effect":"Recombinant CD23 liposomes bound CD11c-CD18 transfectants, inhibited by anti-CD11c and anti-CD23; CD23 caused increases in nitrite-oxidative products, IL-1 beta, IL-6 and TNF alpha in monocytes [PMID:7621072]. Labelled agonist.","molecular_requirements":"CD11c-CD18 heterodimer was tested; CD11a-CD18 not bound [PMID:7621072].","affinity_potency":[],"species_and_systems":"Human CD23, COS transfectants and monocytes.","localisation_and_range":"CD23 flagged secreted and transmembrane [flag].","caveats":"Abstract-only read; no affinity reported. Interaction classed Receptor-Receptor.","key_references":[{"PMID":"7621072","why":"CD23 binding to CD11c-CD18"}],"covers":["LR007197"]},"LR005883":{"pair":"Fcer2a -> Itgam","headline":"CD23 binds CD11b-CD18 on transfected COS cells and drives monocyte activation; human data projected to mouse.","interaction_type":"direct binding","direction_and_effect":"Recombinant CD23 in fluorescent liposomes bound COS cells expressing CD11b-CD18; antibodies to CD11b or CD23 blocked this. CD23 triggering raised nitrite-oxidative products and IL-1 beta, IL-6 and TNF alpha in monocytes, so effect is agonist [PMID:7621072].","molecular_requirements":"Needs the CD11b-CD18 complex; CD11a-CD18 did not bind [PMID:7621072].","affinity_potency":[],"species_and_systems":"Experiments used human CD23 and human integrins (curator fields) in COS transfectants and monocytes; the mouse pair is ortholog-inferred and no mouse experiment is in our evidence.","localisation_and_range":"Fcer2a is flagged secreted and receptor [flag]; binding was shown with liposome-presented full-length CD23 [PMID:7621072].","caveats":"Single paper; abstract plus partial full text. No affinity reported.","key_references":[{"PMID":"7621072","why":"CD23 binds CD11b-CD18 and CD11c-CD18"}],"covers":["LR005883"]},"LR005892":{"pair":"FGF1 -> ITGB3","headline":"FGF1 binds integrin alphaVbeta3 directly, with micromolar affinity; a mutant lacking integrin binding loses signalling.","interaction_type":"direct binding","direction_and_effect":"FGF1 directly bound soluble and cell-surface integrin alphavbeta3; the antagonists 7E3 and cyclic RGDfV blocked this, and an integrin-binding-defective FGF1 mutant (R50E) failed to induce DNA synthesis, proliferation, migration and chemotaxis [PMID:18441324]. Wild-type FGF1 formed an integrin-FGF1-FGFR1 ternary complex that recruited SHP-2; R50E did not [PMID:20422052]. UniProt records the same [DB:UniProt].","molecular_requirements":"The receptor is the alphaV:beta3 heterodimer (UniProt describes ITGAV:ITGB3 binding) [DB:UniProt]; the beta3 specificity loop CYDMKTTC contributes [PMID:18441324]. FGF1 bound several beta1 integrins only weakly [PMID:18441324]. Signalling involves a ternary complex with FGFR1, so FGFR1 expression matters too [PMID:20422052].","affinity_potency":[{"value":"KD about 1 micromolar","assay":"solid-phase and cell-surface binding assay","system":"soluble and cell-surface integrin alphavbeta3","cite":"PMID:18441324"}],"species_and_systems":"Binding assays used soluble and cell-surface alphavbeta3 [PMID:18441324]. Ternary complex shown in mouse NIH 3T3 cells and human umbilical endothelial cells; BaF3 mouse pro-B cells expressed human FGFR1 [PMID:20422052]. The mouse pair is projected from human evidence (ortholog_inferred).","localisation_and_range":"FGF1 is flagged secreted and non-transmembrane; the integrin is a membrane receptor [flag]. Action is paracrine or autocrine via cell-surface integrin, inferred from these flags.","caveats":"Both papers were read as abstracts only (one with some full-text excerpts). Both come from the same research group, so they are not independent. Functional role depends on FGFR1 co-engagement.","key_references":[{"PMID":"18441324","why":"direct binding, KD and R50E mutant"},{"PMID":"20422052","why":"ternary complex with FGFR1 in 3T3 and endothelial cells"}],"covers":["LR002626","LR005892"]},"LR005919":{"pair":"FLRT2 -> UNC5B","headline":"FLRT2 signals through UNC5B to cause endothelial repulsion; binding supported by a binding screen, with one abstract-level negative.","interaction_type":"direct binding","direction_and_effect":"A high-throughput extracellular binding screen found all three FLRTs binding all four Unc5s near saturation (mean Abs650nm value = 2.14), with ELISA titration on purified protein and CHO.K1 cell aggregation [PMID:26633812]. In mice, endothelial FLRT2 knockout caused aberrant endothelial alignment in the placental labyrinth, related to endothelial repulsion through binding to UNC5B [PMID:28576770]; the curated row labels the effect antagonist. UniProt notes UNC5B binds FLRT2 and FLRT3, with higher affinity for FLRT3 [DB:UniProt, PMID:25374360].","molecular_requirements":"Extracellular domains interact [DB:UniProt, PMID:25374360]; co-receptors are not reported in our evidence.","affinity_potency":[],"species_and_systems":"Screen on purified ectodomains and CHO.K1 cells [PMID:26633812]; placental work in mice, with the curated row labelled human [PMID:28576770]. Mouse pair not ortholog-inferred.","localisation_and_range":"FLRT2 flagged secreted and transmembrane [flag]; the placental phenotype is described as inter-endothelial repulsion [PMID:28576770].","caveats":"One abstract-only paper was judged pair_absent because it names FLRT2 as specific to Unc5D and FLRT3 as the Unc5B partner [PMID:21673655]; the later screen contradicts exclusivity. The placental paper was read as abstract only.","key_references":[{"PMID":"26633812","why":"Binding screen covering FLRT2-UNC5B."},{"PMID":"28576770","why":"Endothelial FLRT2/UNC5B repulsion in placenta."}],"covers":["LR002653","LR005919"]},"LR005928":{"pair":"FN1 -> CD248","headline":"Reported direct binding of fibronectin to endosialin/TEM1 from a single abstract-level paper.","interaction_type":"direct binding","direction_and_effect":"Fibronectin and collagen types I and IV were identified as specific ligands of endosialin/TEM1; TEM1-expressing cells showed enhanced adhesion to fibronectin and migration [PMID:17986615]. Described as an adhesion-mediating interaction, with the curator assigning agonist.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human, per curator fields; mouse pair inferred by orthology from human evidence [PMID:17986615].","localisation_and_range":"FN1 is flagged secreted, CD248 transmembrane [flag]; matrix-to-cell contact.","caveats":"One paper, read as an abstract only. The abstract does not give an affinity or binding assay type.","key_references":[{"PMID":"17986615","why":"identifies FN as a specific ligand of endosialin/TEM1"}],"covers":["LR002662","LR005928"]},"LR008493":{"pair":"FPR1 -> ANXA1","headline":"Annexin I N-terminal peptides act as FPR agonists on human neutrophils; stored orientation is receptor-first.","interaction_type":"functional only","direction_and_effect":"Annexin I N-terminal peptides (Ac1-26, Ac9-25) served as FPR ligands, triggering dose-dependent signalling; low concentrations gave Ca2+ transients and inhibited neutrophil transmigration [PMID:10882119]. Agonist.","molecular_requirements":"Active peptides came from the unique N-terminal domain; Ac1-18 was inactive [PMID:10882119].","affinity_potency":[],"species_and_systems":"Human neutrophils with synthetic annexin I peptides [PMID:10882119].","localisation_and_range":"FPR1 flagged transmembrane receptor; ANXA1 flagged secreted [flag]. Annexin I is the ligand despite the row order.","caveats":"Abstract and excerpts only; full-length annexin I binding not shown. Direct binding not demonstrated in the abstract; BioGRID lists an affinity capture-western [DB:BioGRID]. UniProt describes interaction in dendritic cell positioning [DB:UniProt].","key_references":[{"PMID":"10882119","why":"Annexin I peptides activate FPR on neutrophils"}],"covers":["LR008493"]},"LR005937":{"pair":"GDF1 -> ACVR1B","headline":"Weak functional evidence only: a GDF3 paper cites GDF1 as using ALK4 (ACVR1B); GtoPdb asserts agonism.","interaction_type":"functional only","direction_and_effect":"GtoPdb lists GDF1 as an agonist at this receptor [DB:GtoPdb]. The only paper states that GDF3 signalling, 'similar to GDF1', is mediated by ALK4, ActRIIA, ActRIIB and Cripto in Smad-dependent reporter assays [PMID:17936261].","molecular_requirements":"Type I ALK4, type II ActRIIA/ActRIIB and the co-receptor Cripto are named; native GDF1 was incapable of signalling in heterologous cells unless a heterologous prodomain, Furin or Nodal co-expression was used [PMID:17936261].","affinity_potency":[],"species_and_systems":"Mouse is the species with primary evidence; the human pair is ortholog-projected. The abstract does not state the cell species [PMID:17936261].","localisation_and_range":"GDF1 is flagged secreted [flag].","caveats":"Abstract-only. GDF1 receptor usage is background in a paper about GDF3, not its own result [PMID:17936261]. Native GDF1 is poorly processed, so potency is not reported in our evidence.","key_references":[{"PMID":"17936261","why":"GDF3 (and, by reference, GDF1) use ALK4, ActRIIA/B and Cripto"}],"covers":["LR002672","LR005937"]},"LR008268":{"pair":"GDF1 -> ACVR1B:ACVR2A","headline":"Database-asserted only: GtoPdb lists an agonist action; no confirmed paper.","interaction_type":"database-asserted only","direction_and_effect":"GtoPdb lists GDF1 as an agonist at the ACVR1B and ACVR2A subunits (listed separately) [DB:GtoPdb]; no paper confirms it in our evidence.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"No experimental system reported in our evidence.","localisation_and_range":"GDF1 is flagged secreted [flag].","caveats":"No confirmed paper. Two papers were review-only and four abstract-insufficient. Affinity and species are not reported in our evidence.","key_references":[],"covers":["LR008268"]},"LR002679":{"pair":"GDF10 -> TGFBR2","headline":"Cross-linking competition suggests GDF10 competes with TGF-beta1 for TbetaRII binding; evidence is a browser-read quote, not spot-checked.","interaction_type":"direct binding","direction_and_effect":"GDF10 selectively activated TbetaRI/II-dependent Smad3 phosphorylation [PMID:21518866]. The curator sentence says GDF10 competes with [125I]TGF-beta1 for TbetaRI (55 kDa), TbetaRII (70 kDa) and betaglycan [PMID:21518866].","molecular_requirements":"TbetaRI/II heterodimer needed for signalling; betaglycan also competes in cross-linking [PMID:21518866].","affinity_potency":[],"species_and_systems":"Mouse tumour-cell system per the abstract [PMID:21518866]; the human pair is ortholog-inferred.","localisation_and_range":"GDF10 is flagged secreted and non-transmembrane [flag], so signalling would be paracrine or autocrine; range not studied in our evidence.","caveats":"The binding sentence is a browser-read Results quote marked unverifiable with spot-check pending; the dossier abstract holds only the signalling claim. Competition does not show direct GDF10 binding. Three other screened papers had insufficient abstracts.","key_references":[{"PMID":"21518866","why":"GDF10-dependent TGF-beta receptor signalling and competition for receptor binding"}],"covers":["LR002679","LR005944"]},"LR005946":{"pair":"GDF11 -> TGFBR1","headline":"In mice, GDF11 signals through ALK5 (TGFBR1) alongside ALK4; supported by genetics and a PDB structure.","interaction_type":"functional only","direction_and_effect":"GDF11 predominantly uses ALK4 and ALK5 to activate a Smad3-dependent reporter, and Alk5 mutant embryos show patterning defects resembling Gdf11-null mutants [PMID:16845371].","molecular_requirements":"A type II receptor is involved: the interaction was genetic with Acvr2b [PMID:16845371]; PDB 6MAC has chains of O95390 and P36897 [DB:PDB 6MAC].","affinity_potency":[],"species_and_systems":"Mouse reporter assays and embryos [PMID:16845371]; both pairs ortholog-inferred.","localisation_and_range":"GDF11 flagged secreted [flag].","caveats":"Abstract-only paper; no affinity in our evidence.","key_references":[{"PMID":"16845371","why":"ALK5 mediates GDF11 signalling in embryogenesis"}],"covers":["LR002681","LR005946"]},"LR008259":{"pair":"GDF3 -> ACVR1C:ACVR2B","headline":"Complex pair with no curator-verified paper; rests on GtoPdb and UniProt records.","interaction_type":"database-asserted only","direction_and_effect":"GtoPdb lists GDF3 as agonist of both subunits (ACVR1C and ACVR2B) as separate records [DB:GtoPdb]. UniProt says GDF3 signals via a receptor complex based on ACVR1C and CRIPTO [DB:UniProt].","molecular_requirements":"UniProt names CRIPTO as part of the receptor complex; it is not in this entry [DB:UniProt].","affinity_potency":[],"species_and_systems":"Species of the database evidence is not reported in our evidence.","localisation_and_range":"GDF3 is flagged secreted [flag]; the receptor complex is flagged transmembrane [flag].","caveats":"No papers; only review-level sources were judged. Pairing with this type II receptor is not shown directly.","key_references":[],"covers":["LR008259"]},"LR000699":{"pair":"GDF5 -> BMPR1B","headline":"Well-supported direct GDF5 binding to the type I receptor BMPR1B, by SPR and radioligand binding, with stimulatory Smad signalling.","interaction_type":"direct binding","direction_and_effect":"GDF5 binds BMPR-IB and signals stimulatorily: GDF-5 induced alkaline phosphatase activity in rat ROB-C26 cells and bound BMPR-IB but not BMPR-IA in non-transfected cells [PMID:8702914]. GDF-5 activates Smad1/5/8 in osteoprogenitor cells [PMID:11282024]. UniProt describes high-affinity BMPR1B binding and lower-affinity BMPR1A binding [DB:UniProt].","molecular_requirements":"In COS-1 cells GDF-5 bound BMPR-IB alone among type I receptors; type II receptors (BMPR-II, ActR-II, ActR-IIB) were bound too [PMID:8702914]. Ror2 forms a ligand-independent complex with BRI-b (BMPR1B) and modulates GDF5 signalling [PMID:15569154]. GDF5 Asn445 lies in both the type I receptor and NOGGIN interaction sites in a GDF5:BMPR1B structural model (PDB 3EVS) [PMID:19956691].","affinity_potency":[{"value":"apparent KD 1.3 nM","assay":"SPR biosensor, GDF5 analyte on immobilised BMPR-IB ectodomain","system":"recombinant proteins","cite":"PMID:19735544"}],"species_and_systems":"Binding: recombinant SPR [PMID:19735544]; 125I-GDF-5 on rat ROB-C26 cells and COS-1 transfectants [PMID:8702914]; iodinated GDF5 crosslinking in COS7 cells with BRI-b-HA, construct species not stated [PMID:15569154]. Pair is recorded for human and mouse.","localisation_and_range":"Ligand is flagged secreted [flag], so signalling is expected to be paracrine; not otherwise reported in our evidence.","caveats":"PMID:15569154 was read only as an abstract plus a browser-read sentence not yet spot-checked. PMID:11282024 is functional (Smad activation, type I receptor synergy), not binding. PMID:19956691 supports the pair only through a structural model and a C2C12 line stably expressing Bmpr1b.","key_references":[{"PMID":"19735544","why":"SPR affinity of GDF5 for BMPR-IB (1.3 nM)"},{"PMID":"8702914","why":"Radioligand binding and receptor specificity of GDF-5"},{"PMID":"15569154","why":"BRI-b/GDF5 binding and Ror2 modulation"}],"covers":["LR000699","LR004183"]},"LR002688":{"pair":"GDF6 -> ACVR2B","headline":"GDF6 binds the type II receptor ACVR2B with affinity similar to type I receptors, by recombinant binding; one paper.","interaction_type":"direct binding","direction_and_effect":"rhBMP13 (GDF6 alias) bound ACVR2B [PMID:21702718]. Despite similar binding to BMP2, BMP12/BMP13 induced a tendon marker (Thbs4) without detectable SMAD1/5/8 activation in C3H10T1/2 cells [PMID:21702718].","molecular_requirements":"ACVR2B is a type II receptor; ALK3 and ALK6 bound with high affinity as type I partners [PMID:21702718]. Whether ACVR2B acts alone is not reported in our evidence.","affinity_potency":[{"value":"KD (kin) 1.6 nM","assay":"Bio-Layer Interferometry, immobilised ACVR2B-Fc, rhBMP13 (GDF6 alias)","system":"recombinant proteins","cite":"PMID:21702718"}],"species_and_systems":"Recombinant proteins in vitro and C3H10T1/2 cells [PMID:21702718]. Human pair listed directly; mouse pair is ortholog-inferred.","localisation_and_range":"Ligand is flagged secreted and not transmembrane [flag]; range beyond that is not reported in our evidence.","caveats":"Only one paper; the ligand mapping (GDF6 = BMP13) rests on alias names. The paper states ACVR2B affinity for BMP12/BMP13 is similar to that of type I receptors [PMID:21702718]. No database records.","key_references":[{"PMID":"21702718","why":"Binding of rhBMP13 (GDF6) to ACVR2B"}],"covers":["LR002688","LR005953"]},"LR005955":{"pair":"GDF7 -> BMPR1B","headline":"GDF7 binds BMPR1B (ALK6) directly with high affinity and functional support.","interaction_type":"direct binding","direction_and_effect":"Binding: rhBMP12 (GDF7) bound ALK6 (BMPR1B) with high affinity, similar to rhBMP13 (GDF6) (numeric KD not in our excerpts) [PMID:21702718]. ALK6 overexpression in COS7 cells conferred GDF7 signalling [PMID:16049014]. GtoPdb lists an agonist record [DB:GtoPdb].","molecular_requirements":"Type I receptor; a type II receptor partner is implicated: BMPRII and ActRIIA shRNA suppressed GDF7 signalling [PMID:16049014].","affinity_potency":[],"species_and_systems":"Recombinant human BMP12 and receptor ectodomains in binding assays; musculoskeletal marker assays in C3H10T1/2 cells and rat ectopic implants [PMID:21702718]. Signalling studies in COS7 and MC3T3 cells [PMID:16049014]. The mouse pair is projected from human evidence.","localisation_and_range":"Ligand is flagged secreted and the receptor chain(s) as receptor [flag], which would imply paracrine signalling to a membrane receptor; localisation is not otherwise reported in our evidence.","caveats":"Binding is not the same as activation: rhBMP12 gave no detectable SMAD1/5/8 activation in C3H10T1/2 cells at low dose [PMID:21702718], whereas Smad1/5/8 reporters were activated in MC3T3 cells [PMID:16049014]. Numeric affinities are not in the excerpts. rhBMP12 is mapped to GDF7 via alternate names [PMID:16049014]. Both papers are abstract-only reads.","key_references":[{"PMID":"21702718","why":"Kinetic binding of rhBMP12 (GDF7) to type I and II receptors."},{"PMID":"16049014","why":"Receptor requirements for GDF7 signalling."}],"covers":["LR002690","LR005955"]},"LR010788":{"pair":"GDF9 -> ORAI2","headline":"Database-asserted only: a two-hybrid pooling interaction record; no curated paper evidence.","interaction_type":"database-asserted only","direction_and_effect":"Direction and effect are not reported in our evidence.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"IntAct record from a physical association by two-hybrid pooling approach [DB:IntAct]; species of the screen is not stated in our evidence.","localisation_and_range":"GDF9 is flagged secreted [flag]; ORAI2 has no localisation flags.","caveats":"Rests on a high-throughput two-hybrid record alone [PMID:16169070]; the one literature row was review-only. Treat as unverified.","key_references":[{"PMID":"16169070","why":"Source of the IntAct two-hybrid record"}],"covers":["LR010788"]},"LR007971":{"pair":"GP1BA -> ITGAM:ITGB2","headline":"Direct binding of GP Ibalpha to the Mac-1 (alphaM beta2) integrin, with the site mapped to alphaM; one strong paper (human).","interaction_type":"direct binding","direction_and_effect":"GP Ibalpha binding to Mac-1 (alphaM beta2) is mapped to the P201-K217 sequence of the alphaM I domain: swapping it for alphaL sequence abolished adhesion, and grafting it onto alphaL made alphaL beta2 bind GP Ibalpha [PMID:14530377]. Synthetic P201-K217 peptide bound GP Ibalpha directly and blocked alphaM beta2 adhesion [PMID:14530377]. Effect is adhesion; agonist/antagonist role not reported in our evidence.","molecular_requirements":"Complex is ITGAM:ITGB2. The binding site lies in the ITGAM I domain; a role for ITGB2 beyond forming the heterodimer is not reported in our evidence [PMID:14530377]. Anti-CD11b mAb LPM19c blocked adhesion of Mac-1 293 cells to soluble GP Ibalpha.","affinity_potency":[],"species_and_systems":"Human proteins; Mac-1-expressing 293 cells, THP-1 cells, adherent platelets [PMID:14530377].","localisation_and_range":"GP Ibalpha is the platelet counter receptor and Mac-1 is on leukocytes, so contact-dependent platelet-leukocyte adhesion [PMID:14530377]; both are annotated non-secreted [flag].","caveats":"Single paper. Judged rows also include 'different_entity' (1) and 'abstract_insufficient' (1). No affinity reported in our evidence.","key_references":[{"PMID":"14530377","why":"Maps the GP Ibalpha binding site to alphaM P201-K217"}],"covers":["LR007971"]},"LR002697":{"pair":"GPC1 -> LRRTM4","headline":"Glypicans bind LRRTM4 in a heparan-sulfate-dependent manner; GPC1 was detected among five glypicans in LRRTM4-Fc pulldowns.","interaction_type":"direct binding","direction_and_effect":"Glypican acts as a presynaptic partner of postsynaptic LRRTM4 in a trans-synaptic interaction; the abstract calls glypican a receptor for LRRTM4. LRRTM4 positively regulates excitatory synapse development, and its synaptogenic activity requires neuronal-surface heparan sulfate [PMID:23911103].","molecular_requirements":"Binding is heparan-sulfate (HS) dependent and selective for LRRTM4 over LRRTM2 [PMID:23911103]. LRRTM4-Fc bound strongly to all glypican isoforms tested in cell-surface assays [PMID:23911103]. LRRTM4 forms separate complexes with neurexin and glypican, not a tripartite complex (GPC4 data) [PMID:23911103].","affinity_potency":[],"species_and_systems":"Rat brain homogenate pulldown, HA-tagged mouse glypican cDNAs in HEK293T cells, cultured hippocampal neurons [PMID:23911103]; the curators labelled the experiment species human. Pair is ortholog-inferred for both species.","localisation_and_range":"Glypican is a GPI-anchored HSPG (full text) and annotated as secreted [flag]; LRRTM4 is a transmembrane receptor [flag]. Interaction is trans-synaptic and needs local glypican concentration, since soluble GPC4 did not induce LRRTM4 clustering [PMID:23911103].","caveats":"Paper-level evidence is for 'glypican' as a class. GPC1 was detected in the LRRTM4-Fc mass spectrometry sample (Figure S1A) and the abstract does not name it [PMID:23911103]. Direct cell-free binding was shown for GPC4 only. Abstract plus excerpts.","key_references":[{"PMID":"23911103","why":"Unbiased discovery of glypican-LRRTM4 binding and its role in synapse development"}],"covers":["LR002697","LR005962"]},"LR005964":{"pair":"GPC4 -> LRRTM4","headline":"Glypicans bind LRRTM4 in a heparan-sulfate-dependent manner; GPC4 is the best-characterised glypican partner, with direct cell-free binding.","interaction_type":"direct binding","direction_and_effect":"Glypican acts as a presynaptic partner of postsynaptic LRRTM4 in a trans-synaptic interaction; the abstract calls glypican a receptor for LRRTM4. LRRTM4 positively regulates excitatory synapse development, and its synaptogenic activity requires neuronal-surface heparan sulfate [PMID:23911103].","molecular_requirements":"Binding is heparan-sulfate (HS) dependent and selective for LRRTM4 over LRRTM2 [PMID:23911103]. LRRTM4-Fc bound strongly to all glypican isoforms tested in cell-surface assays [PMID:23911103]. LRRTM4 forms separate complexes with neurexin and glypican, not a tripartite complex (GPC4 data) [PMID:23911103].","affinity_potency":[],"species_and_systems":"Rat brain homogenate pulldown, HA-tagged mouse glypican cDNAs in HEK293T cells, cultured hippocampal neurons [PMID:23911103]; the curators labelled the experiment species human. Pair is ortholog-inferred for both species.","localisation_and_range":"Glypican is a GPI-anchored HSPG (full text) and annotated as secreted [flag]; LRRTM4 is a transmembrane receptor [flag]. Interaction is trans-synaptic and needs local glypican concentration, since soluble GPC4 did not induce LRRTM4 clustering [PMID:23911103].","caveats":"This is the specifically studied member: His-LRRTM4 ectodomain co-precipitated with GPC4-Fc, confirming direct interaction, and GPC4 and LRRTM4 localise to pre- and postsynaptic membranes [PMID:23911103]. Pulldowns in 293T cells worked in both directions. Curator notes call it 'GPC1/GPC4', which is imprecise.","key_references":[{"PMID":"23911103","why":"Unbiased discovery of glypican-LRRTM4 binding and its role in synapse development"}],"covers":["LR002699","LR005964"]},"LR005973":{"pair":"GPR15LG -> SUSD2","headline":"GPR15LG (CSBF/C10orf99) binds SUSD2 with sub-nanomolar competition IC50 and inhibits colon cancer cell growth; one full-text paper.","interaction_type":"direct binding","direction_and_effect":"CSBF/C10orf99 interacts with SUSD2 to inhibit colon cancer cell growth and induce G1 arrest by down-regulating cyclin D and CDK6; this is blocked by soluble sSUSD2-Fc [PMID:25351403]. It induced dose-dependent internalisation of SUSD2-EGFP [PMID:25351403]. Curators label it antagonist, meaning growth inhibition.","molecular_requirements":"Co-immunoprecipitation and FRET (efficiency 15.2%) support direct contact; the soluble extracellular region of SUSD2 (sSUSD2-Fc) binds the ligand [PMID:25351403].","affinity_potency":[{"value":"IC50 0.28 nM","assay":"125I-CSBF competition binding","system":"sSUSD2-Fc","cite":"PMID:25351403"}],"species_and_systems":"Human proteins; colon cancer cell lines (including LoVo) and purified sSUSD2-Fc [PMID:25351403].","localisation_and_range":"Classical secreted protein of about 6.5 kDa [PMID:25351403]; flagged as secreted [flag].","caveats":"One paper only. Gal1 was a comparison ligand with IC50 0.19 nM [PMID:25351403]. Activity curve was bell-shaped, optimal near 10 ng/ml.","key_references":[{"PMID":"25351403","why":"Binding IC50, co-IP, FRET and growth inhibition for CSBF/C10orf99 with SUSD2"}],"covers":["LR002708","LR005973"]},"LR005982":{"pair":"HMGB1 -> CXCR4","headline":"HMGB1 acts through CXCR4 only as a heterocomplex with CXCL12; one full-text paper, no affinity.","interaction_type":"functional only","direction_and_effect":"HMGB1 and CXCL12 form a heterocomplex (NMR, SPR) that acts exclusively through CXCR4 and not through other HMGB1 receptors, and promotes different CXCR4 conformational rearrangements than CXCL12 alone by FRET. Cell recruitment in vivo is inhibited by AMD3100 and glycyrrhizin [PMID:22370717]. UniProt notes the CXCL12:HMGB1 complex triggers CXCR4 homodimerization [DB:UniProt].","molecular_requirements":"CXCL12 is required: HMGB1-induced recruitment depends on CXCL12 [PMID:22370717].","affinity_potency":[],"species_and_systems":"Curated as human ligand and receptor; experiments also used murine NIH/3T3 cells, human monocytes and mouse air pouches [PMID:22370717]. The mouse pair is ortholog-inferred.","localisation_and_range":"HMGB1 is flagged secreted [flag]; it acts as a chemoattractant for recruited cells [PMID:22370717].","caveats":"HMGB1 is not shown here as an independent CXCR4 ligand. BioGRID lists an affinity-capture record [DB:BioGRID]. The curated assay class is direct binding, but the strongest binding data are for the HMGB1-CXCL12 interaction.","key_references":[{"PMID":"22370717","why":"HMGB1-CXCL12 heterocomplex signals via CXCR4"}],"covers":["LR002734","LR005982"]},"LR005991":{"pair":"HMGB2 -> LRP1","headline":"HMGB2 is reported to bind purified LRP1 directly in a chondrocyte ligandome study; only one abstract-level paper.","interaction_type":"direct binding","direction_and_effect":"Direct LRP1 binding was confirmed for HMGB2 (together with nine other ligands) using purified LRP1; the study links affinity for LRP1 with endocytosis rate [PMID:36028175]. Inhibiting LRP1-ligand interaction caused chondrocyte cell death and altered the secretome [PMID:36028175].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human chondrocytes, LRP1-deficient fibroblasts and a conditional Lrp1 knockout mouse; HMGB2-specific work is curated as human [PMID:36028175]. The mouse pair is ortholog-inferred.","localisation_and_range":"HMGB2 is flagged as secreted [flag]; the receptor mediates endocytosis in cartilage [PMID:36028175].","caveats":"Abstract-only reading; the HMGB2 affinity value is not given. No database records.","key_references":[{"PMID":"36028175","why":"LRP1 cartilage ligandome; direct binding of HMGB2 to LRP1"}],"covers":["LR002743","LR005991"]},"LR009393":{"pair":"HSP90B1 -> ERBB2","headline":"Database records only; no curator-verified paper supports this pair as a ligand-receptor interaction.","interaction_type":"database-asserted only","direction_and_effect":"Direction and effect are not reported in our evidence.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"BioGRID lists 2 affinity-capture-western records [DB:BioGRID]; IntAct lists one co-immunoprecipitation [DB:IntAct]. Species of the experiments is not reported in our evidence beyond the human entities.","localisation_and_range":"The ligand carries no secreted flag [flag]; localisation of the interaction is not reported in our evidence.","caveats":"No verified paper; rows judged were different_entity (3), abstract_insufficient (3) and review_only (1).","key_references":[],"covers":["LR009393"]},"LR010887":{"pair":"IBSP -> ITGAV:ITGB3","headline":"Only database records (UniProt, Reactome) support this complex; no curator-verified paper is in our evidence.","interaction_type":"database-asserted only","direction_and_effect":"UniProt says ITGAV:ITGB3 acts as a receptor for IBSP and promotes cell adhesion and migration [DB:UniProt]. Reactome lists the complex and the reaction of integrin alphaVbeta3 with IBSP [DB:Reactome R-HSA-265408].","molecular_requirements":"Both ITGAV and ITGB3 form the receptor per the database entries [DB:UniProt].","affinity_potency":[],"species_and_systems":"Human; experimental system not reported in our evidence.","localisation_and_range":"IBSP is flagged secreted and the complex transmembrane [flag].","caveats":"No papers judged (one review_only row). Direct binding, affinity and cell system are not reported in our evidence.","key_references":[],"covers":["LR010887"]},"LR000789":{"pair":"ICAM2 -> ITGAM","headline":"One 1995 abstract reports ICAM-2 interacting with CD11b/CD18 via the CD11b A domain; thin evidence.","interaction_type":"direct binding","direction_and_effect":"ICAM-2 interacts with CD11b/CD18, and the binding is through the CD11b A domain, using purified protein [PMID:7561061]. Effect direction not reported in our evidence.","molecular_requirements":"The A (I) domain of CD11b is sufficient to mediate binding [PMID:7561061]; the dossier does not say whether CD18 is needed for ICAM-2 binding.","affinity_potency":[],"species_and_systems":"Purified proteins; species not stated in the curated fields [PMID:7561061].","localisation_and_range":"Membrane-bound adhesion molecules; contact-dependent.","caveats":"Abstract only; three other judged rows were abstract_insufficient. No database records and no affinity.","key_references":[{"PMID":"7561061","why":"ICAM-2 binds CD11b/CD18 through the CD11b A domain"}],"covers":["LR000789"]},"LR000798":{"pair":"ICAM4 -> ITGAM","headline":"Human studies show Mac-1 (alphaMbeta2) binding to ICAM-4-Fc; first and second Ig domains are involved; mouse pair is ortholog-inferred.","interaction_type":"direct binding","direction_and_effect":"alphaMbeta2 transfectants bind recombinant ICAM-4-Fc specifically and dose dependently [PMID:15355350]; antibodies to CD11b or CD18 blocked L-cell adhesion to ICAM-4-Fc, which was sensitive to Ca2+ and Mg2+ [PMID:10846180]. UniProt lists ITGAM:ITGB2 as an ICAM4 partner in vitro [DB:UniProt].","molecular_requirements":"The complex alphaM/beta2 (Mac-1) is the receptor. The Mac-1 binding site encompasses both the first and second Ig-like domains of ICAM-4 [PMID:10846180].","affinity_potency":[],"species_and_systems":"Human ICAM-4-Fc with human integrin transfectants and L-cells [PMID:15355350, PMID:10846180].","localisation_and_range":"ICAM4 carries both secreted and transmembrane flags [flag], so range is unclear; the papers used recombinant ICAM-4-Fc and cell-surface ICAM-4, consistent with contact-dependent adhesion.","caveats":"Both papers abstract only; one is an adhesion assay. A fifth judged row was abstract-insufficient. Affinity not reported.","key_references":[{"PMID":"15355350","why":"Dose-dependent alphaMbeta2 binding to ICAM-4-Fc"},{"PMID":"10846180","why":"Mac-1 binding spans ICAM-4 domains 1 and 2"}],"covers":["LR000798","LR004252"]},"LR007269":{"pair":"IFNA10 -> IFNAR1:IFNAR2","headline":"Heterodimer pair supported only by a class-wide chain-binding abstract and GtoPdb chain entries.","interaction_type":"direct binding","direction_and_effect":"Alpha-IFNs bind each isolated chain [PMID:21856167]; GtoPdb lists IFNA10 as agonist of each chain [DB:GtoPdb].","molecular_requirements":"The paper tested isolated IFNAR1 and IFNAR2 chains, not the assembled complex [PMID:21856167].","affinity_potency":[{"value":"0.5-5 \u03bcM (IFNAR1) and 0.4-5 nM (IFNAR2)","assay":"binding to isolated chains","system":"12 human alpha-IFN subtypes","cite":"PMID:21856167"}],"species_and_systems":"Human isolated receptor chains.","localisation_and_range":"IFNA10 flagged secreted; complex flagged transmembrane [flag].","caveats":"Abstract only; IFNA10 not named in the abstract. No complex-level binding in our evidence.","key_references":[{"PMID":"21856167","why":"Chain affinities of alpha-IFN subtypes"}],"covers":["LR007269"]},"LR007278":{"pair":"IFNA7 -> IFNAR1:IFNAR2","headline":"IFNA7 binds the IFNAR1:IFNAR2 receptor; support is a class-wide binding study on the individual chains plus GtoPdb.","interaction_type":"direct binding","direction_and_effect":"IFNA6 acts as an agonist on the type I interferon receptor; the curator-verified study reports binding of human alpha-IFN subtypes to isolated receptor chains [PMID:21856167]. GtoPdb lists this as an agonist interaction with no affinity units [DB:GtoPdb].","molecular_requirements":"Both chains are named: for alpha-IFNs IFNAR2 binds tightly (0.4-5 nM) and IFNAR1 weakly (0.5-5 \u03bcM) [PMID:21856167]. Binding was measured on isolated chains, not on the assembled heterodimer.","affinity_potency":[{"value":"0.4-5 nM","assay":"affinity determination, 12 human alpha-IFN subtypes collectively, isolated IFNAR2 chain","system":"human proteins","cite":"PMID:21856167"},{"value":"0.5-5 \u03bcM","assay":"affinity determination, 12 human alpha-IFN subtypes collectively, isolated IFNAR1 chain","system":"human proteins","cite":"PMID:21856167"}],"species_and_systems":"Human ligand and human receptor chains, isolated recombinant chains (abstract-level reading) [PMID:21856167].","localisation_and_range":"Ligand is flagged secreted and not transmembrane [flag], so it acts as a diffusible paracrine or endocrine signal. The receptor is flagged transmembrane [flag].","caveats":"The affinity range is stated for 'Alpha-IFNs' as a class, not IFNA6 individually; only IFN-alpha1 (220 nM) is singled out as weaker, and the paper was read as an abstract only [PMID:21856167].","key_references":[{"PMID":"21856167","why":"binding of 12 human alpha-IFN subtypes to isolated IFNAR1 and IFNAR2"}],"covers":["LR007278"]},"LR005199":{"pair":"IFNE -> IFNAR1","headline":"IFNE signals through IFNAR1 in mouse, shown functionally; human pair is projected. No database records.","interaction_type":"functional only","direction_and_effect":"IFN-\u03b5 signalled via the Ifnar1 and Ifnar2 receptors to induce IFN-regulated genes, so it acts as a type I IFN agonist [PMID:23449591]. Ifn-\u03b5-deficient mice were more susceptible to HSV-2 and Chlamydia muridarum infection of the female reproductive tract [PMID:23449591].","molecular_requirements":"Both Ifnar1 and Ifnar2 are named as the signalling receptors [PMID:23449591]; whether one chain suffices is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Mouse experiments; the human pair is ortholog-inferred, the mouse pair is not [PMID:23449591].","localisation_and_range":"Ligand is flagged secreted and not transmembrane [flag], so it acts as a diffusible paracrine or endocrine signal. The paper reports IFN-\u03b5 constitutively expressed by female reproductive tract epithelium and hormonally regulated [PMID:23449591].","caveats":"Evidence is functional (gene induction), not binding, and abstract-only. No direct binding or affinity data and no database records in our evidence.","key_references":[{"PMID":"23449591","why":"IFN-\u03b5 signals via Ifnar1/Ifnar2; knockout mice more infection-prone"}],"covers":["LR001851","LR005199"]},"LR002769":{"pair":"IGF2 -> ITGA6","headline":"Integrin alpha6beta4 binds IGF2 in one verified study; ITGA6 is the alpha chain.","interaction_type":"direct binding","direction_and_effect":"IGF2 specifically bound integrins alphavbeta3 and alpha6beta4 and induced proliferation of IGF1R-positive CHO cells expressing either integrin [PMID:28873464]. Integrin-binding-defective IGF2 mutants (Arg to Glu at 24, 34, 37 and/or 38) suppressed wild-type IGF2 proliferation, suggesting dominant-negative IGF1R antagonism [PMID:28873464]. UniProt agrees [DB:UniProt].","molecular_requirements":"The alpha6beta4 heterodimer was tested; ITGA6 alone is not shown [PMID:28873464].","affinity_potency":[],"species_and_systems":"CHO cells expressing recombinant integrins, ELISA-type binding with soluble alphavbeta3, and adhesion assays; anchorage-independent conditions [PMID:28873464]. Mouse pair is ortholog-inferred.","localisation_and_range":"IGF2 is flagged secreted [flag].","caveats":"The single supporting paper is the same for several integrin chain rows; evidence concerns the heterodimer. No affinity is reported in our evidence.","key_references":[{"PMID":"28873464","why":"IGF2 binds alphavbeta3 and alpha6beta4; C-domain Arg mutants"}],"covers":["LR002769","LR006015"]},"LR008295":{"pair":"IGFBP7 -> DCC","headline":"Conflicting: a large screen saw no ELISA binding of DCC to IGFBP7, but the same paper's SPR reports binding.","interaction_type":"conflicting","direction_and_effect":"Direction and effect are not reported in our evidence. The screen did not see DCC binding IGFBP7, but DCC bound IGFBPL1; the authors then examined both by SPR and observed binding for both [PMID:32822567].","molecular_requirements":"No subunit or co-receptor information in our evidence.","affinity_potency":[],"species_and_systems":"Human proteins, recombinant, in a high-throughput ELISA screen followed by SPR (analyte concentrations 2 to 2,048 nM) [PMID:32822567].","localisation_and_range":"IGFBP7 is annotated as secreted and DCC as transmembrane [flag].","caveats":"The curator-selected evidence sentence is a negative from the screen, while SPR is positive; no affinity value is given in the excerpts. The paper is a full-text read but the excerpts are partial.","key_references":[{"PMID":"32822567","why":"Cell-surface interactome screen; DCC-IGFBP7 negative in screen, SPR positive"}],"covers":["LR008295"]},"LR002778":{"pair":"IGFBP7 -> LRP1","headline":"One of ten ligands with direct LRP1 binding confirmed in a chondrocyte ligandome study (abstract only).","interaction_type":"direct binding","direction_and_effect":"Direct LRP1 binding was confirmed for IGFBP7 with purified LRP1; affinity correlated with endocytosis rate, so LRP1 acts as an endocytic receptor [PMID:36028175]. Curator effect label: agonist.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human chondrocytes, purified proteins, LRP1-deficient cells, plus a conditional Lrp1-knockout mouse for in vivo relevance [PMID:36028175]. The mouse pair is projected.","localisation_and_range":"IGFBP7 is annotated as secreted [flag].","caveats":"Abstract-only read; the abstract names IGFBP7 among ten ligands without an IGFBP7-specific affinity. LRP1 is an endocytic scavenger, so this is clearance rather than signalling.","key_references":[{"PMID":"36028175","why":"Chondrocyte LRP1 ligandome; direct binding confirmed for IGFBP7"}],"covers":["LR002778","LR006024"]},"LR008691":{"pair":"IL12B -> IL23R","headline":"No curated paper supports IL12B binding IL23R; only database records (GtoPdb and PDB complexes) assert it.","interaction_type":"database-asserted only","direction_and_effect":"GtoPdb lists IL12B-IL23R as agonist, citing PMID 29287995 and 34038748 [DB:GtoPdb].","molecular_requirements":"PDB structures 5MZV (IL-23:IL-23R:Nb22E11), 6WDQ and 8OE4 contain chains of IL12B and IL23R [DB:PDB 5MZV]. UniProt says IL-23 binds a heterodimeric receptor of IL12RB1 and IL23R [DB:UniProt]. Whether p40 itself contacts IL23R is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human records; the complex structures are X-ray.","localisation_and_range":"Not reported in our evidence.","caveats":"No confirmed papers (one abstract judged insufficient). Co-occurrence of chains in a complex structure does not show a direct IL12B-IL23R contact. GtoPdb gives pKd and pEC50 units but no values here.","key_references":[],"covers":["LR008691"]},"LR007296":{"pair":"IL15 -> IL15RA:IL2RB","headline":"IL15 is trans-presented as IL15RA:IL15 to IL2RB:IL2RG; supported by one recent in vivo abstract.","interaction_type":"functional only","direction_and_effect":"IL-15 is trans-presented as IL-15R alpha:IL-15 complex to IL-15R beta:gamma-c on neighboring cells [PMID:42588715]. GtoPdb lists agonist [DB:GtoPdb].","molecular_requirements":"Receptor is composed of IL-15R alpha, IL-15R beta and common gamma-c [PMID:42588715]. In this row only IL15RA and IL2RB are included; IL2RG is omitted.","affinity_potency":[],"species_and_systems":"Knockout mice (Il15-/-, Il15ra-/-) and tumour models; the paper concerns mice though ligand and receptor species are labelled human [PMID:42588715].","localisation_and_range":"Trans-presentation implies membrane-bound, contact-dependent presentation to neighbouring cells [PMID:42588715].","caveats":"Statement is background framing in an in vivo tumour paper, not a binding test. Abstract only. IL15RA lacking mice had reduced MCA tumour incidence while IL-15 loss did not [PMID:42588715].","key_references":[{"PMID":"42588715","why":"Trans-presentation of IL-15 by IL15Ra in tumour immune surveillance"}],"covers":["LR007296"]},"LR002787":{"pair":"IL17D -> CD93","headline":"IL-17D reportedly binds CD93 on ILC3s, found by protein purification and supported by mouse knockout data; one abstract-only paper.","interaction_type":"direct binding","direction_and_effect":"Receptor role: IL-17D bound CD93 rather than canonical IL-17 receptors [PMID:33852831]. Mice lacking Cd93 in ILC3s had impaired IL-22 production and aggravated colitis, consistent with an IL-17D-CD93 axis [PMID:33852831].","molecular_requirements":"Not reported in our evidence beyond CD93 being a glycoprotein on mature ILC3s [PMID:33852831].","affinity_potency":[],"species_and_systems":"Mouse knockout and colitis work (Il17d-/-, Cd93 in ILC3s); curators recorded the binding species as unspecified [PMID:33852831]. Human pair is ortholog-inferred.","localisation_and_range":"CD93 is annotated as a transmembrane receptor and not secreted [flag]; IL-17D annotated as secreted [flag]. Cell-surface on ILC3s is described in the paper.","caveats":"Single abstract-only paper; no affinity or binding assay details beyond 'protein purification studies'.","key_references":[{"PMID":"33852831","why":"IL-17D binds CD93 on ILC3s; Cd93 loss in ILC3s phenocopies"}],"covers":["LR002787","LR006030"]},"LR000888":{"pair":"IL20 -> IL20RB","headline":"IL-20 binds IL20RB first with high affinity, then recruits IL20RA; well supported as a chain of the IL-20 receptor.","interaction_type":"direct binding","direction_and_effect":"IL-20 forms a stable high-affinity binary complex with sIL-20R2 (IL20RB), which creates the binding site for receptor I [PMID:14580208]. IL-20 signals through both IL-20RA/IL-20RB and IL-22R/IL-20RB [PMID:12351624] [PMID:11564763]. GtoPdb: Agonist [DB:GtoPdb].","molecular_requirements":"IL20RB is the shared chain of both type I and type II complexes [PMID:11564763] [PMID:12351624]; signalling needs a partner chain, IL20RA or IL22RA1.","affinity_potency":[],"species_and_systems":"Recombinant human soluble ectodomains from S2 cells [PMID:14580208]; transfected cell lines [PMID:12351624]. Mouse pair projected.","localisation_and_range":"IL-20 flagged secreted [flag].","caveats":"All papers abstract only; no numeric affinity reported in our evidence. Two other papers were abstract_insufficient.","key_references":[{"PMID":"14580208","why":"IL-20 binds receptor II (IL20RB) first with high affinity"},{"PMID":"11564763","why":"IL20RB shared by type I and II IL-20R"},{"PMID":"12351624","why":"Receptor sharing among IL-19, IL-20, IL-24"}],"covers":["LR000888","LR004318"]},"LR000897":{"pair":"IL24 -> IL20RA","headline":"IL-24 signals through IL20RA paired with IL20RB; multiple papers agree, though all were read as abstracts.","interaction_type":"direct binding","direction_and_effect":"IL-24 is a ligand for IL-20R1/IL-20R2 and IL-22R1/IL-20R2, and COS cells with either heterodimer bind it with similar saturation kinetics [PMID:11706020]; mda-7 binds the type I IL-20R complex with STAT3 phosphorylation [PMID:11564763]. Agonist per GtoPdb [DB:GtoPdb].","molecular_requirements":"IL20RA acts only with IL20RB; IL-24 can alternatively use IL22RA1 with IL20RB [PMID:12351624][PMID:20061404]. A soluble homodimeric IL-20R2 blocks IL-24 [PMID:20061404].","affinity_potency":[],"species_and_systems":"Human receptors in COS, BHK cells and keratinocytes [PMID:11706020]; IL-24 transgenic mice show epidermal phenotypes that appear IL-22R1 dependent [PMID:20061404].","localisation_and_range":"IL-24 is flagged secreted [flag].","caveats":"All abstract-only. Binding is to heterodimers, so the IL20RA row inherits complex evidence. In vivo phenotype is described as IL-22R1 dependent, not IL20RA dependent [PMID:20061404].","key_references":[{"PMID":"11706020","why":"IL-24 binds IL-20R1/IL-20R2 and IL-22R1/IL-20R2"},{"PMID":"11564763","why":"mda-7 binds type I IL-20R"},{"PMID":"20061404","why":"IL-24 transgenic mice; soluble IL-20R2 blocks IL-24"}],"covers":["LR000897","LR004327"]},"LR007926":{"pair":"INHA:INHBA -> ACVR1:ACVR2B","headline":"Inhibin-A (INHA:INHBA) to ACVR1:ACVR2B: database support, mostly via activin A; no curated paper.","interaction_type":"database-asserted only","direction_and_effect":"GtoPdb lists INHA and INHBA with ACVR2B as agonist [DB:GtoPdb]. UniProt notes activin A can form a non-signalling complex with ACVR1 and a type II receptor, rendering receptors unavailable to BMPs [DB:UniProt]. Inhibin-A effect is not directly evidenced in our evidence.","molecular_requirements":"Type II chain ACVR2B binds activin A/inhibin per databases; UniProt says it binds inhibin-A/INHA-INHBA [DB:UniProt]. PDB 7OLY shows ACVR2B ligand-binding region with activin A [DB:PDB 7OLY]. Type I chain ACVR1 is not specifically evidenced.","affinity_potency":[],"species_and_systems":"Species not reported in our evidence. X-ray structure PDB 7OLY (35005539) [DB:PDB 7OLY]; BioGRID has INHBA with ACVR2B [DB:BioGRID 282732].","localisation_and_range":"Ligand heterodimer flagged secreted [flag].","caveats":"No paper evidence supports this pair; it rests on database records. Both judged papers were review_only. The PDB structure is activin A (INHBA) with the receptor, not the INHA:INHBA heterodimer; evidence concerns INHBA rather than the inhibin heterodimer.","key_references":[],"covers":["LR007926"]},"LR007935":{"pair":"INHA:INHBB -> ACVR1C:ACVR2A","headline":"Inhibin A:activin B to ACVR1C:ACVR2A rests on database records for single chains only; no verified paper.","interaction_type":"database-asserted only","direction_and_effect":"No curator-verified paper; GtoPdb lists the component pairs as agonist [DB:GtoPdb]. BioGRID records ACVR2A with INHBB and INHA (Reconstituted Complex, Affinity Capture-Western) [DB:BioGRID]; IntAct has a coimmunoprecipitation record [DB:IntAct]; Reactome lists activin binding to ACVR2A,B:ACVR1B [DB:Reactome].","molecular_requirements":"Receptor is a type I plus type II pair (ACVR1C:ACVR2A). UniProt notes INHBB-related signalling through ACVR1C with type II receptors such as ACVR2A or BMPR2 where relevant [DB:UniProt]; whether this specific heterodimeric ligand binds this exact combination is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human pair; no experimental species reported in our evidence (no verified papers).","localisation_and_range":"Ligand carries a secreted flag and receptor a transmembrane flag [flag]; suggests endocrine or paracrine action on membrane receptors.","caveats":"Rests on databases alone; the two papers judged were review_only, so none confirms this pair. Database records concern individual subunits or related complexes, not necessarily this exact combination. ","key_references":[],"covers":["LR007935"]},"LR007944":{"pair":"ITGAV:ITGB3 -> ADGRE5","headline":"Integrin alphavbeta3 contributes to CD97 attachment, weaker than alpha5beta1; abstract-level evidence.","interaction_type":"functional only","direction_and_effect":"Alphavbeta3 'also contributes to cell attachment' to CD97 [PMID:15576472].","molecular_requirements":"Listed as secondary to alpha5beta1 [PMID:15576472].","affinity_potency":[],"species_and_systems":"Human HUVEC [PMID:15576472].","localisation_and_range":"ADGRE5 flagged secreted and transmembrane [flag].","caveats":"Abstract only; no direct binding or affinity reported for this integrin. Curator notes call it a secondary contributor.","key_references":[{"PMID":"15576472","why":"Notes alphavbeta3 as a contributor to CD97 attachment"}],"covers":["LR007944"]},"LR001869":{"pair":"JAM2 -> JAM3","headline":"JAM2 and JAM3 are heterophilic binding partners, supported by several papers and database records.","interaction_type":"direct binding","direction_and_effect":"JAM3 ectodomain bound JAM2-Fc, also when JAM3-Fc captured cells expressing JAM2; JAM3 is the counter-receptor mediating JAM2 adhesion to T cells [PMID:11590146]. JAM-B and JAM-C heterophilically interact in cell-cell contacts, and soluble JAM-B dissociated JAM-C homodimers [PMID:16093349]. A functional JAM-B/JAM-C interaction was found between human HSPC and mesenchymal stem cells [PMID:24357068]. Reactome records the binding [DB:Reactome].","molecular_requirements":"The first Ig-like fold of JAM2 binds JAM3 [PMID:12070135]. JAM3 also binds integrin alphaMbeta2 and may be sequestered by JAM2 [PMID:16093349].","affinity_potency":[],"species_and_systems":"Human proteins and cells [PMID:11590146][PMID:12070135][PMID:16093349]; mouse in vivo plus human cells [PMID:24357068].","localisation_and_range":"JAM2 flagged as not secreted [flag]; junctional or cell-contact interaction [PMID:16093349].","caveats":"All abstract-only; no affinity in our evidence. Species labelled human for a paper using mouse in vivo [PMID:24357068].","key_references":[{"PMID":"11590146","why":"Identifies JAM2-JAM3 binding"},{"PMID":"16093349","why":"Heterophilic interaction in cell contacts"},{"PMID":"24357068","why":"Functional role in HSPC homing"}],"covers":["LR001869","LR005214"]},"LR000969":{"pair":"L1CAM -> CNTN1","headline":"Co-immunoprecipitation from mouse cerebellum shows F3/CNTN1 in a complex with L1; one abstract-only paper.","interaction_type":"direct binding","direction_and_effect":"F3 (CNTN1) was physically associated in a complex with both L1 and fyn tyrosine kinase in native adult mouse cerebellum [PMID:7595520]. No effect direction is reported.","molecular_requirements":"F3 is GPI-anchored and sits in glycolipid-enriched microdomains that also contain L1 and fyn [PMID:7595520]; whether fyn or other proteins bridge the association is not reported in our evidence. Reactome lists an L1:CNTN1 complex [DB:Reactome R-HSA-443653].","affinity_potency":[],"species_and_systems":"Adult mouse cerebellum tissue, co-IP; human pair is ortholog-inferred [PMID:7595520].","localisation_and_range":"Both membrane-anchored on parallel fibers (cis/contact); CNTN1 is not flagged secreted [flag].","caveats":"Co-IP shows association within a complex, not proven direct binding; abstract only.","key_references":[{"PMID":"7595520","why":"Native-tissue co-IP of F3 with L1 and fyn"}],"covers":["LR000969","LR004391"]},"LR004398":{"pair":"LAMA1 -> ITGA2","headline":"A recombinant laminin alpha1 N-terminal fragment binds purified alpha2beta1 integrin; abstract-only read.","interaction_type":"direct binding","direction_and_effect":"Fragment alpha1VI/V bound purified alpha1beta1 and alpha2beta1 integrins, whereas fragment alpha1V alone did not [PMID:9688542]. The interaction record carries a Stimulatory effect label [flag].","molecular_requirements":"The site localises to the LN module (domain VI); the integrin was tested as the alpha2beta1 heterodimer, so ITGB1 is also needed in our evidence [PMID:9688542].","affinity_potency":[],"species_and_systems":"Recombinant laminin alpha1 fragments and purified integrins; species not stated in the abstract [PMID:9688542].","localisation_and_range":"Ligand flagged secreted [flag]; a matrix ligand.","caveats":"Abstract only; a fragment rather than full-length LAMA1 was tested. Pair is assigned from a heterodimer result. BioGRID lists a reconstituted complex [DB:BioGRID].","key_references":[{"PMID":"9688542","why":"LN module binds alpha2beta1 integrin"}],"covers":["LR000977","LR004398"]},"LR000978":{"pair":"LAMA1 -> ITGA6","headline":"Functional evidence that laminin supports alpha6beta4-dependent cell adhesion under flow; abstract-only and heterotrimer-level.","interaction_type":"functional only","direction_and_effect":"Laminin supported attachment and rolling of alpha6beta4-positive cells under shear, and an anti-alpha6 antibody blocked attachment and detached adherent cells [PMID:7699012].","molecular_requirements":"The receptor in this paper is the alpha6beta4 heterodimer; laminin fragment E8 supported attachment while fibronectin did not [PMID:7699012].","affinity_potency":[],"species_and_systems":"Cell lines expressing alpha6beta4 in a laminar-flow assay; species not stated [PMID:7699012].","localisation_and_range":"Ligand flagged secreted [flag]; matrix ligand supporting dynamic cell adhesion [PMID:7699012].","caveats":"Abstract only; the ligand is the laminin heterotrimer, not LAMA1 alone, and the receptor is alpha6beta4, not ITGA6 alone. Two other confirmed rows and two review-only rows are not shown.","key_references":[{"PMID":"7699012","why":"Alpha6beta4-mediated adhesion to laminin under flow"}],"covers":["LR000978","LR004399"]},"LR000987":{"pair":"LAMA2 -> ITGB4","headline":"Alpha6beta4 reported as a receptor for laminin 2 in radioligand and adhesion assays; abstract-only, trimer-level.","interaction_type":"direct binding","direction_and_effect":"Cell adhesion and radioligand-binding assays showed alpha6beta4 is a receptor for several laminin isoforms including laminin 2 [PMID:7721947]. Labelled Stimulatory [flag].","molecular_requirements":"The receptor is the alpha6beta4 heterodimer; beta4 mutants lacking either domain did not suppress adhesion to laminins [PMID:7721947].","affinity_potency":[],"species_and_systems":"804G bladder epithelial cells (the curator infers rat), laminin origin unstated [PMID:7721947]. Human and mouse pairs are ortholog-inferred.","localisation_and_range":"Ligand flagged secreted; matrix ligand.","caveats":"Abstract only; species ambiguous; laminin 2 is a trimer, so LAMA2 alone is not isolated. One review-only row not shown. No affinity reported.","key_references":[{"PMID":"7721947","why":"Alpha6beta4 is a receptor for laminin 2"}],"covers":["LR000987","LR004407"]},"LR002859":{"pair":"LAMA4 -> DAG1","headline":"Recombinant laminin alpha4 G-domain modules bind alpha-dystroglycan only weakly; one abstract-level paper.","interaction_type":"direct binding","direction_and_effect":"Recombinant alpha4LG1-3 and alpha4LG4-5 had only a low affinity for alpha-dystroglycan compared with laminin alpha1 and alpha2 G domains [PMID:10934193].","molecular_requirements":"G-domain fragments were tested, not full-length laminin alpha4 chain or laminin-8 [PMID:10934193].","affinity_potency":[],"species_and_systems":"Species not specified in our evidence; human and mouse pairs are both ortholog-inferred [PMID:10934193].","localisation_and_range":"LAMA4 flagged secreted; DAG1 flagged transmembrane [flag].","caveats":"Evidence is a low-affinity, comparative result, not a quantified Kd; abstract only. Two papers were abstract-insufficient.","key_references":[{"PMID":"10934193","why":"Low-affinity alpha-dystroglycan binding of alpha4 G domain"}],"covers":["LR002859","LR006093"]},"LR000996":{"pair":"LAMA5 -> ITGA6","headline":"Laminin alpha5 (as laminin-511/521) binds integrin alpha6beta1 with sub-nM Kd; supported by binding and antibody-blocked adhesion.","interaction_type":"direct binding","direction_and_effect":"Laminin-511/521 bound recombinant integrin alpha6beta1 [PMID:16413178]. Mouse FDCP-mix cell adhesion to alpha5-laminins involved integrin alpha6 and beta1 chains by antibody perturbation [PMID:10194432]. Annotated stimulatory.","molecular_requirements":"Binding was shown for the assembled heterotrimer with the alpha6beta1 heterodimer, not for single chains [PMID:16413178]. A PDB entry has a chain of O15230 and a chain of P23229 [DB:PDB 7CEC].","affinity_potency":[{"value":"Kd 0.73 nM","assay":"solid-phase saturation binding, recombinant integrin ectodomain to purified laminin isoforms (laminin-511/521 vs alpha6beta1)","system":"human recombinant proteins","cite":"PMID:16413178"}],"species_and_systems":"Human recombinant proteins [PMID:16413178]; mouse cell adhesion [PMID:10194432]. Mouse pair is ortholog-inferred.","localisation_and_range":"LAMA5 is flagged secreted [flag] and ITGA6 is flagged as a receptor [flag]; beyond these annotation flags, range is not reported in our evidence.","caveats":"Heterotrimer-level evidence. The adhesion paper was read as an abstract only and is a functional antibody readout [PMID:10194432].","key_references":[{"PMID":"16413178","why":"Kd of alpha6beta1 for laminin-511/521"},{"PMID":"10194432","why":"Mouse cell adhesion to alpha5-laminins via alpha6/beta1"}],"covers":["LR000996","LR004415"]},"LR006099":{"pair":"LAMB1 -> ITGB8","headline":"Integrin beta8-containing heterodimers mediate chick neuron interaction with laminin-1; a single abstract-only functional paper.","interaction_type":"functional only","direction_and_effect":"An antibody to the beta8 extracellular domain blocked chick sensory neuron interactions with laminin-1, collagen IV and fibronectin, identifying the first ligands for beta8 integrins [PMID:7542940].","molecular_requirements":"Beta8-containing heterodimers are the binding entity; the alpha partner is not given in our evidence. Laminin-1 is a heterotrimer, so LAMB1 is not isolated [PMID:7542940].","affinity_potency":[],"species_and_systems":"Chick sensory neurons; human and mouse pairs are by homology (ortholog-inferred) [PMID:7542940].","localisation_and_range":"LAMB1 is flagged secreted [flag] and ITGB8 is flagged as a receptor [flag]; beyond these annotation flags, range is not reported in our evidence.","caveats":"One abstract-only antibody-blocking study; no direct binding or affinity. The dossier's curator note states the integrin subunit rows should be folded into complex entities before scoring [PMID:7542940].","key_references":[{"PMID":"7542940","why":"Anti-beta8 antibody blocks neuron interaction with laminin-1"}],"covers":["LR002865","LR006099"]},"LR002868":{"pair":"LAMB2 -> ITGA7","headline":"LAMB2 (in laminin-211/221) binds integrin alpha7 with sub-nanomolar Kd in recombinant assays; assembled-laminin evidence.","interaction_type":"direct binding","direction_and_effect":"Laminin-211/221, which contains LAMB2, bound the recombinant integrin alpha7 beta1 ectodomain in solid-phase binding [PMID:16413178]. Direction: laminin ligand to integrin receptor; effect not reported beyond binding.","molecular_requirements":"The tested binder is the alpha7X1beta1 heterodimer and the ligand is the assembled laminin heterotrimer; single chains were not tested [PMID:16413178].","affinity_potency":[{"value":"Kd 0.64 nM","assay":"solid-phase saturation binding, recombinant integrin ectodomain to purified laminin isoform; alpha7X1beta1 vs laminin-211/221","system":"recombinant human integrin, purified laminin","cite":"PMID:16413178"}],"species_and_systems":"Recombinant human proteins [PMID:16413178]; mouse pair is projected from human.","localisation_and_range":"Ligand is annotated as secreted [flag]; the receptor is annotated as a receptor [flag]. Matrix versus soluble range is not reported in our evidence.","caveats":"Kd values are for the whole laminin heterotrimer, not the single chain. Only one paper supports the pair.","key_references":[{"PMID":"16413178","why":"Kd for alpha7X1beta1 vs laminin-211/221, full text"}],"covers":["LR002868","LR006102"]},"LR010797":{"pair":"LAMC2 -> ITGA9:ITGB1","headline":"Supported only by a Reactome record about alpha2beta1 binding laminin-332; no curated paper.","interaction_type":"database-asserted only","direction_and_effect":"Reactome R-HSA-349626 records integrin alpha2beta1 binding laminin-332 [DB:Reactome R-HSA-349626].","molecular_requirements":"The record names alpha2beta1, not alpha9beta1 [DB:Reactome R-HSA-349626].","affinity_potency":[],"species_and_systems":"Not reported in our evidence.","localisation_and_range":"LAMC2 flagged secreted [flag].","caveats":"No verified papers; the database record does not name ITGA9.","key_references":[],"covers":["LR010797"]},"LR002877":{"pair":"LEFTY1 -> ACVR2B","headline":"Lefty is proposed to antagonise Nodal by competing for ActRIIA/ActRIIB; evidence is functional, from one abstract.","interaction_type":"functional only","direction_and_effect":"Lefty-induced inhibition of Nodal signalling was rescued by excess ActRIIA or ActRIIB, suggesting competitive binding as an antagonist [PMID:11952836].","molecular_requirements":"ActRIIA or ActRIIB can serve as the common receptor; the paper does not say which is required [PMID:11952836].","affinity_potency":[],"species_and_systems":"Frog animal caps and mouse genetics (lefty2 with ActRIIB) [PMID:11952836]. Human pair is ortholog-projected.","localisation_and_range":"LEFTY1 flagged secreted [flag].","caveats":"Abstract only; competition inferred, not measured; Lefty1 versus Lefty2 not distinguished.","key_references":[{"PMID":"11952836","why":"Rescue of Lefty inhibition by ActRIIB"}],"covers":["LR002877","LR006111"]},"LR001878":{"pair":"LGALS1 -> ITGB1","headline":"Direct galectin-1 binding to beta1 integrin shown by cross-linking and immunoprecipitation in smooth muscle cells.","interaction_type":"direct binding","direction_and_effect":"125I-galectin-1 cross-linked to cell surface proteins immunoprecipitated with beta1 integrin; galectin-1 modulated SMC attachment, transiently raised active beta1 integrin and tyrosine phosphorylation of two proteins, one coinciding with FAK, suggesting outside-in signalling [PMID:14550305].","molecular_requirements":"Beta1 subunit identified; alpha partner not reported in our evidence. Binding depended on beta-galactoside, as attachment effects were beta-galactoside-dependent [PMID:14550305].","affinity_potency":[],"species_and_systems":"Human vascular smooth muscle cells (curator: human); mouse pair ortholog-inferred [PMID:14550305].","localisation_and_range":"Galectin-1 flagged secreted; ITGB1 flagged receptor, not secreted [flag]. Acts on SMC surface [PMID:14550305].","caveats":"Abstract-only read; FAK link is a coincidence in size, not proven. No affinity data.","key_references":[{"PMID":"14550305","why":"Cross-linking/IP shows direct galectin-1 binding to beta1 integrin"}],"covers":["LR001878","LR005220"]},"LR002886":{"pair":"LGALS3 -> MCAM","headline":"CD146/MCAM is the major galectin-3 binder on endothelial cells and mediates galectin-3-induced cytokine secretion.","interaction_type":"direct binding","direction_and_effect":"Galectin-3 bound N-linked glycans on CD146, induced CD146 dimerisation and AKT signalling; CD146 siRNA completely abolished galectin-3-induced IL-6 and G-CSF secretion [PMID:28364041]. Effect is agonist.","molecular_requirements":"N-glycans on CD146 are required for binding; dimerisation of CD146 follows [PMID:28364041].","affinity_potency":[],"species_and_systems":"Human vascular endothelial cells [PMID:28364041]. BioGRID lists Affinity Capture-Western, Reconstituted Complex and Co-purification [DB:BioGRID]. Mouse pair ortholog-inferred.","localisation_and_range":"Circulating galectin-3 (up to 30-fold higher in cancer patients) acts on endothelial cells [PMID:28364041]; MCAM flagged not transmembrane in the annotation [flag].","caveats":"Abstract-only read. Galectin-3 co-purified three other glycoproteins, so CD146 is not the only partner. The MCAM transmembrane flag looks inconsistent with a cell-surface adhesion molecule.","key_references":[{"PMID":"28364041","why":"CD146 is the functional galectin-3 receptor on endothelium"}],"covers":["LR002886","LR006120"]},"LR002895":{"pair":"LGALS3BP -> SIGLEC7","headline":"Supported only by a BioGRID Reconstituted Complex record; our curators judged no paper to support this pair.","interaction_type":"database-asserted only","direction_and_effect":"Direction and effect are not reported in our evidence.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"BioGRID cites PMID 25320078 [DB:BioGRID]; species of the experiment is not reported in our evidence.","localisation_and_range":"Ligand carries a secreted flag [flag].","caveats":"The only support is a BioGRID record (Reconstituted Complex) [DB:BioGRID]. The curated judgment of the cited paper was 'different_entity', meaning it did not support this specific pair, so the record may be spurious (the paper's abstract names Siglec-9, -5 and -10).","key_references":[],"covers":["LR002895"]},"LR001887":{"pair":"LGI2 -> ADAM22","headline":"LGI2 co-precipitates with Adam22 from rat brain; one full-text paper, with Reactome support.","interaction_type":"direct binding","direction_and_effect":"Both Adam22 and Adam23 antibodies co-precipitated Lgi2 from rat brain [PMID:21829378]. The paper's section title states Lgi2 K518X truncation prevents LGI2 secretion and action on neuronal ADAM receptors [PMID:21829378]. Reactome lists LGI2 binding ADAM22,23 [DB:Reactome].","molecular_requirements":"Reactome lists a complex LGI2:ADAM22,23 at the plasma membrane [DB:Reactome].","affinity_potency":[],"species_and_systems":"Rat brain co-IP and cell-surface binding assay; excerpts include Lagotto Romagnolo dogs, so curator's human label does not match [PMID:21829378]. Human and mouse pairs are ortholog-inferred.","localisation_and_range":"LGI family are neuronally secreted proteins [PMID:21829378]; Reactome places the complex at the plasma membrane [DB:Reactome].","caveats":"A co-IP shows association, not direct binding; effect direction and affinity are not reported in our evidence. Reactome is the only database.","key_references":[{"PMID":"21829378","why":"Lgi2 co-IPs with Adam22/23; truncation blocks secretion"}],"covers":["LR001887","LR005229"]},"LR001896":{"pair":"LRRC4B -> PTPRD","headline":"NGL-3 (LRRC4B) interacts with PTPdelta via its first two FNIII domains and drives presynaptic differentiation only; one confirming paper plus Reactome.","interaction_type":"direct binding","direction_and_effect":"PTPdelta interacts with NGL-3 via its first two FNIII domains; this interaction instructs only presynaptic differentiation, unidirectionally [PMID:20139422]. Curators label it agonist [PMID:20139422].","molecular_requirements":"The first two FNIII domains of PTPdelta are the interacting region [PMID:20139422]. NGL-3 also binds LAR and PTPsigma, so the three LAR-family receptors compete as partners [PMID:20139422].","affinity_potency":[],"species_and_systems":"Human and rodent systems not distinguished in our evidence; curator species listed human [PMID:20139422]. Reactome lists the LRRC4B:PTPRF,PTPRS,PTPRD complex [DB:Reactome]. Both listed species are ortholog-inferred.","localisation_and_range":"Membrane-bound, contact-dependent trans-synaptic adhesion (annotation [flag]).","caveats":"Abstract only, no affinity, and two other judged papers were abstract_insufficient and four review_only. PTPRD is a paralog of PTPRF and PTPRS, which bind the same ligand, so subunit specificity is limited.","key_references":[{"PMID":"20139422","why":"NGL-3 interactions with LAR, PTPdelta and PTPsigma and their synaptic effects"}],"covers":["LR001896","LR005238"]},"LR008556":{"pair":"LTBP1 -> TGFB1","headline":"LTBP1 binds latent TGF-beta1 as a matrix-binding partner; database support only, not a signalling ligand-receptor pair.","interaction_type":"database-asserted only","direction_and_effect":"No verified paper; four judged papers were different_entity. Records describe LTBP1 binding TGF-beta (BioGRID affinity capture-western and reconstituted complex) [DB:BioGRID]; Reactome lists LTBP1, LTBP3 binding TGF-Beta [DB:Reactome]. UniProt says LAP associates with TGF-beta-1 and regulates its activation via milieu molecules such as LTBP1 [DB:UniProt].","molecular_requirements":"Reactome includes a complex LTBP1:TGFB1:LAP1 with LAP1-binding integrins [DB:Reactome]; a structure is deposited [DB:PDB 9R3S]. IntAct lists electron microscopy [DB:IntAct].","affinity_potency":[],"species_and_systems":"Species and experimental systems not reported in our evidence.","localisation_and_range":"Both partners flagged secreted [flag]; matrix association is not stated in this dossier.","caveats":"The interaction class is Ligand-Ligand; TGFB1 here is the latent complex partner, not a receptor. Do not score it as a signalling pair.","key_references":[],"covers":["LR008556"]},"LR002949":{"pair":"MDK -> RNF167","headline":"Midkine binding to the RNF167 ectodomain was seen by SPR in a CRISPRa orphan-receptor screen; single full-text paper.","interaction_type":"direct binding","direction_and_effect":"Midkine ectodomain captured on sensors bound RNF167 ectodomain by SPR; RNF128 (negative control) showed no binding [PMID:36178190]. Functional effect on RNF167 is not reported in our evidence.","molecular_requirements":"RNF167 is a transmembrane PA-TM-RING E3 ligase; the SPR used its ECD [PMID:36178190]. No co-receptor requirement reported.","affinity_potency":[],"species_and_systems":"Human proteins, recombinant ectodomains by SPR, after a cell-based CRISPRa screen [PMID:36178190]. Mouse pair is ortholog-inferred.","localisation_and_range":"Midkine is flagged secreted [flag]; RNF167 is a membrane protein per the paper [PMID:36178190], so a secreted ligand acting on a membrane receptor is plausible but not shown in cells.","caveats":"Only SPR on purified ectodomains; no affinity value reported in our excerpts. Midkine did not bind MFRP or ROR1 in the same study, showing selectivity [PMID:36178190]. RNF167 is an E3 ligase, so physiological signalling direction is unclear.","key_references":[{"PMID":"36178190","why":"SPR binding of MDK and PTN to RNF167-ECD with negative controls"}],"covers":["LR002949","LR006174"]},"LR004479":{"pair":"MFAP2 -> NOTCH1","headline":"MAGP-1 (MFAP2) binds Notch1 and activates it by ectodomain release in one abstract-only paper.","interaction_type":"direct binding","direction_and_effect":"MAGP-1 was shown to bind Notch1, cause release of the Notch1 extracellular domain and activate signalling, as an agonist [PMID:16492672].","molecular_requirements":"The paper maps MAGP-2 binding to the EGF-like repeats of Notch1 and its C-terminal domain; release needs prior furin-like cleavage but not the ADAM cleavage [PMID:16492672]. Whether these details hold for MAGP-1 is not stated.","affinity_potency":[],"species_and_systems":"Human proteins in co-expression cell assays [PMID:16492672]. Both species pairs are ortholog-inferred.","localisation_and_range":"MFAP2 is flagged secreted [flag]; the paper describes it as a microfibril protein [PMID:16492672].","caveats":"Most mechanistic work was on MAGP-2; MAGP-1 was 'predicted and further showed' from homology. Abstract only, no affinity. Non-canonical activation by ectodomain dissociation, not DSL-like ligand activation.","key_references":[{"PMID":"16492672","why":"MAGP-1/-2 bind Notch1 and induce ectodomain release and activation"}],"covers":["LR001066","LR004479"]},"LR007980":{"pair":"MICA -> HCST:KLRK1","headline":"MICA is the established ligand of the NKG2D-DAP10 complex, supported by structures, SPR records and functional papers.","interaction_type":"direct binding","direction_and_effect":"NKG2D engagement activated NK and T cell cytolysis against MICA-expressing targets [PMID:10426993]; NKG2D-DAP10 complexes may activate responses against MICA-bearing tumours [PMID:10426994]. A mouse-focused paper states human NKG2D binds MICA and MICB [PMID:10894171].","molecular_requirements":"Complex of KLRK1 (NKG2D) and HCST (DAP10); the DAP10 SH2-binding site recruits PI 3-kinase p85 for NKG2D-dependent signalling [PMID:10426994].","affinity_potency":[],"species_and_systems":"Human cells for the functional papers [PMID:10426994]. Structures and SPR in databases [DB:PDB 1HYR, DB:IntAct].","localisation_and_range":"MICA is flagged membrane-bound (transmembrane), so signalling is juxtacrine [flag].","caveats":"The only full-text paper (PMID 10894171) describes mouse NKG2D ligands and mentions MICA as background citing other work, so it is not primary MICA evidence. DAP10 contribution is from an abstract-only paper.","key_references":[{"PMID":"10426993","why":"MICA ligation of NKG2D activates cytolysis"},{"PMID":"10426994","why":"NKG2D-DAP10 receptor complex and signalling"}],"covers":["LR007980"]},"LR002958":{"pair":"MIF -> EGFR","headline":"Secreted, O-GlcNAcylated MIF binds the EGFR extracellular domain and acts as an antagonist; one full-text paper plus interaction records.","interaction_type":"direct binding","direction_and_effect":"MIF antagonizes EGFR: it blocked EGF binding and EGF-induced EGFR, ERK and c-Jun phosphorylation, invasion, proliferation and brain tumour formation. EGFR activation induces MMP13, which degrades extracellular MIF [PMID:26280537].","molecular_requirements":"MIF must be O-GlcNAcylated at Ser112/Thr113; bacterially expressed His-MIF did not block EGFR activation, whereas Flag-MIF from mammalian cells did. MIF bound the EGFR extracellular domain directly [PMID:26280537].","affinity_potency":[],"species_and_systems":"Human cells (A431, U87 and others) and purified proteins [PMID:26280537]. Mouse pair is ortholog-inferred.","localisation_and_range":"MIF is naturally secreted and acts on EGFR extracellularly [PMID:26280537]; secreted flag [flag].","caveats":"Single paper; no affinity reported. Activity depends on the modification, so recombinant bacterial MIF is not equivalent [PMID:26280537]. BioGRID and IntAct records exist [DB:BioGRID] [DB:IntAct].","key_references":[{"PMID":"26280537","why":"O-GlcNAcylated MIF binds EGFR and inhibits its activation"}],"covers":["LR002958","LR006183"]},"LR004488":{"pair":"MMP7 -> CD44","headline":"CD44 heparan sulfate proteoglycan recruits MMP-7 into a surface complex with pro-HB-EGF; mouse knockout evidence, abstract only.","interaction_type":"functional only","direction_and_effect":"CD44HSPG recruits active MMP-7 and pro-HB-EGF into a surface complex; MMP-7 processes HB-EGF and the mature HB-EGF activates ErbB4 [PMID:11825873]. In CD44-/- mice MMP-7 localisation was altered and pro-HB-EGF processing and ErbB4 activation fell [PMID:11825873].","molecular_requirements":"The complex contains CD44HSPG, MMP-7, HB-EGF and ErbB4 [PMID:11825873].","affinity_potency":[],"species_and_systems":"Tumour cell lines, and mouse postpartum uterus and lactating mammary gland, with CD44-/- mice [PMID:11825873]. BioGRID records an Affinity Capture-Western from the same PMID [DB:BioGRID]; Reactome lists a CD44:MMP2, MMP7, MMP9 complex [DB:Reactome].","localisation_and_range":"CD44 is annotated both secreted and transmembrane [flag]; the paper describes a cell-surface complex [PMID:11825873].","caveats":"CD44 acts as a docking scaffold rather than a signalling receptor for MMP-7. Direct binding is not shown in the abstract. Abstract only. The human row is not ortholog-inferred, but the experiments were in mouse and tumour cell lines.","key_references":[{"PMID":"11825873","why":"CD44-/- mice and complex assembly of CD44 with MMP-7 and pro-HB-EGF"}],"covers":["LR001076","LR004488"]},"LR006189":{"pair":"MMP9 -> RECK","headline":"MMP9 interacts with canonical RECK via its Kazal motifs; RECK is an MMP inhibitor, so this is an inhibitory interaction, not signalling.","interaction_type":"direct binding","direction_and_effect":"Canonical RECK interacts with MMP9 in an inactivating interaction; a short RECK isoform competes with MMP9 for binding to the Kazal motifs, liberating MMP9 [PMID:29874120]. Increasing short RECK reduced co-immunoprecipitation of MMP9 with long RECK by as much as 88%, with no effect on MMP2 binding [PMID:29874120].","molecular_requirements":"Binding involves the Kazal motif region of canonical (long) RECK [PMID:29874120]. UniProt also lists that RECK interacts with MMP9 [DB:UniProt].","affinity_potency":[],"species_and_systems":"Co-immunoprecipitation in RECK-/- 293T cells with overexpressed proteins, plus fibroblast migration assays [PMID:29874120].","localisation_and_range":"RECK is not annotated secreted in the dossier; localisation is not reported in our evidence.","caveats":"The paper's main subject is the short-isoform competition; the MMP9-long RECK binding is background and was shown by co-IP in overexpression. Curated as an antagonist effect: RECK inhibits MMP9. Only the abstract plus excerpts were read.","key_references":[{"PMID":"29874120","why":"Competitive co-IP showing MMP9 binds the Kazal region of long RECK"}],"covers":["LR002964","LR006189"]},"LR002967":{"pair":"MRC1 -> SIGLEC1","headline":"MRC1 cysteine-rich domain binds sialoadhesin (SIGLEC1) glycoforms; one abstract-only paper.","interaction_type":"direct binding","direction_and_effect":"CR-Fc bound selectively to sialoadhesin purified from spleen and lymph nodes [PMID:10575006].","molecular_requirements":"Binding is glycoform-specific: only the CR-Fc-binding form of sialoadhesin, with sialidase-resistant charged glycans, is recognised [PMID:10575006].","affinity_potency":[],"species_and_systems":"Mouse spleen and lymph node lysates, ligand blots with an Fc chimera [PMID:10575006].","localisation_and_range":"Both membrane proteins [flag]; SIGLEC1 also carries a secreted flag [flag].","caveats":"Abstract only; glycoform-conditional; single paper; direction (which partner is ligand) follows the curated assignment rather than the paper.","key_references":[{"PMID":"10575006","why":"Identifies sialoadhesin as CR-Fc counter-receptor"}],"covers":["LR002967","LR006192"]},"LR008448":{"pair":"MTMR4 -> SMAD3","headline":"Database-only intracellular interaction; MTMR4 binds phosphorylated SMAD2/3, not a ligand-receptor pair.","interaction_type":"database-asserted only","direction_and_effect":"MTMR4 binds phosphorylated SMAD2/3 on early endosomes [DB:Reactome R-HSA-2187405]; coimmunoprecipitation recorded [DB:IntAct P84022-Q9NYA4].","molecular_requirements":"Phosphorylated SMAD2/3 form is involved [DB:Reactome R-HSA-2187399].","affinity_potency":[],"species_and_systems":"Species not reported in our evidence beyond human annotation.","localisation_and_range":"Intracellular, early endosome membrane [DB:Reactome R-HSA-2187399].","caveats":"No verified papers (different_entity).","key_references":[],"covers":["LR008448"]},"LR006198":{"pair":"MYL12B -> CD69","headline":"Myl9/12 reported as functional CD69 ligands in mouse asthma models; abstract-only and not isoform-specific.","interaction_type":"functional only","direction_and_effect":"Myl9 and Myl12 are described as new functional ligands for CD69; blocking CD69-Myl9/12 interaction ameliorated allergic airway inflammation [PMID:28783682].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Mouse ovalbumin- and house dust mite-induced asthma models, plus human nasal polyp tissue staining [PMID:28783682].","localisation_and_range":"Ligand is flagged secreted [flag]; platelet-derived Myl9/12 localised to blood vessel luminal surfaces and net-like intravascular structures [PMID:28783682].","caveats":"Abstract only; the abstract does not give binding affinity or a binding assay. Evidence is functional (antibody blockade, in vivo) [PMID:28783682]. Myl9/12 are reported jointly; the abstract does not separate Myl12a from Myl12b. Mouse pair is ortholog-inferred.","key_references":[{"PMID":"28783682","why":"Myl9/12 identified as functional CD69 ligands; blockade reduces airway inflammation"}],"covers":["LR002973","LR006198"]},"LR004497":{"pair":"MYOC -> FZD7","headline":"Myocilin-AP fusion bound FZD7 in a browser-read Results sentence; modulates Wnt signalling.","interaction_type":"direct binding","direction_and_effect":"Myocilin-AP bound Fzd1, Fzd3, Fzd4, Fzd7, Fzd10 and sFRPs; myocilin modulated Wnt signalling and its stress fiber activity was blocked by sFRP1/sFRP3 and beta-catenin siRNA [PMID:19188438]. Effect of myocilin on the receptor (agonist versus modulator) is not clear from our evidence.","molecular_requirements":"Binding was to cysteine-rich domains of Frizzled receptors; sFRPs also bound, so Wnt pathway modulators are involved [PMID:19188438]. Co-receptor requirements not reported in our evidence.","affinity_potency":[],"species_and_systems":"Myocilin expressed in HEK293 cells, tested on human trabecular meshwork and NIH 3T3 cells; construct species for the binding sentence not stated. Mouse pair is ortholog-inferred [PMID:19188438].","localisation_and_range":"Myocilin is flagged secreted [flag]; acts as a secreted modulator in conditioned medium [PMID:19188438].","caveats":"Binding sentence was browser-read and unverified (spot-check pending); dossier abstract only. Binding is AP-fusion to receptor CRDs, not full receptor, and shared across several Fzd paralogs, so paralog specificity is weak. UniProt also records MYOC interacting with FZD7 [DB:UniProt].","key_references":[{"PMID":"19188438","why":"Myocilin-AP binding to Fzd CRDs and Wnt signalling modulation"}],"covers":["LR001086","LR004497"]},"LR009375":{"pair":"NCAM1 -> CACNA1C","headline":"Only an IntAct co-immunoprecipitation record; no verified paper.","interaction_type":"database-asserted only","direction_and_effect":"Direction and effect not reported in our evidence.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human proteins; system not reported beyond an anti-bait co-immunoprecipitation record [DB:IntAct EBI-50425795].","localisation_and_range":"Receptor annotation flags are absent for CACNA1C; not reported in our evidence.","caveats":"The only candidate paper was classed review_only, so no primary evidence was verified. A co-immunoprecipitation does not show a ligand-receptor relationship [DB:IntAct EBI-50425795].","key_references":[],"covers":["LR009375"]},"LR002976":{"pair":"NCAM1 -> CNTN2","headline":"High-affinity binding of N-CAM to TAG-1/axonin-1 (CNTN2) measured in a binding assay, read from abstract only.","interaction_type":"direct binding","direction_and_effect":"N-CAM is described as a high-affinity ligand of TAG-1/axonin-1; effect on signalling not reported in our evidence [PMID:8663515].","molecular_requirements":"Not reported in our evidence; Reactome lists an NCAM1-Contactin-2 plasma membrane complex [DB:Reactome R-HSA-375108].","affinity_potency":[{"value":"Kd approximately 1 nM","assay":"high-affinity binding assay","system":"N-CAM with TAG-1/axonin-1 (species not stated in dossier)","cite":"PMID:8663515"}],"species_and_systems":"Species of the assay proteins is not reported in our evidence; human and mouse pairs are ortholog-inferred.","localisation_and_range":"Both partners are flagged transmembrane or receptor-capable [flag]; contact-mediated adhesion is plausible but not stated in the paper text we have.","caveats":"Abstract only. The abstract focuses on neurocan and phosphacan; the N-CAM Kd is quoted in the evidence sentence as a prior demonstration. Two other rows were abstract_insufficient.","key_references":[{"PMID":"8663515","why":"N-CAM bound by TAG-1/axonin-1 with Kd about 1 nM"}],"covers":["LR002976","LR006201"]},"LR002985":{"pair":"NECTIN4 -> NECTIN1","headline":"Direct trans-interaction with 100 nM Kd shown in human nectins; selective for nectin1 among nectins.","interaction_type":"direct binding","direction_and_effect":"Soluble nectin4-Fc trans-interacts with nectin1-expressing cells but not with cells expressing nectin2, nectin3 or PVR/CD155; nectin1-Fc precipitated nectin4 and the proteins interacted in vitro [PMID:11544254]. Effect is adhesion; signalling direction not reported.","molecular_requirements":"The nectin1 V domain is the interaction region [PMID:11544254]; V-to-V contacts with C domains raising affinity, mapped to C-C'-C\"-D strands [PMID:12011057].","affinity_potency":[{"value":"KD 100 nM","assay":"nectin1/nectin4 trans-interaction","system":"recombinant human nectin ectodomains","cite":"PMID:12011057"}],"species_and_systems":"Human proteins; mouse pair is ortholog-projected [PMID:11544254] [PMID:12011057].","localisation_and_range":"Membrane-bound trans adhesion [DB:Reactome]; flags mark nectin4 and nectin1 as secreted as well [flag].","caveats":"Abstract-only reading. Weaker than nectin1/nectin3 (KD 1 nM) [PMID:12011057].","key_references":[{"PMID":"11544254","why":"Identifies nectin4 and its selective binding to nectin1"},{"PMID":"12011057","why":"KD 100 nM for nectin1/nectin4"}],"covers":["LR002985","LR006210"]},"LR011499":{"pair":"NFASC -> CNTN1:CNTNAP1","headline":"Complex-receptor pair supported by one structural paper on contactin 1 and neurofascin 155 only, which does not address CNTNAP1.","interaction_type":"direct binding","direction_and_effect":"Crystal structures show heterophilic contactin 1 - neurofascin 155 complexes via Ig1-2 interfaces [PMID:36329006]. Effect direction is not reported in our evidence.","molecular_requirements":"The receptor is listed as CNTN1 plus CNTNAP1 [flag]. The paper concerns contactin 1 and neurofascin 155, not CNTNAP1; the Reactome record lists a Neurofascin:CNTN1:CASPR complex [DB:Reactome]. Whether CNTN1 alone suffices is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Crystal structures of binding regions; species not stated in our evidence [PMID:36329006].","localisation_and_range":"Both partners are membrane proteins acting across cells in paranodal junctions, with the heterophilic complex defining 7.4 nm paranodal spacing [PMID:36329006]; neither is annotated secreted [flag].","caveats":"Paper read as abstract only. Evidence concerns CNTN1-NFASC155, so the CNTNAP1 subunit is supported only by Reactome. Most other candidate papers were judged as a different entity or review only.","key_references":[{"PMID":"36329006","why":"Structures of contactin 1 - neurofascin 155 adhesion complex"}],"covers":["LR011499"]},"LR007368":{"pair":"NODAL -> ACVR1B:ACVR2B:CFC1","headline":"Plausible Nodal complex, but the only verified evidence concerns Cripto-1, not CFC1.","interaction_type":"functional only","direction_and_effect":"Nodal bound to the type II receptor uses Cripto-1 to recruit ALK4 for SMAD2/3 activation [PMID:39840816].","molecular_requirements":"EGF-CFC co-receptor needed, but the paper names Cripto-1; ACVR2B and CFC1 are not named [PMID:39840816].","affinity_potency":[],"species_and_systems":"NTERA-2 cells, SPR, AlphaFold3 [PMID:39840816].","localisation_and_range":"Nodal flagged secreted [flag].","caveats":"Abstract only; two other papers review-only; CFC1 untested in our evidence.","key_references":[{"PMID":"39840816","why":"Cripto-1-dependent ternary complex with ALK4"}],"covers":["LR007368"]},"LR002994":{"pair":"NODAL -> BMPR2","headline":"Nodal is reported as a high-affinity BMPR2 growth factor in a human in vitro binding survey; no Nodal-specific structure.","interaction_type":"direct binding","direction_and_effect":"Among growth factors tested, the high-affinity BMPR2 ones comprise BMP15, BMP10 and Nodal; effect is agonist as curated [PMID:35643319]. BMPR2 is a type II receptor [PMID:35643319].","molecular_requirements":"BMPR2 binds growth factors at a conserved hydrophobic hot spot, via the ligand knuckle epitope; type I chain requirements for Nodal are not reported in our evidence [PMID:35643319].","affinity_potency":[],"species_and_systems":"Human ligand and receptor, in vitro binding; the crystal structures in the paper are of BMPR2 with activin B and ACVR2A with activin A, not Nodal [PMID:35643319]. Mouse pair is ortholog-inferred.","localisation_and_range":"Nodal is flagged secreted [flag].","caveats":"The Nodal result is one of 14 ligand-receptor combinations; the excerpts shown give no Nodal Kd or assay detail. Full text read, but Nodal-specific numbers are not in the excerpts.","key_references":[{"PMID":"35643319","why":"BMPR2 and ACVR2A growth factor recognition; Nodal among high-affinity BMPR2 ligands"}],"covers":["LR002994","LR006218"]},"LR004569":{"pair":"Ntf5 -> Ngfr","headline":"Mouse pair projected from human evidence; rat in vivo data show p75 dependence of NT-4 retrograde transport.","interaction_type":"functional only","direction_and_effect":"Blockade of LNR completely blocked retrograde transport of NT-4 and BDNF to sensory neurons; transport was dramatically reduced in LNR-null mice [PMID:7541633].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Adult rats and LNR-null mice, abstract only [PMID:7541633]. No database records.","localisation_and_range":"NT-4 is flagged secreted [flag]; transport is axonal retrograde.","caveats":"Ortholog-inferred; functional dependence, not binding; abstract only.","key_references":[{"PMID":"7541633","why":"p75 needed for NT-4 retrograde transport"}],"covers":["LR004569"]},"LR004578":{"pair":"NTN3 -> NEO1","headline":"Netrin-3 binds neogenin (abstract) and acts through it in myoblasts, where CDO is also required.","interaction_type":"direct binding","direction_and_effect":"Murine netrin-3 binds neogenin [PMID:10366627]. Myoblasts express netrin-3 and neogenin, which stimulate myotube formation and enhance myogenic bHLH- and NFAT-dependent transcription [PMID:15520228].","molecular_requirements":"Neogenin binds CDO in cis, and myoblasts lacking CDO respond poorly to recombinant netrin, so netrin-3/neogenin signalling needs CDO [PMID:15520228].","affinity_potency":[],"species_and_systems":"Murine netrin-3 in binding study [PMID:10366627]; myoblasts in the second paper, which the curation labels human [PMID:15520228]. Reactome lists a Netrin-3:Neogenin complex [DB:Reactome]. Mouse and human pairs are both ortholog-inferred.","localisation_and_range":"Netrin-3 is flagged secreted [flag]. The authors propose an autocrine mechanism in myoblasts [PMID:15520228].","caveats":"The binding paper was read as abstract only and gives no affinity. The myogenesis paper is functional. One abstract_insufficient row is not shown.","key_references":[{"PMID":"10366627","why":"Murine netrin-3 binds neogenin"},{"PMID":"15520228","why":"Netrin-3 and neogenin promote myotube formation; CDO needed"}],"covers":["LR001169","LR004578"]},"LR004587":{"pair":"NXPH1 -> NRXN3","headline":"Neurexophilin-1 binds neurexin-3 LNS2 with nanomolar affinity; splice insert SS2A raises it about 6-fold.","interaction_type":"direct binding","direction_and_effect":"Nxph1 binds the LNS2SS2- domains of Nrxn1, Nrxn2 and Nrxn3 with similar nanomolar affinities, and Nrxn3 LNS2SS2A+ binds Nxph1 with a ~6-fold higher affinity than LNS2SS2- [PMID:31566781]. The 1998 study found neurexophilins 1 and 3 bind LNS2 of all three alpha-neurexins [PMID:9856994].","molecular_requirements":"LNS2 domain is the binding unit. The I401Q mutation reduces Nxph1 affinity for Nrxn3 from the nanomolar to the millimolar range [PMID:31566781].","affinity_potency":[],"species_and_systems":"Mouse Nrxn3 was tested in [PMID:31566781]; recombinant mouse proteins and knockout mice in [PMID:9856994]. Both species pairs are ortholog-inferred.","localisation_and_range":"Secreted ligand [flag] and membrane neurexin [flag].","caveats":"Absolute affinity numbers are not in our excerpts. The 1998 evidence is abstract-only. The 2019 evidence sentence is not itself a result.","key_references":[{"PMID":"31566781","why":"Structures of Nxph1 with Nrxn LNS2 and isoform specificity"},{"PMID":"9856994","why":"NXPH1 and NXPH3 bind LNS2 of all three alpha-neurexins"}],"covers":["LR001178","LR004587"]},"LR008880":{"pair":"NXPH2 -> NRXN1","headline":"Weak support: the only paper purified neurexophilin (NXPH1) with neurexin I alpha, not NXPH2.","interaction_type":"database-asserted only","direction_and_effect":"A 29 kDa neurexophilin was purified in a complex with neurexin I alpha from rat brain [PMID:8699246].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Rat brain affinity chromatography; cloning in rat, bovine and mouse [PMID:8699246]. The dossier does not name NXPH2 as the bound protein.","localisation_and_range":"Not reported in our evidence beyond the secreted/transmembrane nature of the partners, which is not flagged here.","caveats":"The curator note says the purified protein is the founding neurexophilin (NXPH1), while NXPH2 is one of two distinct mouse genes found in the paper, and that no mRNA for the second gene was detected in rodents [PMID:8699246]. This is paralog-level uncertainty and the abstract was the only text read. No database records.","key_references":[{"PMID":"8699246","why":"Neurexophilin-neurexin I alpha co-purification; paralog identity uncertain"}],"covers":["LR008880"]},"LR004596":{"pair":"OSM -> LIFR","headline":"OSM uses LIFR, with human-specific binding and functional evidence plus structural mapping; gp130 is needed for high affinity.","interaction_type":"direct binding","direction_and_effect":"OSM binds the high-affinity but not the low-affinity LIF receptor [PMID:1536831]. The OSM site 3 motif (Phe160/Lys163) is responsible for LIFR and OSMR binding [PMID:10997905]. Human OSM, but not mouse OSM, also acted through LIFR in rat hepatoma cells [PMID:10854424]. OSM signalling was unaffected by deletion of the LIFR N-terminal cytokine binding domain, unlike CNTF [PMID:16051226]. GtoPdb lists OSM as agonist of LIFR [DB:GtoPdb].","molecular_requirements":"gp130 is the converting subunit giving high-affinity OSM binding to the LIFR; gp130 alone gives low-affinity OSM binding [PMID:1542794]. LIFR alone at low affinity does not bind OSM [PMID:1536831].","affinity_potency":[],"species_and_systems":"Human cell lines, COS-7 and rat hepatoma [PMID:1536831][PMID:1542794][PMID:10854424]. The mouse pair is ortholog-inferred.","localisation_and_range":"OSM is flagged secreted [flag]; the LIFR entity has a receptor flag only [flag].","caveats":"All papers read as abstracts only. Mouse OSM does not act through LIFR [PMID:10854424], so the projected mouse pair is doubtful. Structure is of OSM alone [PMID:10997905]. No affinity values in our evidence.","key_references":[{"PMID":"1536831","why":"OSM binds high-affinity LIFR"},{"PMID":"1542794","why":"gp130 converts LIFR to high affinity for OSM"},{"PMID":"10854424","why":"Human-specific LIFR use"}],"covers":["LR001187","LR004596"]},"LR006288":{"pair":"PCDHGA10 -> PCDHGA10","headline":"Mouse Pcdhga10 is homophilic in K562 aggregation assays; the only confirming paper was read via browser.","interaction_type":"functional only","direction_and_effect":"Seven \u03b3-Pcdh isoforms including A10 showed highly specific, strictly homophilic interaction in K562 quantitative and microscopic aggregation assays [PMID:20679223].","molecular_requirements":"Clustered protocadherin trans interaction is homophilic and isoform-specific; cis multimers with other isoforms may form the actual cell-surface unit, so one isoform alone may not reproduce the interface.","affinity_potency":[],"species_and_systems":"Mouse isoforms in K562 cells [PMID:20679223]; human pair is ortholog-inferred.","localisation_and_range":"Membrane-bound cell-adhesion molecule; trans homophilic contact between cells (juxtacrine), not secreted [flag].","caveats":"Curator note marks the quote as unverifiable with spot-check pending; two other papers were abstract_insufficient. Isoform-specific; paralogs cannot substitute.","key_references":[{"PMID":"20679223","why":"homophilic aggregation of seven gamma-Pcdh isoforms"}],"covers":["LR003065","LR006288"]},"LR006297":{"pair":"PCDHGA8 -> PCDHGA8","headline":"Mouse Pcdhga8 binds itself in trans (aggregation and SPR) with strict specificity versus \u03b3A9.","interaction_type":"direct binding","direction_and_effect":"\u03b3A8 and \u03b3A9 do not engage in heterophilic interactions despite 91-97% identity in EC2-EC3 [PMID:25171406]; mutations disrupting the \u03b3A8 trans interface inhibited homophilic binding [PMID:35253643].","molecular_requirements":"Clustered protocadherin trans interaction is homophilic and isoform-specific; cis multimers with other isoforms may form the actual cell-surface unit, so one isoform alone may not reproduce the interface.","affinity_potency":[],"species_and_systems":"Mouse proteins in K562 aggregation and SPR of EC1-4 fragments [PMID:25171406] [PMID:35253643]. Human pair is ortholog-inferred.","localisation_and_range":"Membrane-bound cell-adhesion molecule; trans homophilic contact between cells (juxtacrine), not secreted [flag].","caveats":"Isoforms 91-97% identical in EC2-EC3 do not cross-react, so paralogs cannot substitute [PMID:25171406]. No heterophilic binding for \u03b3A8/9 with a lower limit KD of ~200 \u03bcM [PMID:35253643].","key_references":[{"PMID":"25171406","why":"homophilic specificity"},{"PMID":"35253643","why":"trans-interface mutagenesis by SPR"}],"covers":["LR003074","LR006297"]},"LR008970":{"pair":"PCSK9 -> LDLR","headline":"PCSK9 binds the LDLR EGF-A domain, shown by crystal structure; binding leads to receptor degradation rather than signalling.","interaction_type":"direct binding","direction_and_effect":"PCSK9 binds LDLR on the cell surface, leading to its degradation [PMID:18250299]. UniProt describes the interaction as inhibiting LDLR degradation in one entry and PCSK9 as promoting degradation of LDL-receptor family members in another [DB:UniProt]; the curated modulatory effect is Inhibitory.","molecular_requirements":"The LDLR EGF-A domain binds the subtilisin-like catalytic domain of PCSK9, which contains Asp-374; the EGF-A domain does not contact the C-terminal domain or prodomain [PMID:18250299]. Arg-194 and Phe-379 mutations in PCSK9 greatly diminished binding to LDLR extracellular domain [PMID:18250299].","affinity_potency":[],"species_and_systems":"Human proteins, crystal structure and cell-surface binding [PMID:18250299]; also supported by PDB, IntAct, BioGRID and Reactome [DB:PDB 2W2M][DB:IntAct][DB:BioGRID][DB:Reactome].","localisation_and_range":"PCSK9 acts on the cell-surface LDLR; PCSK9 is not flagged secreted in the dossier.","caveats":"Paper read as abstract only [PMID:18250299]. Functionally unusual: the output is receptor degradation, not signal transduction. Direction label (ligand PCSK9) is a convention.","key_references":[{"PMID":"18250299","why":"Crystal structure of PCSK9 with LDLR EGF-A domain."}],"covers":["LR008970"]},"LR007386":{"pair":"PDGFB -> PDGFRA:PDGFRB","headline":"PDGFB acting on PDGFRB in human colorectal cancer cells is shown functionally; PDGFRA is not individually tested.","interaction_type":"functional only","direction_and_effect":"Macrophage-secreted PDGFB activates PDGFRB signalling in FADS1-positive tumour cells, driving EMT; PDGFB overexpression induced EMT markers and PDGFRB knockdown attenuated them [PMID:41655559]. Effect is agonist.","molecular_requirements":"The paper tested PDGFRB (knockdown); PDGFRA and LRP1 were named as receptors in expression-based analysis, but only PDGFRB was manipulated, so a requirement for the PDGFRA:PDGFRB heterodimer is not shown [PMID:41655559].","affinity_potency":[],"species_and_systems":"Human: THP-1-derived macrophages conditioned medium on DLD-1 colorectal cells in a transwell, plus single-cell and spatial data [PMID:41655559]. Database records (BioGRID, IntAct, PDB 3MJG, Reactome) also exist for PDGFB with each receptor chain [DB:BioGRID][DB:PDB 3MJG][DB:Reactome].","localisation_and_range":"PDGFB is flagged secreted and the receptor complex transmembrane [flag]; the paper describes a paracrine macrophage-to-tumour-cell route [PMID:41655559].","caveats":"Only one curated paper, read with full text; no direct binding or affinity in it. The heterodimer evidence is inferred from PDGFRB alone. Other binding records in databases are for single chains, not the heterodimer.","key_references":[{"PMID":"41655559","why":"Coculture and knockdown show PDGFB-PDGFRB signalling driving EMT in human CRC cells"}],"covers":["LR007386"]},"LR006792":{"pair":"PI3 -> CELA2A","headline":"No papers and no verified evidence; a single GtoPdb inhibitor record.","interaction_type":"database-asserted only","direction_and_effect":"GtoPdb lists an inhibitor action [DB:GtoPdb].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Not reported in our evidence.","localisation_and_range":"Not reported in our evidence.","caveats":"The record is an inhibitor type, not a signalling action; no affinity value in the dossier [DB:GtoPdb].","key_references":[],"covers":["LR006792"]},"LR011967":{"pair":"PORCN -> WNT7A","headline":"UniProt notes WNT7A interacts with PORCN, by similarity; three papers are still pending.","interaction_type":"database-asserted only","direction_and_effect":"UniProt states WNT7A interacts with PORCN (by similarity) [DB:UniProt].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"No judged papers; species not reported in our evidence.","localisation_and_range":"Not reported in our evidence.","caveats":"Database-only, by similarity; 3 papers are pending curation.","key_references":[],"covers":["LR011967"]},"LR004659":{"pair":"PROK2 -> PROKR1","headline":"Well supported agonist-receptor pair: PROK2 activates PROKR1 in transfected cells with pIC50 7.5 reported; abstracts only.","interaction_type":"direct binding","direction_and_effect":"Prokineticin 2 is a cognate ligand of PK-R1 (ZAQ), inducing calcium transients with nanomolar potency in CHO cells [PMID:12054613]. PK2 stimulated Ca2+ responses in PKR1-expressing cells with potency similar to PK1 and PK2beta [PMID:15772293]. GtoPdb lists full agonist [DB:GtoPdb].","molecular_requirements":"Not reported in our evidence. PK2beta, a proteolytically processed form of the PK2 long splice product, acts with similar potency at PKR1 [PMID:15772293].","affinity_potency":[{"value":"pIC50 7.5","assay":"intracellular Ca2+ response benchmark","system":"human PK2 in PKR1-expressing cells","cite":"PMID:15772293"}],"species_and_systems":"Human ligand and receptor in cell lines [PMID:12054613][PMID:15772293]; mouse pair is ortholog-inferred.","localisation_and_range":"Both PROK2 and the receptor are annotated secreted and transmembrane respectively [flag], so paracrine signalling onto membrane receptors.","caveats":"Both papers abstract-only. GtoPdb records the same two papers [DB:GtoPdb].","key_references":[{"PMID":"12054613","why":"PK2 as cognate ligand of PK-R1 with calcium flux."},{"PMID":"15772293","why":"PK2 potency at PKR1, pIC50 7.5."}],"covers":["LR001259","LR004659"]},"LR008466":{"pair":"PRSS1 -> F2RL1","headline":"Trypsin activates PAR-2 by cleavage in rat; one abstract-only paper, enzyme-substrate rather than binding.","interaction_type":"functional only","direction_and_effect":"Rat PAR-2 was activated by 300 pM trypsin and independently by the SLIGRL tethered-ligand hexapeptide; the notes interpret this as proteolytic unmasking of the tethered ligand [PMID:9349532].","molecular_requirements":"Activation is by cleavage of the PAR-2 N terminus, exposing the tethered ligand [PMID:9349532].","affinity_potency":[],"species_and_systems":"Rat hippocampus and PAR-2 expressing cells; the pair is human-annotated [PMID:9349532].","localisation_and_range":"Not reported in our evidence.","caveats":"One abstract-only paper in rat; the trypsin identity is not tied to human PRSS1 in the dossier, and one further abstract was insufficient. Activation is by protease cleavage, not reversible ligand binding.","key_references":[{"PMID":"9349532","why":"Trypsin and SLIGRL activate rat PAR-2."}],"covers":["LR008466"]},"LR010878":{"pair":"PRSS23 -> TMEM222","headline":"Only a high-throughput two-hybrid record supports this pair; no curated paper evidence.","interaction_type":"database-asserted only","direction_and_effect":"Not reported in our evidence; IntAct records physical association by two-hybrid pooling [DB:IntAct].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Species not reported in our evidence; pair annotated human.","localisation_and_range":"Not reported in our evidence.","caveats":"Support rests on a single two-hybrid pooling record [DB:IntAct]; the one judged paper was review-only. No functional, directional or ligand-receptor evidence.","key_references":[],"covers":["LR010878"]},"LR010698":{"pair":"PSAP -> CELSR1","headline":"Only a two-hybrid IntAct record supports this pair; no curated evidence.","interaction_type":"database-asserted only","direction_and_effect":"Not reported in our evidence; IntAct lists physical association by two-hybrid pooling [DB:IntAct].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Species not reported in our evidence; pair annotated human.","localisation_and_range":"PSAP flagged secreted [flag].","caveats":"Support is one high-throughput two-hybrid record [DB:IntAct]; the one judged paper was review-only.","key_references":[],"covers":["LR010698"]},"LR004668":{"pair":"PSPN -> RET","headline":"Persephin activates RET through GFRalpha4; RET alone is not the binding partner.","interaction_type":"functional only","direction_and_effect":"Persephin cross-links to GFRalpha4 and Ret and promotes Ret autophosphorylation in GFRA4-transfected cells [PMID:11116144]. UniProt states the action is via coreceptor GFRA4 [DB:UniProt].","molecular_requirements":"GFRalpha4 is the ligand-binding subunit needed with RET [PMID:11116144]; RET-only action is not shown in our evidence.","affinity_potency":[],"species_and_systems":"Human proteins in GFRA4-transfected cells [PMID:11116144].","localisation_and_range":"Ligand flagged secreted [flag].","caveats":"Abstract only. The RET interaction is indirect via the coreceptor; a RET-only expression pattern would be misleading for scoring.","key_references":[{"PMID":"11116144","why":"Cross-linking and Ret phosphorylation by PSPN via GFRalpha4."}],"covers":["LR001268","LR004668"]},"LR009618":{"pair":"PTGS2 -> CAV1","headline":"PTGS2 and CAV1 co-precipitate in BioGRID records; no verified paper and not a ligand-receptor pair.","interaction_type":"database-asserted only","direction_and_effect":"BioGRID lists affinity capture-Western and a reconstituted complex between PTGS2 and CAV1 [DB:BioGRID]. No direction or effect is reported in our evidence.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Species and system not reported in our evidence.","localisation_and_range":"Not reported in our evidence.","caveats":"No curator-confirmed papers (abstract_insufficient or different_entity). Evidence is database only.","key_references":[],"covers":["LR009618"]},"LR006828":{"pair":"PTHLH -> PRLHR","headline":"PTHrP -> PRLHR rests only on a GtoPdb agonist record; no papers in our evidence.","interaction_type":"database-asserted only","direction_and_effect":"GtoPdb records PTHLH as a full agonist of PRLHR [DB:GtoPdb].","molecular_requirements":"not reported in our evidence","affinity_potency":[],"species_and_systems":"not reported in our evidence (human entities only)","localisation_and_range":"PTHLH is flagged as secreted and PRLHR as transmembrane [flag].","caveats":"No paper was judged for this pair and the GtoPdb record gives no affinity value and no reference [DB:GtoPdb]. Treat as unverified; a PTHrP-PRLHR link is not corroborated by any binding or functional data here.","key_references":[],"covers":["LR006828"]},"LR006369":{"pair":"PTN -> ITGB3","headline":"PTN directly binds integrin alphavbeta3 in an RGD-independent manner, supported by one paper and database records.","interaction_type":"direct binding","direction_and_effect":"alphavbeta3 directly interacts with PTN, and a beta3 specificity-loop peptide inhibited the interaction and abolished PTN-induced endothelial cell migration [PMID:19141530]. UniProt records ITGAV:ITGB3 interacting with PTN [DB:UniProt].","molecular_requirements":"Binding is RGD-independent and maps to the beta3 specificity loop, residues 177-184 [PMID:19141530]. The partner alphaV chain is part of the receptor [DB:UniProt]; PTN-induced Tyr773 phosphorylation of beta3 needs RPTPbeta/zeta and c-Src [PMID:19141530].","affinity_potency":[],"species_and_systems":"Human endothelial and glioma cells [PMID:19141530]. Mouse pair is ortholog-inferred.","localisation_and_range":"PTN is flagged as secreted [flag], so signalling would be paracrine.","caveats":"Abstract only; no affinity reported. BioGRID lists an affinity capture-Western record [DB:BioGRID]. The effect depends on cell context: PTN decreased migration in alphavbeta3-negative glioma cells [PMID:19141530].","key_references":[{"PMID":"19141530","why":"Direct PTN-alphavbeta3 interaction via beta3 loop"}],"covers":["LR003148","LR006369"]},"LR004677":{"pair":"PTN -> PTPRZ1","headline":"Well supported direct PTN-PTPRZ1 binding plus functional signalling; PTN binding inactivates the phosphatase.","interaction_type":"direct binding","direction_and_effect":"PTN binds PTPRZ1 and inactivates its catalytic activity [PMID:10706604]. Ligand-induced oligomerisation inactivates the receptor, which is active as a monomer, so substrate tyrosine phosphorylation rises (curator annotation: antagonist) [PMID:16814777]. In glioblastoma, macrophage-secreted PTN drives glioma stem cell growth through PTPRZ1, with AKT phosphorylation lost when PTPRZ1 is disrupted [PMID:28569747].","molecular_requirements":"Single chain receptor; oligomerisation is needed for inactivation [PMID:16814777]. Midkine-style binding in the related paper depends on the chondroitin sulfate portion of PTPRZ1 (shown for midkine, with PTN binding competed by soluble PTN) [PMID:10212223]. Reactome lists (PTN,MDK):PTPRZ complexes [DB:Reactome]; UniProt notes a complex with integrin alpha-V/beta-3 in one function annotation [DB:UniProt].","affinity_potency":[{"value":"Kd 0.58 nM (high-affinity site; 3.0 nM low-affinity site)","assay":"solid-phase binding, Scatchard analysis (measured for midkine; PTN binding was equally inhibited by soluble PTN)","system":"human ligand, rat receptor","cite":"PMID:10212223"}],"species_and_systems":"Binding data use human ligand with rat receptor [PMID:10212223]; U373-MG human cells [PMID:10706604]; human glioma stem cells and mouse xenografts [PMID:28569747].","localisation_and_range":"PTN is flagged secreted and PTPRZ1 transmembrane [flag]; PTN acts as a paracrine signal on PTPRZ1-expressing cells [PMID:28569747].","caveats":"Three of four confirmed papers were read as abstracts only. The 0.58 nM value was measured for midkine; our evidence does not give a PTN-specific Kd. Effect is inhibitory for phosphatase activity, though downstream signalling is pro-growth.","key_references":[{"PMID":"10706604","why":"PTN binds and inactivates RPTPbeta/zeta in U373-MG cells"},{"PMID":"16814777","why":"ligand-induced oligomerisation inactivates Ptprz"},{"PMID":"28569747","why":"PTN-PTPRZ1 paracrine signalling in glioma stem cells"}],"covers":["LR001277","LR004677"]},"LR006378":{"pair":"PTPRD -> IL1RAPL1","headline":"Well supported by crystal structure, binding Kd and synaptic assays; splice-dependent trans-synaptic adhesion.","interaction_type":"direct binding","direction_and_effect":"IL1RAPL1 ectodomains induce excitatory presynapse formation by interacting with PTPdelta [PMID:21926414]. PTPdelta induces pre- and postsynaptic differentiation via binding IL1RAPL1 [PMID:25908590].","molecular_requirements":"The PTPdelta Ig1-Ig2 domains retain IL1RAPL1 binding; ratio 1:1; affinity depends on splice inserts meA9 and meB [PMID:25908590].","affinity_potency":[{"value":"Kd 0.15 uM","assay":"binding measurement, PTPdelta isoform with meA9 and meB (highest of all variants)","system":"PTPdelta ECD with IL1RAPL1 ECD","cite":"PMID:25908590"}],"species_and_systems":"Crystallography and neurons [PMID:25908590]; neurons with IL1RAPL1 ectodomains [PMID:21926414]; species not specified for the latter.","localisation_and_range":"Both flagged transmembrane [flag]; trans-synaptic. PDB 5WY8 holds the complex [DB:PDB 5WY8].","caveats":"Abstract-level evidence for curated rows, with full-text excerpts for the Kd; affinity applies to one isoform only.","key_references":[{"PMID":"25908590","why":"crystal structure and Kd of PTPdelta-IL1RAPL1"},{"PMID":"21926414","why":"IL1RAPL1 ectodomain induces presynapse via PTPdelta"}],"covers":["LR003157","LR006378"]},"LR006387":{"pair":"PTPRG -> CNTN5","headline":"PTPRG carbonic-anhydrase-like domain binds CNTN5 Ig repeats 2-3 by crystallography; one primary paper.","interaction_type":"direct binding","direction_and_effect":"PTPRG interacts with CNTN3, 4, 5 and 6, whereas PTPRZ binds only CNTN1 [PMID:20133774]. Effect direction is not reported in our evidence.","molecular_requirements":"Crystal structures show the carbonic anhydrase-like domains of PTPRZ/PTPRG interact directly with the second and third Ig repeats of contactins; the CNTN4 complex used mouse CNTN4 with mouse PTPRG's carbonic-anhydrase-like domain [PMID:20133774].","affinity_potency":[],"species_and_systems":"Curated as human proteins; the co-crystal used mouse CNTN4 and mouse PTPRG domains [PMID:20133774]. Human pair is ortholog-inferred; mouse pair is not.","localisation_and_range":"Not stated in the paper text shown; entity flags: CNTN5 flagged secreted, PTPRG not secreted [flag].","caveats":"Structure paper was read only as abstract; the abstract-level result shows PTPRG binds CNTN3, 4, 5 and 6 and no affinity is reported in our evidence. Curator note says this pair is stored four times (both directions, human and mouse) for one interaction. The CNTN5 evidence is the family-level statement, not a CNTN5-specific structure.","key_references":[{"PMID":"20133774","why":"Crystal structures of PTPRG/PTPRZ with contactins; CNTN specificity"}],"covers":["LR003166","LR006387"]},"LR005289":{"pair":"PVR -> NECTIN3","headline":"PVR-nectin3 trans-binding is stated in one paper's abstract (as prior work) and supported by database records; no new primary data in our evidence.","interaction_type":"direct binding","direction_and_effect":"Nectin3 is described as binding PVR in a trans-hetero-interaction network of nectins [PMID:12011057]. UniProt notes that trans-interaction with PVR activates CDC42 and RAC [DB:UniProt].","molecular_requirements":"Not reported in our evidence for this pair; the paper mapped nectin3 binding on a nectin1 V domain using PVR chimeras, not PVR-nectin3 binding itself [PMID:12011057].","affinity_potency":[],"species_and_systems":"Human proteins [PMID:12011057]. Mouse pair is projected from human evidence (ortholog inferred). Database records include surface plasmon resonance and solid phase assay (IntAct), a reconstituted complex (BioGRID) and Reactome trans-heterodimer [DB:IntAct][DB:BioGRID][DB:Reactome].","localisation_and_range":"Nectins are adhesion molecules at adherens junctions, with trans-interactions between ectodomains of adjacent cells [PMID:12011057]. PVR is also flagged secreted [flag].","caveats":"The only paper restates the authors' earlier network and read as abstract only; curators noted PVR is only a scaffold there. Affinity for PVR-nectin3 not reported. Direction (which partner is ligand) is not defined in the evidence; the interaction is trans-homophilic-style adhesion.","key_references":[{"PMID":"12011057","why":"States the nectin3-PVR interaction (background to the study); abstract only"}],"covers":["LR001953","LR005289"]},"LR006396":{"pair":"PVRIG -> NECTIN2","headline":"PVRIG inhibits human CD8+ T cells via NECTIN2 (PVRL2) in functional assays; direct binding is not shown by this paper.","interaction_type":"functional only","direction_and_effect":"PVRIG is a coinhibitory receptor of the DNAM/TIGIT/CD96 nectin family that binds PVRL2; the inhibitory effect of PVRL2 was mediated by PVRIG and not TIGIT [PMID:30659054]. Blocking PVRIG raised CD8+ T-cell cytokine production and cytotoxicity, and combining with TIGIT or PD-1 blockade increased activation further [PMID:30659054]. Biologically NECTIN2 is the ligand on tumour or myeloid cells and PVRIG the inhibitory receptor on T cells.","molecular_requirements":"Not reported in our evidence. An antibody (COM701) blocking PVRIG-PVRL2 interaction was used [PMID:30659054].","affinity_potency":[],"species_and_systems":"Human CD8+ T cells (pp65-specific) co-cultured with human tumour lines, and human tumour-infiltrating lymphocytes [PMID:30659054]. PDB structures contain chains of both partners [DB:PDB 8X6B][DB:PDB 9E6Y].","localisation_and_range":"PVRIG flag shows not secreted [flag]; PVRL2 was seen on CD45- cells and CD14+ cells in tumours [PMID:30659054]. Signalling is contact-based (cell-surface).","caveats":"This paper's binding statement is background; the excerpt cites an earlier report of 88 nmol/L affinity, which is not this paper's result. Read depth in the dossier row is abstract only although excerpts exist. The pair is written PVRIG -> NECTIN2 (PVRIG as 'ligand'), opposite the biological direction.","key_references":[{"PMID":"30659054","why":"Functional PVRIG-PVRL2 inhibitory axis in CD8+ T cells, distinct from TIGIT-PVR"}],"covers":["LR003176","LR006396"]},"LR004686":{"pair":"RARRES2 -> CMKLR1","headline":"Chemerin is a well-supported agonist of CMKLR1, with binding, signaling and vascular functional data, plus GtoPdb and PDB records.","interaction_type":"direct binding","direction_and_effect":"Chemerin activates CMKLR1 (ChemR23): calcium release, inhibition of cAMP accumulation and p42-p44 MAPK phosphorylation through Gi proteins, with chemotaxis of immature dendritic cells and macrophages [PMID:14530373]. Chemerin and chemerin-9 activate Galphai and Galphao subtypes and recruit beta-arrestin1/2 at CMKLR1 [PMID:27716822]. In human vessels, chemerin acts at CMKLR1, not GPR1, to cause vasoconstriction [PMID:27742615]. GtoPdb lists a full agonist [DB:GtoPdb].","molecular_requirements":"The proform has low activity; proteolytic removal of the C-terminal domain gives a potent agonist, the circulating form being residues 21 to 154 [PMID:14530373, PMID:14675762]. Chemerin-9 (149-157) retains most activity; Tyr149, Phe150, Gly152, Phe154, Phe156 are key [PMID:14701797]. Single GPCR chain, no co-receptor reported.","affinity_potency":[{"value":"KD of respectively 0.88 nM","assay":"saturation binding, [125I]-chemerin","system":"CHO-K1 cells expressing human CMKLR1","cite":"PMID:27716822"},{"value":"KD=0.28\u00b10.07 nmol/L","assay":"radiolabeled chemerin-9 binding","system":"CHO-K1 cells expressing human CMKLR1","cite":"PMID:27742615"},{"value":"pD2=8.45\u00b10.10","assay":"inhibition of forskolin-evoked cAMP accumulation, full-length chemerin","system":"CMKLR1 cell-based assay","cite":"PMID:27742615"}],"species_and_systems":"Human proteins in recombinant cells, primary human cells and human vessels; the mouse pair is inferred from human evidence (ortholog_inferred).","localisation_and_range":"Chemerin is flagged secreted, so paracrine/endocrine; CMKLR1 is transmembrane [flag]. Chemerin was abundant in human inflammatory fluids [PMID:14530373].","caveats":"Four rows are pending. Chemerin-9 is biased toward cAMP inhibition over beta-arrestin recruitment at CMKLR1, so readout matters [PMID:27742615]. Some papers read as abstract only. The mouse pair has no direct mouse evidence here.","key_references":[{"PMID":"14530373","why":"Chemerin characterized as processed ChemR23 agonist"},{"PMID":"14701797","why":"Chemerin-9 minimal agonist, residue mapping"},{"PMID":"27716822","why":"Binding and signaling of three chemerin receptors"}],"covers":["LR001287","LR004686"]},"LR004695":{"pair":"RGMB -> NEO1","headline":"RGMB physically interacts with neogenin and inhibits migration of dentate precursors; supported by a dedicated paper and a generic RGM paper.","interaction_type":"direct binding","direction_and_effect":"Co-immunoprecipitation and binding assays indicate a strong physical interaction; RGMb abolished in vitro and in vivo migration of dentate neuroepithelial cells and reduced cell adhesion (antagonist) [PMID:19944164]. A PDB structure with RGMB and NEO1 chains is recorded [DB:PDB 4UI2].","molecular_requirements":"Not reported in our evidence beyond the two partners.","affinity_potency":[{"value":"sub-nanomolar","assay":"expression cloning binding (RGM generically)","system":"chick","cite":"PMID:15258590"}],"species_and_systems":"Developing dentate gyrus, organotypic slices and in utero electroporation [PMID:19944164]; chick retina for the generic RGM paper [PMID:15258590].","localisation_and_range":"RGMB is not flagged secreted [flag]; contact-mediated reduction of adhesion between neogenin and RGMb cells [PMID:19944164].","caveats":"Both abstract-only. The second paper refers to RGM generically, not RGMB specifically [PMID:15258590].","key_references":[{"PMID":"19944164","why":"Neogenin-RGMb interaction and migration inhibition"},{"PMID":"15258590","why":"Neogenin as an RGM receptor (generic RGM)"}],"covers":["LR001296","LR004695"]},"LR001959":{"pair":"ROBO2 -> ROBO2","headline":"ROBO2 homophilic ectodomain interaction, from one abstract-only paper plus an IntAct record.","interaction_type":"direct binding","direction_and_effect":"Robo2 extracellular domain is a homophilic adhesion molecule [PMID:12504588]; the interaction is symmetric and no agonist or antagonist effect is reported.","molecular_requirements":"Blocked by antibody to the first Ig domain of Robo1/2 or soluble Robo-Fc [PMID:12504588]; stoichiometry not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human Robo2 in transfected 3T3 cells with primary neurons [PMID:12504588]. Mouse pair is projected.","localisation_and_range":"Robo2 carries both secreted and membrane flags [flag]; trans adhesion per the paper [PMID:12504588].","caveats":"Abstract only. IntAct 'polymerization' record cites the same paper [DB:IntAct]. A self-pair, so ligand and receptor roles are not distinguishable.","key_references":[{"PMID":"12504588","why":"Homophilic Robo2 adhesion"}],"covers":["LR001959","LR005292"]},"LR008439":{"pair":"ROR2 -> FZD2","headline":"Ror2 CRD associates with rat Frizzled-2 by co-immunoprecipitation; one abstract-only paper.","interaction_type":"direct binding","direction_and_effect":"Ror2 associates via its CRD with rFz2, a putative Wnt5a receptor [PMID:12839624]. Wnt5a and Ror2 activate non-canonical Wnt signalling, assessed by JNK activation in cultured cells and inhibition of convergent extension in Xenopus [PMID:12839624].","molecular_requirements":"The Ror2 extracellular cysteine-rich domain (CRD) mediates the association [PMID:12839624].","affinity_potency":[],"species_and_systems":"Mouse Ror2 CRD with rat Frizzled-2 in co-immunoprecipitation; Xenopus for convergent extension [PMID:12839624]. The dossier pair is human.","localisation_and_range":"Both cell-surface receptors [flag].","caveats":"Abstract only (re-read via protein aliases). Co-IP does not prove direct binding, and the species differ from the human pair.","key_references":[{"PMID":"12839624","why":"Ror2 CRD associates with Frizzled-2"}],"covers":["LR008439"]},"LR010959":{"pair":"RSPO3 -> WNT1","headline":"Ligand-ligand pair resting only on UniProt interaction annotations; no curated paper supports it.","interaction_type":"database-asserted only","direction_and_effect":"Not reported in our evidence; the interaction is classed Ligand-Ligand with a stimulatory modulatory flag [flag].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"No experimental system in our evidence. UniProt P04628 (WNT1) lists RSPO1, RSPO2 and RSPO3 as interactors, and Q9BXY4 lists WNT1, both by similarity [DB:UniProt].","localisation_and_range":"Both RSPO3 and WNT1 are flagged secreted [flag].","caveats":"The one judged row was classed as a different entity, and no papers were judged. The UniProt statements are marked by similarity [DB:UniProt]. Treat as weakly supported.","key_references":[],"covers":["LR010959"]},"LR006459":{"pair":"SAA1 -> TLR2","headline":"SAA activates TLR2 signalling and binds the TLR2 ectodomain in one abstract-level study; moderately supported.","interaction_type":"direct binding","direction_and_effect":"TLR2-expressing HeLa cells responded to SAA with NF-kappaB activation, MAPK phosphorylation and IkappaBalpha degradation; a solid-phase binding assay showed SAA interaction with the TLR2 ectodomain [PMID:18566366]. SAA-induced gene expression was selectively reduced in tlr2-/- mouse macrophages [PMID:18566366].","molecular_requirements":"TLR1 co-expression enhanced the response, and TIR-deletion mutants of TLR1, TLR2 and TLR6 blocked it [PMID:18566366].","affinity_potency":[],"species_and_systems":"Human SAA and TLR2 in HeLa cells, plus mouse macrophages for knockout data [PMID:18566366].","localisation_and_range":"Secreted ligand acting on a membrane receptor [flag].","caveats":"Read as abstract only; no affinity reported. A second confirmed paper exists but is not shown.","key_references":[{"PMID":"18566366","why":"TLR2 as functional SAA receptor: binding and signalling"}],"covers":["LR003243","LR006459"]},"LR007395":{"pair":"SCT -> VIPR2","headline":"Supported only by GtoPdb agonist records; no curator-verified paper for this pair.","interaction_type":"database-asserted only","direction_and_effect":"GtoPdb lists secretin as an agonist at VIPR2 with pIC50 units [DB:GtoPdb]. Direction beyond that is not reported in our evidence.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Species and experimental system are not reported in our evidence; the pair rests on database records only.","localisation_and_range":"Secretin is flagged secreted and VIPR2 transmembrane [flag].","caveats":"No papers were verified for this pair (no judged papers). The two GtoPdb records cite papers PMID:9437714 and PMID:9928018, but those were not verified here for VIPR2 [DB:GtoPdb].","key_references":[],"covers":["LR007395"]},"LR006468":{"pair":"SCUBE2 -> PTCH1","headline":"SCUBE2 is reported to interact with PTCH1 and enhance SHH signalling; one abstract-only paper.","interaction_type":"direct binding","direction_and_effect":"Human SCUBE2 interacts with SHH and with PTCH1 and enhances SHH signalling in cholesterol-rich raft microdomains, acting as a positive component upstream of ligand binding [PMID:19480626]. UniProt notes the PTCH1 interaction [DB:UniProt].","molecular_requirements":"SCUBE2 engages both SHH and PTCH1; the spacer region and cysteine-rich repeats matter for membrane association [PMID:19480626]. It functions as a co-regulator, not a classical ligand.","affinity_potency":[],"species_and_systems":"Human SCUBE2 overexpressed as recombinant protein, with biochemical and reporter assays; the human and mouse pairs are ortholog-inferred [PMID:19480626].","localisation_and_range":"Secreted but surface-anchored glycoprotein when overexpressed, active in lipid rafts [PMID:19480626]; SCUBE2 flagged secreted [flag].","caveats":"Single paper read from abstract only; no affinity and the assay type is not detailed. The interaction is as a co-regulator of SHH-PTCH1.","key_references":[{"PMID":"19480626","why":"SCUBE2 interacts with SHH and PTCH1 and boosts SHH signalling"}],"covers":["LR003252","LR006468"]},"LR006477":{"pair":"SELPLG -> SIGLEC1","headline":"Sialoadhesin binds PSGL-1 in one mouse study, read as abstract only; thin support.","interaction_type":"direct binding","direction_and_effect":"Sialoadhesin-Fc fusion proteins precipitated a 240-kDa glycoprotein from murine TK-1 T cells that was identified as PSGL-1 (CD162) [PMID:11238599]. Which partner signals is not reported; effect on cells is not reported in our evidence.","molecular_requirements":"Binding to the glycoproteins was sialic acid dependent and abolished by the R97A mutation in the sialic acid binding site of sialoadhesin [PMID:11238599]. The paper's main finding concerns CD43 as counterreceptor.","affinity_potency":[],"species_and_systems":"Mouse sialoadhesin-Fc and mouse TK-1 T cells [PMID:11238599]. The human pair is inferred from the mouse evidence (ortholog_inferred).","localisation_and_range":"The receptor is flagged secreted and transmembrane [flag]; the experiment used the membrane form on cells binding a soluble Fc fusion [PMID:11238599].","caveats":"Only one paper, read as abstract only; PSGL-1 is a secondary finding after CD43. No database records. Binding is glycan-mediated rather than protein-protein [PMID:11238599].","key_references":[{"PMID":"11238599","why":"Sialoadhesin-Fc precipitates PSGL-1 from mouse T cells"}],"covers":["LR003261","LR006477"]},"LR006486":{"pair":"SEMA3D -> PLXND1","headline":"Co-immunoprecipitation in pancreatic cancer and zebrafish genetics support SEMA3D acting via PlexinD1; both papers abstract-level.","interaction_type":"functional only","direction_and_effect":"Secreted Sema3D co-immunoprecipitated with plexin D1 on PDA cells and promoted metastasis [PMID:26243191]. In zebrafish, mesenchymal Sema3d repels the common cardinal vein through PlexinD1 [PMID:27799363].","molecular_requirements":"PlexinD1 is described as a co-receptor in the PDA paper [PMID:26243191]; in zebrafish it acted independently of Nrp1 for the repulsion function [PMID:27799363].","affinity_potency":[],"species_and_systems":"Mouse KPC pancreatic cancer model [PMID:26243191]; zebrafish embryos [PMID:27799363]. The curator lists species as human for both; the mouse pair is not ortholog-inferred.","localisation_and_range":"SEMA3D is annotated secreted [flag]; autocrine in PDA cells [PMID:26243191] and mesenchymal paracrine in zebrafish [PMID:27799363].","caveats":"Both read as abstracts; co-IP is in cells not purified protein; effect labels differ (agonist vs antagonist) by context. No affinity data.","key_references":[{"PMID":"26243191","why":"Sema3D co-IP with PlxnD1 in pancreatic cancer"},{"PMID":"27799363","why":"Mesenchymal Sema3d repulsion via PlexinD1 in zebrafish"}],"covers":["LR003270","LR006486"]},"LR004749":{"pair":"SEMA3F -> NRP1","headline":"NRP1 reported as a SEMA3F receptor by binding screen and cell assays; mixed abstract-level and full-text evidence.","interaction_type":"direct binding","direction_and_effect":"SEMA3F inhibited cell contacts, with loss of membrane E-cadherin and beta-catenin, in NRP1-only MCF7 cells [PMID:15802023]. The 1997 paper states neuropilin-1 binds Sema III, Sema E and Sema IV with high affinity [PMID:9331348].","molecular_requirements":"NRP1 alone suffices in MCF7 cells, which express only NRP1 [PMID:15802023]. A screen reports direct Sema-Nrp interactions without specifying plexin needs [PMID:26633812].","affinity_potency":[],"species_and_systems":"Human cells and proteins in the cited papers [PMID:15802023][PMID:9331348][PMID:26633812]. The mouse pair is ortholog-inferred.","localisation_and_range":"SEMA3F is annotated secreted [flag].","caveats":"Mostly abstract-only. In the C100 line, repulsion was blocked by anti-NRP2 and not tested against anti-NRP1 [PMID:15802023]. The 1997 sentence shown concerns NRP2 selectivity. Mapping Sema IV to SEMA3F is from curator notes. Other confirmed rows are not shown; no affinity reported.","key_references":[{"PMID":"9331348","why":"NRP1 binds Sema IV; NRP2 identified"},{"PMID":"15802023","why":"SEMA3F acts on NRP1-only MCF7 cells"},{"PMID":"26633812","why":"Biochemical screen of Sema-Nrp binding"}],"covers":["LR001353","LR004749"]},"LR001968":{"pair":"SEMA4A -> PLXNB1","headline":"Sema4A binds Plexin-B1 in COS-7 transfection assays and signals through it in neurons; abstract-level.","interaction_type":"direct binding","direction_and_effect":"Sema4A binds Plexin-B1, -B2 and -B3 in transfected COS-7 cells; Rnd1 with Plexin-B1 induced cell contraction [PMID:20043131]. Sema4A signals via postsynaptic Plexin-B1 to promote inhibitory synapse development [PMID:29981480].","molecular_requirements":"Rnd1 was co-expressed for contraction signalling [PMID:20043131]. Plexin-B1 alone suffices for binding in COS-7 [PMID:20043131].","affinity_potency":[],"species_and_systems":"COS-7 cells and mouse hippocampal neurons [PMID:20043131]; rodent hippocampus [PMID:29981480]. Curator tags say human.","localisation_and_range":"SEMA4A is flagged secreted and PLXNB1 transmembrane [flag]. IntAct lists a cross-linking study [DB:IntAct].","caveats":"Both papers read as abstracts only. Binding is not specific to Plexin-B1 (also B2, B3). Two papers are stated; others were review_only or insufficient.","key_references":[{"PMID":"20043131","why":"binding to Plexin-B1 and contraction via Rnd1"},{"PMID":"29981480","why":"Sema4A via Plexin-B1 promotes inhibitory synapses"}],"covers":["LR001968","LR005298"]},"LR005298":{"pair":"SEMA4A -> PLXNB1","headline":"Sema4A binds Plexin-B1 in COS-7 transfection assays and signals through it in neurons; abstract-level.","interaction_type":"direct binding","direction_and_effect":"Sema4A binds Plexin-B1, -B2 and -B3 in transfected COS-7 cells; Rnd1 with Plexin-B1 induced cell contraction [PMID:20043131]. Sema4A signals via postsynaptic Plexin-B1 to promote inhibitory synapse development [PMID:29981480].","molecular_requirements":"Rnd1 was co-expressed for contraction signalling [PMID:20043131]. Plexin-B1 alone suffices for binding in COS-7 [PMID:20043131].","affinity_potency":[],"species_and_systems":"COS-7 cells and mouse hippocampal neurons [PMID:20043131]; rodent hippocampus [PMID:29981480]. Curator tags say human.","localisation_and_range":"SEMA4A is flagged secreted and PLXNB1 transmembrane [flag]. IntAct lists a cross-linking study [DB:IntAct].","caveats":"Both papers read as abstracts only. Binding is not specific to Plexin-B1 (also B2, B3). Two papers are stated; others were review_only or insufficient.","key_references":[{"PMID":"20043131","why":"binding to Plexin-B1 and contraction via Rnd1"},{"PMID":"29981480","why":"Sema4A via Plexin-B1 promotes inhibitory synapses"}],"covers":["LR001968","LR005298"]},"LR004758":{"pair":"SEMA4D -> PLXNB1","headline":"SEMA4D-PLXNB1 is a well-established receptor pair with binding, functional and structural database support.","interaction_type":"direct binding","direction_and_effect":"Plexin-B1 is a receptor for Sema4D (CD100) [PMID:10520995]. Sema4D triggers invasive growth through Plexin B1/Met [PMID:12198496], and acts on platelets via plexin-B1 [PMID:17244710]. In mouse hippocampus, Sema4D-Plexin-B1 regulates inhibitory synapse development without affecting excitatory synapses [PMID:29981480].","molecular_requirements":"Plexin-B1 is sufficient for binding; Met and ErbB-2 are associated co-receptors for signalling [PMID:12198496][DB:Reactome]. Active Rac enhances Sema4D binding to plexin-B1 [PMID:11937491].","affinity_potency":[],"species_and_systems":"Human recombinant and cell assays [PMID:10520995][PMID:11937491]; mouse hippocampal neurons [PMID:29981480]. PDB 3OL2 gives a structure of the pair [DB:PDB 3OL2]; IntAct surface plasmon resonance [DB:IntAct]. Mouse pair is ortholog-inferred.","localisation_and_range":"Sema4D flagged secreted and transmembrane [flag]; platelet work shows membrane form followed by ADAM17 shedding [PMID:17244710].","caveats":"Papers were read as abstracts, except 29981480 with excerpts. No affinity in our evidence. In 11937491 Sema4D binding is a readout of Rac effects, not the paper's subject.","key_references":[{"PMID":"10520995","why":"Plexin-B1 assigned as Sema4D receptor"},{"PMID":"11937491","why":"Sema4D binding to plexin-B1 regulated by Rac"},{"PMID":"12198496","why":"Plexin B1-Met coupling"}],"covers":["LR001362","LR004758"]},"LR006495":{"pair":"SEMA4D -> PTPRC","headline":"SEMA4D (CD100) is physically associated with CD45 on human T cells; this is an association, not clearly a ligand-receptor pair.","interaction_type":"direct binding","direction_and_effect":"CD100 is associated with CD45 at the surface of human T lymphocytes, and the association has functional significance in T cell homotypic adhesion [PMID:8955171]. Direction and effect as ligand to receptor are not reported in our evidence.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human T lymphocytes [PMID:8955171]. BioGRID Affinity Capture-Western [DB:BioGRID]; Reactome complex SEMA4D:PTPRC [DB:Reactome]; IntAct co-immunoprecipitation [DB:IntAct]. Mouse pair is ortholog-inferred.","localisation_and_range":"PTPRC flagged transmembrane, not secreted [flag]; SEMA4D is flagged secreted and transmembrane [flag].","caveats":"One paper, abstract only; co-association evidence does not show that CD45 acts as a signalling receptor for SEMA4D.","key_references":[{"PMID":"8955171","why":"CD100 associates with CD45 on T cells"}],"covers":["LR003279","LR006495"]},"LR004767":{"pair":"SEMA7A -> PLXNC1","headline":"Direct binding is supported by structural and biophysical database records and two papers, though both papers are abstract-only.","interaction_type":"direct binding","direction_and_effect":"Plexin-C1 is described as a receptor for the GPI-anchored semaphorin Sema7A [PMID:10520995]. Human melanocytes express Plexin C1, a receptor for Semaphorin 7a, and Sema7a affects melanocyte dendricity [PMID:17671519]. Effect is annotated stimulatory.","molecular_requirements":"No co-receptor requirement is reported in our evidence.","affinity_potency":[],"species_and_systems":"Species of the first paper unspecified; human melanocytes in the second. Human pair is not ortholog-inferred, mouse pair is.","localisation_and_range":"Ligand is GPI-anchored per the abstract [PMID:10520995]; flagged secreted and transmembrane [flag]. Reactome places the complex at the plasma membrane [DB:Reactome].","caveats":"Both papers abstract only; neither gives affinity. Database records include ITC, X-ray crystallography and solid phase assay and PDB 3NVQ [DB:IntAct][DB:PDB 3NVQ].","key_references":[{"PMID":"10520995","why":"Plexin-C1 identified as a Sema7A receptor"},{"PMID":"17671519","why":"Melanocytes express Plexin C1, a Sema7a receptor"}],"covers":["LR001371","LR004767"]},"LR004776":{"pair":"SFRP1 -> FZD2","headline":"SFRP1 interacts with Frizzled-2 and acts through it to steer axon growth cones; one abstract-only paper.","interaction_type":"functional only","direction_and_effect":"SFRP1 reoriented retinal ganglion cell axon growth, and Fz2 knockdown abolished growth cone responses, so the authors propose guidance via Fz2 [PMID:16172602]. Curators label the effect agonist although SFRP1 is classically a Wnt inhibitor.","molecular_requirements":"The activity did not require Wnt inhibition; intracellular signalling needs G(alpha) activation [PMID:16172602].","affinity_potency":[],"species_and_systems":"Chick and Xenopus laevis retinal ganglion cell axons [PMID:16172602]; dossier labels species human. Both human and mouse pairs here are ortholog-projected.","localisation_and_range":"SFRP1 is flagged secreted [flag]; acts as a diffusible guidance cue per the paper [PMID:16172602].","caveats":"Abstract says SFRP1 interacts with Fz2 but binding data are not reported in our evidence. One further row is pending.","key_references":[{"PMID":"16172602","why":"SFRP1 guides growth cones through Fz2"}],"covers":["LR001381","LR004776"]},"LR011787":{"pair":"SFRP1 -> WNT3","headline":"Only computational docking supports this pair; SFRP1 had among the lowest predicted affinities for Wnt3.","interaction_type":"database-asserted only","direction_and_effect":"Docking indicated SFRP3 has the highest binding affinity to Wnt3, while SFRP1 and SFRP5 have the lowest [PMID:40372458]. Antagonistic activity is argued to rest on SFRP1's positively charged NTR domain raising local concentration [PMID:40372458].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"In silico modelling and docking only [PMID:40372458].","localisation_and_range":"SFRP1 is flagged secreted [flag]; ligand-ligand class.","caveats":"No experimental binding; abstract only; three other papers were abstract_insufficient.","key_references":[{"PMID":"40372458","why":"Docking comparison of SFRP family binding to Wnt3"}],"covers":["LR011787"]},"LR004785":{"pair":"SHH -> PTCH1","headline":"SHH binds PTCH1 directly, with structures, biochemical papers and database support; PTCH1 is the canonical receptor.","interaction_type":"direct binding","direction_and_effect":"Shh binding to PTCH is described as preventing PTCH inhibition of SMO [PMID:9811851]. Vertebrate Patched1 inhibition is caused by direct, palmitate-dependent interaction with Shh; a palmitoylated N-terminal fragment binds Patched1 and is sufficient to inhibit it [PMID:27647915]. UniProt: negative regulator of the smoothened pathway [DB:UniProt].","molecular_requirements":"The Shh N-terminal palmitoylated fragment binds, while the rest of Shh confers high-affinity binding [PMID:27647915]. UniProt: two PTCH1 molecules engage one hedgehog [DB:UniProt]; cryo-EM structures [DB:PDB 6DMY] [DB:PDB 6E1H].","affinity_potency":[],"species_and_systems":"PTCH binds all hedgehog family members with similar affinity and can form a complex with SMO [PMID:9811851]; Patched1 work with species unspecified [PMID:27647915]. Mouse pair is primary; human ortholog-inferred.","localisation_and_range":"SHH is flagged secreted [flag]; PTCH1 is a multitransmembrane receptor [PMID:9811851].","caveats":"Both papers are abstract-only. No numeric affinity in the dossier. Several other papers were abstract-insufficient, pending or review-only.","key_references":[{"PMID":"27647915","why":"Direct palmitate-dependent Shh-Patched1 binding"},{"PMID":"9811851","why":"PTCH and PTCH2 bind hedgehog proteins"}],"covers":["LR001390","LR004785"]},"LR009276":{"pair":"SHH -> SMO","headline":"SHH-SMO has no confirmed evidence; the papers judged were of a different entity or insufficient.","interaction_type":"database-asserted only","direction_and_effect":"UniProt describes SHH acting via patched to relieve smoothened inhibition, which is indirect [DB:UniProt]. SMO is activated by cholesterol in response to hedgehog morphogens [DB:UniProt].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human; no experiments in our evidence.","localisation_and_range":"Not reported in our evidence.","caveats":"No papers confirmed: two judged different_entity and four abstract_insufficient. The records say SHH acts through PTCH, not on SMO directly, so this may not be a direct ligand-receptor pair.","key_references":[],"covers":["LR009276"]},"LR001977":{"pair":"SIGLEC1 -> SPN","headline":"Sialoadhesin (SIGLEC1) binds CD43 (SPN) on mouse T cells in a sialic acid dependent manner.","interaction_type":"direct binding","direction_and_effect":"Sialoadhesin-Fc precipitated CD43 (130 kDa) from murine T cells; CD43 expressed in COS cells supported increased binding to immobilized sialoadhesin, identifying CD43 as a T cell counterreceptor [PMID:11238599].","molecular_requirements":"Binding is sialic acid dependent and abolished by the R97A mutation in the sialic acid binding site of sialoadhesin; it binds core-1 and core-2 O-linked glycoforms [PMID:11238599]. A single chain suffices.","affinity_potency":[],"species_and_systems":"Murine T cell line TK-1, COS cells and CHO cells [PMID:11238599]. Human pair is ortholog-inferred.","localisation_and_range":"Both are membrane proteins (receptor flagged transmembrane [flag]); cell-cell contact interaction between macrophages and T cells [PMID:11238599].","caveats":"Abstract-only. One more paper was abstract-insufficient. IntAct has a solid phase assay record [DB:IntAct]. No affinity.","key_references":[{"PMID":"11238599","why":"Sialoadhesin binds CD43 on T cells"}],"covers":["LR001977","LR005307"]},"LR001986":{"pair":"SLIT3 -> ROBO1","headline":"SLIT3-ROBO1 is supported by mouse knockout phenotypes and co-expression; direct binding not shown in the papers' abstracts.","interaction_type":"functional only","direction_and_effect":"Slit3 and Robo1 knockout mice both show osteopenia, and osteoclast-secreted SLIT3 stimulates osteoblast migration and proliferation via beta-catenin [PMID:29504949]. In endothelial cells Robo1 is named a cognate receptor, but the migration effect is attributed to Robo4 [PMID:19741192].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Mouse knockouts, human circulating SLIT3 association and ovariectomy rescue [PMID:29504949]; mouse endothelial cells [PMID:19741192]. Dossier covers human and mouse pairs.","localisation_and_range":"SLIT3 secreted; autocrine and paracrine, from osteoclasts or endothelial/smooth muscle cells [PMID:29504949][PMID:19741192].","caveats":"Both papers abstract only. PMID:19741192 does not test Robo1 separately. Reactome lists a ROBO1:SLIT3 complex [DB:Reactome]; UniProt records cited concern SLIT1/SLIT2 [DB:UniProt].","key_references":[{"PMID":"29504949","why":"Slit3 and Robo1 knockout osteopenia"},{"PMID":"19741192","why":"Slit3 angiogenesis; Robo1/Robo4 expression"}],"covers":["LR001986","LR005315"]},"LR001995":{"pair":"SLITRK6 -> PTPRS","headline":"SLITRK6-PTPsigma is supported by a knockdown/rescue synapse assay; binding not directly shown.","interaction_type":"functional only","direction_and_effect":"Knockdown of PTPsigma substrates (N-cadherin, p250RhoGAP) or liprin-alpha2/3 in neurons inhibited Slitrk6-induced, PTPsigma-mediated heterologous synapse formation [PMID:29934346].","molecular_requirements":"Intracellular PTPsigma partners are needed downstream; the receptor-side requirements for binding are not reported in our evidence [PMID:29934346].","affinity_potency":[],"species_and_systems":"Cultured rat hippocampal neurons [PMID:29934346]. Both pairs ortholog-inferred.","localisation_and_range":"Trans-synaptic; SLITRK6 flagged transmembrane [flag].","caveats":"Abstract only; the paper tests downstream pathway components, not binding. Four review-only rows not shown.","key_references":[{"PMID":"29934346","why":"Slitrk6-induced PTPsigma synapse assay"}],"covers":["LR001995","LR005324"]},"LR004794":{"pair":"SOST -> LRP5","headline":"Sclerostin binds LRP5 and LRP6 and antagonises canonical Wnt signalling; two papers plus database records.","interaction_type":"direct binding","direction_and_effect":"Sclerostin antagonises canonical Wnt signalling in A293T and MC3T3 cells, reversed by LRP5 overexpression [PMID:15778503]. SOST binds the LRP5/6 ectodomain and disrupts Wnt-induced Frizzled-LRP complex formation in Xenopus embryos and mammalian cells [PMID:15908424].","molecular_requirements":"Binding maps to the first two YWTD-EGF repeat domains of LRP5; canonical Wnt did not appear to compete with sclerostin for LRP5 binding [PMID:15778503]. Sclerostin binds LRP6 as well as LRP5 [PMID:15778503].","affinity_potency":[],"species_and_systems":"Human A293T cells, mouse MC3T3 osteoblastic cells and Xenopus embryos [PMID:15778503][PMID:15908424]. Both human and mouse pairs are ortholog-inferred. BioGRID and IntAct also list records [DB:BioGRID][DB:IntAct].","localisation_and_range":"SOST is flagged secreted and LRP5 as a transmembrane receptor [flag]; sclerostin acts on osteoblast cells [PMID:15778503].","caveats":"Both papers were read as abstracts only. No affinity reported. Binding is to LRP5 and LRP6 together, so paralog specificity is not resolved. Pairs are ortholog-inferred.","key_references":[{"PMID":"15778503","why":"Sclerostin binds LRP5/6 and maps the binding domain"},{"PMID":"15908424","why":"SOST binds LRP5/6 ectodomain and disrupts Frizzled-LRP complex"}],"covers":["LR001399","LR004794"]},"LR006558":{"pair":"TAFA5 -> S1PR2","headline":"FAM19A5 is proposed to act through S1PR2 to limit neointima formation; evidence is a single abstract.","interaction_type":"functional only","direction_and_effect":"FAM19A5 overexpression markedly inhibited vascular smooth muscle cell proliferation and migration and neointima formation after injury, and the title says it acts through S1PR2 [PMID:29453251]. The abstract lists radioligand binding, receptor internalization and calcium mobilization assays to identify the receptor, but its results for them are not in our excerpt [PMID:29453251]. UniProt calls S1PR2 the receptor for FAM19A5 [DB:UniProt].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Rat carotid balloon injury and mouse femoral wire injury in vivo; cultured vascular smooth muscle cells [PMID:29453251].","localisation_and_range":"FAM19A5 is described as a secreted adipokine, with a 43-amino-acid signal peptide [PMID:29453251]; S1PR2 annotated transmembrane receptor [flag].","caveats":"Abstract only, and the visible text is truncated before the receptor results. The UniProt record rests on the same paper [DB:UniProt].","key_references":[{"PMID":"29453251","why":"FAM19A5 inhibits neointima formation via S1PR2"}],"covers":["LR003355","LR006558"]},"LR006567":{"pair":"TFF3 -> LINGO2","headline":"LINGO2 pulls down with TFF3, co-localizes at the membrane and is required for TFF3 function in one paper.","interaction_type":"direct binding","direction_and_effect":"TFF3-LINGO2 interaction disrupts inhibitory EGFR-LINGO2 complexes, enhancing EGFR signalling and allowing TFF3 to block apoptosis [PMID:31562318]. Anti-LINGO2 antibody at high doses blocked TFF3-induced IL-10 production in U937 cells [PMID:31562318].","molecular_requirements":"The LINGO2 extracellular LRR region is needed: an N-terminal truncation (delta 350 AA) abrogated co-localization with TFF3 [PMID:31562318].","affinity_potency":[],"species_and_systems":"Human U937 and HEK293 cells, murine MC38 cells and Lingo2-deficient mice; co-immunoprecipitation used murine TFF3-Fc with Flag-tagged LINGO2 [PMID:31562318]. The human pair is ortholog-inferred; the mouse pair is not.","localisation_and_range":"TFF3 is annotated secreted [flag]; localisation of LINGO2 binding is on the epithelial cell membrane, within 40 nm by proximity ligation [PMID:31562318].","caveats":"Evidence is co-IP and co-localization, with no affinity reported. Only the abstract plus excerpts were read. The same paper found no membrane co-localization of TFF3 with CXCR4 in HEK293 cells [PMID:31562318].","key_references":[{"PMID":"31562318","why":"LINGO2 as TFF3 receptor and EGFR derepression"}],"covers":["LR003366","LR006567"]},"LR004839":{"pair":"TGFB1 -> TGFBR2","headline":"Canonical type II receptor, but the one curated paper concerns ALK1 binding; most support comes from databases.","interaction_type":"direct binding","direction_and_effect":"The curated paper shows ALK1 in endothelial cells binds TGF-beta1 and TbetaR-II [PMID:10716993]. GtoPdb lists agonist [DB:GtoPdb]; records include SPR, co-IP and cross-linking [DB:IntAct] and structures [DB:PDB 3KFD].","molecular_requirements":"Type I receptor partner not specified in this dossier beyond ALK1 in the paper [PMID:10716993].","affinity_potency":[],"species_and_systems":"Mouse cells and knockout mice [PMID:10716993]; human pair is ortholog-inferred.","localisation_and_range":"TGFB1 is flagged secreted [flag]. Receptor localisation not reported in our evidence.","caveats":"The paper does not test TGF-beta1 binding to TbetaR-II itself; abstract only. Two review-only papers excluded. Main support is from databases [DB:BioGRID].","key_references":[{"PMID":"10716993","why":"ALK1 binds TGF-beta1 and TbetaR-II in endothelial cells"}],"covers":["LR001444","LR004839"]},"LR006576":{"pair":"TGFB3 -> ITGB6","headline":"Integrin beta6 (as alphaVbeta6) binds the TGF-beta3 prodomain, with structural evidence; chain-only row.","interaction_type":"direct binding","direction_and_effect":"alphaVbeta6 binds RGDLXXL/I in TGF-beta1 and TGF-beta3 prodomains with high affinity [PMID:25383667], and binds and activates latent TGFbeta3 [PMID:11821050]. A PDB structure exists [DB:PDB 4UM9].","molecular_requirements":"The LXXL/I helix binds a hydrophobic pocket in the beta6 subunit; heterodimer needed [PMID:25383667].","affinity_potency":[],"species_and_systems":"Structure and peptide affinity (species not stated); 2002 work in unspecified species [PMID:11821050].","localisation_and_range":"Ligand secreted, annotated transmembrane [flag].","caveats":"The bound species is the latency-associated peptide (LAP) complex, not mature TGF-beta. Integrin activates latent TGF-beta; abstract-only.","key_references":[{"PMID":"25383667","why":"Crystal structure of alphaVbeta6 with prodomain motif"},{"PMID":"11821050","why":"alphaVbeta6 binds and activates latent TGFbeta3"}],"covers":["LR003375","LR006576"]},"LR004848":{"pair":"TGFB3 -> TGFBR3","headline":"TGF-beta3 binds betaglycan (TGFBR3), a co-receptor, in purified-protein SPR assays; well supported but abstract-level for most evidence.","interaction_type":"direct binding","direction_and_effect":"Betaglycan is a coreceptor for TGF-beta superfamily members [PMID:19842711]. GtoPdb lists the interaction as agonist [DB:GtoPdb]. Soluble betaglycan blocks TGF-beta activity [PMID:19842711].","molecular_requirements":"Betaglycan has two independent ligand-binding regions, membrane-distal and membrane-proximal, and the 45 and 55 kDa fragments each bind TGF-beta but neutralise poorly; tethering the domains gives high affinity [PMID:19842711]. The type III ectodomain bound two TGF-beta molecules [PMID:11382746].","affinity_potency":[{"value":"Kd low nanomolar range (soluble betaglycan, three TGF-beta isoforms)","assay":"SPR","system":"soluble betaglycan","cite":"PMID:19842711"}],"species_and_systems":"Soluble betaglycan was rat and expressed in insect cells; fragment labelling used 125I-TGF-beta2, not beta3 [PMID:19842711]. Species in [PMID:11382746] unspecified.","localisation_and_range":"Betaglycan is flagged transmembrane [flag]; soluble forms also bind [PMID:19842711].","caveats":"Direct-binding data are for betaglycan alone; signalling-receptor requirements are not reported in our evidence. Species is rat for the main paper; the pair is human.","key_references":[{"PMID":"19842711","why":"Two binding domains in betaglycan, SPR Kd"},{"PMID":"11382746","why":"SPR with type III receptor ectodomain"}],"covers":["LR001453","LR004848"]},"LR004857":{"pair":"THBS1 -> CD36","headline":"Well-supported: THBS1 is a ligand of CD36 with gain/loss-of-function, co-IP, peptide and knockout evidence; effects vary by context.","interaction_type":"direct binding","direction_and_effect":"Sense CD36 transfection gave TSP binding and antisense removed it, supporting a TSP receptor role [PMID:1379600]. THBS1 interacts with CD36 and inhibits cAMP signalling and trophoblast fusion, abolished by a CD36-blocking antibody [PMID:33997182]. TSP-1 ligation of CD36 on monocytes inhibits lymphangiogenesis [PMID:21536744]. CD36 blocking antibody inhibited latent TGF-beta1 activation [PMID:10487979]. The CSVTCG peptide stimulates osteoclast resorption [PMID:10772961].","molecular_requirements":"The CD36-binding region of TSP-1 is represented by CSVTCG [PMID:10772961]. Binding was 1:1 with CD36 expression [PMID:1379600].","affinity_potency":[],"species_and_systems":"Human melanoma cells [PMID:1379600]; human BeWo cells [PMID:33997182]; mouse corneas [PMID:21536744]; rat alveolar macrophages [PMID:10487979]; avian osteoclasts [PMID:10772961].","localisation_and_range":"THBS1 is flagged secreted and CD36 transmembrane [flag]; TSP-1 acts on platelets and cell surfaces [PMID:1379600].","caveats":"Effects are inhibitory or stimulatory depending on cell type, so direction is context dependent. Most papers were read as abstracts. In [PMID:10772961] and [PMID:10487979] CD36 involvement is functional, not direct binding.","key_references":[{"PMID":"1379600","why":"Gain and loss of function show CD36 binds TSP"},{"PMID":"33997182","why":"THBS1-CD36 co-IP, cAMP inhibition"},{"PMID":"21536744","why":"TSP-1 ligation of CD36 in vivo"}],"covers":["LR001462","LR004857"]},"LR004866":{"pair":"THBS1 -> SDC1","headline":"Syndecan-1 supports cell spreading and fascin-spike formation on THBS1 in transfection assays; functional evidence, not direct binding.","interaction_type":"functional only","direction_and_effect":"Syndecan-1 transfection of COS-7 cells is sufficient to stimulate spreading and fascin spike assembly on TSP-1 [PMID:11257118]. It is necessary for spreading and spike formation by C2C12 cells on TSP-1 in the VC2-deletion and GAG-negative mutant experiments [PMID:11257118]. Stimulatory effect.","molecular_requirements":"Requires glycosaminoglycan modification at S45 or S47 for spreading and the cytoplasmic VC2 region for spreading and spike formation [PMID:11257118]. Syndecan-2 in COS-7 stimulated spreading but not fascin spikes [PMID:11257118].","affinity_potency":[],"species_and_systems":"Mouse syndecan-1 in green monkey COS-7 and C2C12 cells, TSP-1 as substrate [PMID:11257118]; curated species human, mouse ortholog-inferred. Full text was available.","localisation_and_range":"THBS1 flagged secreted; acts as immobilised matrix substrate, so matrix-contact signalling [flag] [PMID:11257118]. SDC1 carries both secreted and transmembrane flags [flag].","caveats":"No direct physical binding shown in the dossier; antibody ligation and transfection only. One review-only row excluded.","key_references":[{"PMID":"11257118","why":"Syndecan-1 sufficient/necessary for fascin spikes on TSP-1"}],"covers":["LR001471","LR004866"]},"LR006585":{"pair":"THBS1 -> TGFBR1","headline":"One 2024 abstract reports THBS1 interacting with TbetaRI and ITGAV in prostate cancer cells; other details not available.","interaction_type":"direct binding","direction_and_effect":"THBS1 mediates cell migration by interacting with ITGAV and TbetaRI; deletion of TbetaRI or THBS1 prevents migration and invasion [PMID:39304722]. Curation labels agonist, but this is not shown by the abstract.","molecular_requirements":"THBS1 interacts with both ITGAV and TbetaRI in this paper [PMID:39304722]; whether either alone suffices is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Castration-resistant prostate cancer cells (human), CRISPR/siRNA, xenograft [PMID:39304722].","localisation_and_range":"THBS1 is flagged secreted [flag]; TGFbeta induces its production [PMID:39304722].","caveats":"Abstract only; the interaction techniques are not named in the dossier. Interaction direction is odd for a ligand-receptor pair as TbetaRI normally binds TGFb1 [PMID:39304722].","key_references":[{"PMID":"39304722","why":"TbetaRI/ITGAV and THBS1 in prostate cancer migration"}],"covers":["LR003384","LR006585"]},"LR006594":{"pair":"THY1 -> ITGAM","headline":"Thy-1 binds Mac-1 (alphaM-beta2) and the isolated alphaM I-domain; two abstract-only papers.","interaction_type":"direct binding","direction_and_effect":"Thy-1 on endothelium mediates leukocyte adhesion and transendothelial migration via Mac-1 [PMID:15004192]. alphaM I-domain also binds Thy-1, with roughly half the affinity of alphaX [PMID:15850796].","molecular_requirements":"Evidence at the Mac-1 (CD11b/CD18, alphaMbeta2) heterodimer level; the alphaM I-domain alone binds Thy-1 [PMID:15004192][PMID:15850796].","affinity_potency":[],"species_and_systems":"Human: monocytes, PMNs, Thy-1 transfectants, dermal microvascular endothelial cells, purified proteins [PMID:15004192]; recombinant I-domain binding [PMID:15850796].","localisation_and_range":"Membrane-bound on both sides [flag]; juxtacrine leukocyte-endothelium contact [PMID:15004192].","caveats":"Both papers abstract only; alphaM affinity is given only relative to alphaX and no absolute value is reported for alphaM [PMID:15850796]. Beta2 chain involvement is not separated here.","key_references":[{"PMID":"15004192","why":"Thy-1 identified as Mac-1 counterreceptor"},{"PMID":"15850796","why":"alphaM I-domain affinity relative to alphaX"}],"covers":["LR003393","LR006594"]},"LR003399":{"pair":"THY1 -> SDC4","headline":"Thy-1 binds syndecan-4 at single-molecule level and cooperates with alpha5beta1; one abstract-only paper.","interaction_type":"direct binding","direction_and_effect":"Thy-1 independently binds syndecan-4; with alpha5beta1 present they bind cooperatively, forming a trimolecular complex showing 'dynamic catch' [PMID:25216363].","molecular_requirements":"Syndecan-4 alone suffices for binding, but alpha5beta1 and Syn4 together bind cooperatively [PMID:25216363].","affinity_potency":[],"species_and_systems":"Single-molecule force spectroscopy; melanoma cells; human [PMID:25216363].","localisation_and_range":"Membrane-bound; contact-dependent.","caveats":"Abstract only; no affinity values; mouse pair is ortholog-inferred.","key_references":[{"PMID":"25216363","why":"Thy-1 binds Syn4 and alpha5beta1"}],"covers":["LR003399","LR006600"]},"LR004875":{"pair":"TIMP3 -> AGTR2","headline":"TIMP-3 identified as binding AGTR2 by yeast two-hybrid and co-IP records; functional data suggest additive anti-angiogenic action.","interaction_type":"direct binding","direction_and_effect":"A human ovary cDNA two-hybrid screen identified AGTR2 as a TIMP-3-interacting partner; combined TIMP-3 and AGTR2 treatment additively inhibited VEGF-induced HUVEC proliferation and blocked the inhibition of Akt and eNOS phosphorylation [PMID:18344519]. BioGRID and IntAct list two-hybrid and co-IP records from the same paper [DB:BioGRID][DB:IntAct].","molecular_requirements":"not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human cDNA library, HUVECs and an ovarian cancer experimental model [PMID:18344519]; mouse pair is ortholog-inferred.","localisation_and_range":"TIMP3 is flagged secreted; AGTR2 flagged transmembrane receptor [flag].","caveats":"Single paper read as abstract; all database records derive from it. No affinity reported, and whether TIMP-3 binds the AGTR2 ligand-binding site is not reported in our evidence.","key_references":[{"PMID":"18344519","why":"Two-hybrid identification and functional study"}],"covers":["LR001480","LR004875"]},"LR004884":{"pair":"TNC -> ITGB1","headline":"Beta1 integrin pairs (alpha7beta1, alpha9beta1, alpha2beta1) mediate responses to tenascin-C; three papers, mostly abstract-only.","interaction_type":"functional only","direction_and_effect":"Alpha7beta1 associated with tenascin-C VFDNFVLK peptides, and function-blocking anti-alpha7 and anti-beta1 antibodies abolished neurite outgrowth [PMID:14715956]. TNC and integrin alpha9beta1 were essential for lung metastasis in xenografts [PMID:29259017]. Anti-beta1 mAb inhibited endothelial attachment to tenascin up to 80% [PMID:7693733].","molecular_requirements":"Beta1 acts with different alpha chains (alpha7, alpha9, alpha2) [PMID:14715956][PMID:29259017][PMID:7693733].","affinity_potency":[],"species_and_systems":"Human cells and mouse xenograft [PMID:29259017]; cerebellar granule neurons [PMID:14715956]; HUVEC [PMID:7693733].","localisation_and_range":"Ligand flagged as secreted, non-transmembrane [flag]; presented as extracellular matrix, so acts locally on adjacent cells.","caveats":"Single-chain entry; alpha partner determines the interaction. Three more rows abstract_insufficient.","key_references":[{"PMID":"14715956","why":"alpha7beta1 and TNC peptide"},{"PMID":"29259017","why":"TNC/alpha9beta1 in metastasis"},{"PMID":"7693733","why":"alpha2beta1 in endothelial attachment"}],"covers":["LR001489","LR004884"]},"LR004893":{"pair":"TNFSF13 -> TNFRSF13B","headline":"APRIL binds TACI with nanomolar affinity and signals NF-kappaB; one abstract-only paper plus several interaction databases.","interaction_type":"direct binding","direction_and_effect":"TACI interacts with APRIL at nanomolar affinity, and APRIL can signal through TACI to NF-kappaB responses in HEK293 cells [PMID:10956646]. Interaction annotated stimulatory [flag].","molecular_requirements":"Reactome lists a complex of soluble BAFF/APRIL with three TACI plus BCMA [DB:Reactome]; subunit requirements are not tested in our papers.","affinity_potency":[{"value":"nanomolar affinity","assay":"binding of APRIL to TACI (abstract wording, no exact value)","system":"human proteins, HEK293T/HEK293 cells","cite":"PMID:10956646"}],"species_and_systems":"Human proteins in HEK293 cells [PMID:10956646]; mouse pair is projected from human by orthology.","localisation_and_range":"APRIL flagged secreted, TACI transmembrane [flag].","caveats":"Paper read as abstract only; APRIL binds TACI about an order of magnitude weaker than BLyS per curator notes. Also supported by BioGRID, IntAct, GtoPdb and Reactome records [DB:BioGRID][DB:IntAct][DB:GtoPdb][DB:Reactome].","key_references":[{"PMID":"10956646","why":"TACI binds APRIL with nanomolar affinity; NF-kappaB signalling"}],"covers":["LR001502","LR004893"]},"LR006639":{"pair":"UNC5C -> FLRT3","headline":"Extracellular binding of UNC5C and FLRT3 shown in a mouse-protein screen; one full-text paper, no affinity.","interaction_type":"direct binding","direction_and_effect":"Binding was seen in an ELISA-based screen with AP/Fc-tagged extracellular domains, with every FLRT1-3 x Unc5A-D pair reported at or near saturation (mean Abs650nm value = 2.14) [PMID:26633812]. Titration with purified protein and CHO.K1 cell aggregation confirmed the family pairs [PMID:26633812]. In this paper Unc5-expressing neurons are repelled by FLRT, so FLRT acts as ligand and Unc5 as receptor, the reverse of the listed direction [PMID:26633812]. ","molecular_requirements":"Extracellular domains of both partners are used; no co-receptor or extra subunit is reported in our evidence.","affinity_potency":[],"species_and_systems":"Mouse proteins in recombinant ELISA and cell-aggregation assays; the human pair is ortholog-inferred and the mouse pair is the direct one [PMID:26633812].","localisation_and_range":"UNC5C is annotated as a transmembrane receptor and FLRT3 as both secreted and transmembrane [flag]; contact-mediated signalling is likely, but this is not tested here.","caveats":"The binding statement is family-wide rather than specific to this pair. Pair-specific functional data are absent. Unc5C stripes repelled 11% of neurons (n=45/396), but FLRT3 was not expressed by Unc5C-repelled neurons in the data shown [PMID:26633812]. UniProt records the extracellular-domain interaction by similarity [DB:UniProt].","key_references":[{"PMID":"26633812","why":"Extracellular screen and titration binding of all FLRT x Unc5 pairs, mouse proteins"}],"covers":["LR003438","LR006639"]},"LR004929":{"pair":"VEGFA -> ITGB1","headline":"VEGF-A binds integrin alpha9beta1, so ITGB1 is supported only as the beta chain of that heterodimer.","interaction_type":"direct binding","direction_and_effect":"VEGF-A is described as a direct ligand for alpha9beta1; adhesion and migration of human endothelial cells are dependent on it, and a blocking antibody inhibited angiogenesis [PMID:17363377].","molecular_requirements":"The receptor is the alpha9beta1 heterodimer, so ITGB1 alone is chain-only evidence and needs ITGA9. VEGFR-2 cooperates [PMID:17363377].","affinity_potency":[],"species_and_systems":"Human endothelial cells [PMID:17363377].","localisation_and_range":"Not reported in our evidence.","caveats":"One paper, abstract only, and it does not test ITGB1 independently of alpha9. Other beta1 integrin pairings are not covered.","key_references":[{"PMID":"17363377","why":"VEGF-A direct ligand for alpha9beta1"}],"covers":["LR001540","LR004929"]},"LR009735":{"pair":"VEGFA -> ITGB3","headline":"No verified paper; only Reactome records that describe alphaVbeta3 binding VEGFR2.","interaction_type":"database-asserted only","direction_and_effect":"Reactome lists a VEGFA:p-6Y-VEGFR2:Integrin alphaVbeta3 complex [DB:Reactome]. Direction and effect not reported in our evidence.","molecular_requirements":"Would require ITGAV as partner chain; not reported in our evidence beyond the Reactome complex name [DB:Reactome].","affinity_potency":[],"species_and_systems":"Not reported in our evidence.","localisation_and_range":"Not reported in our evidence.","caveats":"Rests on database records alone; curator judgements were review-only or abstract-insufficient.","key_references":[],"covers":["LR009735"]},"LR004938":{"pair":"VEGFC -> KDR","headline":"VEGF-C activates KDR (VEGFR-2) in addition to FLT4; foundational papers and structures support it.","interaction_type":"direct binding","direction_and_effect":"VEGF-C induces tyrosine autophosphorylation of VEGFR-2 and binds KDR [PMID:8617204] [PMID:8612600]; curators label the effect stimulatory and agonist.","molecular_requirements":"No complex requirement reported in our evidence. VEGF-C also acts through FLT4 [PMID:8617204].","affinity_potency":[],"species_and_systems":"Human ligand and receptor, abstract-level reading [PMID:8612600]. Mouse pair is ortholog-inferred.","localisation_and_range":"VEGFC flagged secreted [flag]; KDR a transmembrane kinase receptor per the pair name's family, flag not shown here.","caveats":"The placenta paper is weak for this pair: its VEGF-C experiment reads out VEGFR-3 rather than VEGFR-2 [PMID:11332691]. Supporting structures [DB:PDB 2X1W], [DB:BioGRID] co-crystal record. No affinity in our evidence.","key_references":[{"PMID":"8617204","why":"VEGF-C activates VEGFR-2 and VEGFR-3"},{"PMID":"8612600","why":"VEGF-C binds Flt4 and KDR"}],"covers":["LR001549","LR004938"]},"LR008619":{"pair":"VSIR -> IGSF11","headline":"Weak: one paper measured VISTA binding to VSIG3 by ELISA; the dossier does not state that VSIG3 is IGSF11.","interaction_type":"direct binding","direction_and_effect":"Soluble VISTA-Fc bound plate-coated VSIG3-Fc at pH 6.0; an anti-VISTA antibody (SG7) blocked this binding [PMID:32938950]. Functional effect of the binding is not reported in our evidence.","molecular_requirements":"VISTA mutations (e.g. R54, Q63) affected binding to VSIG3; F62A increased it [PMID:32938950].","affinity_potency":[{"value":"80 \u00b1 20 nM","assay":"ELISA, apparent affinity of VISTA-Fc for VSIG3-Fc at pH 6.0","system":"cell-free soluble proteins, human","cite":"PMID:32938950"}],"species_and_systems":"Cell-free ELISA with human Fc-fusion proteins [PMID:32938950].","localisation_and_range":"Both partners are flagged non-secreted; VSIR transmembrane [flag]; membrane-bound, contact-dependent range is implied by flags only.","caveats":"The paper calls VSIG3 and PSGL-1 'purported' VISTA partners [PMID:32938950]. Study is mainly an antibody-engineering paper; binding was a side assay. Three further papers were abstract_insufficient.","key_references":[{"PMID":"32938950","why":"VISTA-VSIG3 ELISA affinity at pH 6.0"}],"covers":["LR008619"]},"LR006648":{"pair":"VTCN1 -> BTLA","headline":"Thin evidence: one abstract-only paper states B7x is a ligand of BTLA; no binding data in our evidence.","interaction_type":"functional only","direction_and_effect":"The abstract states B7x is a ligand of BTLA, an inhibitory receptor with two ITIMs that recruits SHP-1/SHP-2 and attenuates IL-2 [PMID:12796776]. Whether the interaction is activating or inhibitory is not reported in our evidence beyond BTLA being inhibitory.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Species not specified by the curated row [PMID:12796776]; mouse pair is annotated as non-inferred and human as ortholog-inferred.","localisation_and_range":"Neither partner is flagged secreted; BTLA transmembrane [flag].","caveats":"Single abstract sentence; no binding assay, affinity or subunit detail. The dossier uses 'B7x' and does not itself state it equals VTCN1.","key_references":[{"PMID":"12796776","why":"Identifies BTLA and reports B7x as its ligand"}],"covers":["LR003447","LR006648"]},"LR004947":{"pair":"VTN -> ITGA5","headline":"No support for alpha5 as a vitronectin receptor; the one judged paper pairs vitronectin with alphaVbeta3 instead.","interaction_type":"database-asserted only","direction_and_effect":"Direction and effect are not reported in our evidence. The one judged paper was marked pair_absent: it consistently links vitronectin to alphaVbeta3, not alpha5beta1 [PMID:11331280].","molecular_requirements":"Not reported in our evidence for ITGA5. The Reactome records shown list alphaVbeta1, alphaVbeta3, alpha3beta5 and alphaIIBbeta3, not alpha5beta1 [DB:Reactome].","affinity_potency":[],"species_and_systems":"The negative paper used human ovarian cancer cells (OV-MZ-6) [PMID:11331280].","localisation_and_range":"Vitronectin is flagged as secreted and not transmembrane [flag]; the integrin is a membrane receptor, so signalling is by cell contact with soluble or matrix-bound ligand. The dossier's papers do not describe range further.","caveats":"Verified negative [PMID:11331280] (abstract only); 7 further papers had insufficient abstracts and 2 were pair_absent in total. The only positive signal is a database assertion [DB:Reactome]. Alpha5 likely belongs to a fibronectin receptor rather than a vitronectin one per the curator note, but this is not shown directly.","key_references":[{"PMID":"11331280","why":"Verified negative: vitronectin linked to alphaVbeta3, not alpha5beta1"}],"covers":["LR001558","LR004947"]},"LR004956":{"pair":"VTN -> PVR","headline":"CD155 (PVR) binds vitronectin directly by SPR with a Kd of 72 nM; one abstract-only paper.","interaction_type":"direct binding","direction_and_effect":"CD155 binds vitronectin specifically, and both colocalise on follicular dendritic cells and B cells in tonsil germinal centres [PMID:11437656]. Signalling effect is not reported in our evidence.","molecular_requirements":"No co-receptor or subunit requirement is reported in our evidence.","affinity_potency":[{"value":"Kd 72 nM","assay":"surface plasmon resonance","system":"human CD155 and vitronectin","cite":"PMID:11437656"}],"species_and_systems":"Human protein experiments; the mouse pair is ortholog-inferred [PMID:11437656]. A BioGRID reconstituted-complex record cites the same paper [DB:BioGRID].","localisation_and_range":"Vitronectin is flagged secreted; PVR is flagged secreted, receptor and transmembrane [flag]. The paper describes cell-to-matrix contact [PMID:11437656].","caveats":"Abstract-only read. The paralogue mPRR2 binds vitronectin only weakly [PMID:11437656], so paralogs are not interchangeable. The database record rests on the same paper.","key_references":[{"PMID":"11437656","why":"SPR binding of CD155 to vitronectin, Kd 72 nM"}],"covers":["LR001567","LR004956"]},"LR006657":{"pair":"VWF -> LRP1","headline":"Macrophage LRP1 helps clear VWF; binding is shear-dependent; one abstract-only paper.","interaction_type":"direct binding","direction_and_effect":"VWF-coated beads adhered to LRP1 only above 2.5 dyne/cm(2) shear; half-life of human VWF was increased in macrophage LRP1-deficient mice [PMID:22234691]. LRP1 acts as a clearance receptor.","molecular_requirements":"A beta2-integrin mechanism binding both VWF and LRP1 is implicated, as beta2-integrin inhibition raised VWF in control but not macLRP1- mice [PMID:22234691].","affinity_potency":[],"species_and_systems":"Human VWF in mice with macrophage-specific LRP1 deficiency; basal VWF 1.6 +/- 0.4 vs 1.0 +/- 0.4 U/mL [PMID:22234691]. Both listed pairs are ortholog-inferred.","localisation_and_range":"Macrophage cell surface receptor clearing plasma VWF [PMID:22234691].","caveats":"Abstract-only. Binding was detected only under shear; the paper notes earlier reports of no interaction. No affinity reported.","key_references":[{"PMID":"22234691","why":"macrophage LRP1 and shear-dependent VWF binding"}],"covers":["LR003457","LR006657"]},"LR004965":{"pair":"WNT1 -> FZD8","headline":"WNT1 signals via FZD8 in a human reporter-cell knockout panel; BioGRID lists a reconstituted complex.","interaction_type":"functional only","direction_and_effect":"Wnt1, Wnt8a, Wnt7b, Wnt8b and Wnt10a induced signalling via FZD5 and FZD8 in an FZD knockout panel, a stimulatory effect on TCF reporter signalling [PMID:28733458]. BioGRID lists a WNT1-FZD8 reconstituted complex [DB:BioGRID].","molecular_requirements":"FZD8 and FZD5 were both responsive; FZD8 is not unique. Co-receptors not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human HEK293 reporter cells with multiplex CRISPR FZD knockouts, full text [PMID:28733458]. The mouse pair is projected from human.","localisation_and_range":"WNT1 is flagged as secreted [flag], so signalling would be paracrine or autocrine; this comes from the annotation flag, not from a paper.","caveats":"The curator's sentence summarises the paper's interaction map; it is not a binding assay. Two further papers were abstract_insufficient or pending.","key_references":[{"PMID":"28733458","why":"Functional Wnt-FZD interaction map"}],"covers":["LR001576","LR004965"]},"LR010779":{"pair":"WNT10B -> FZD3:LRP6","headline":"Complex-level pair with no curated paper; rests on one IntAct co-immunoprecipitation record only.","interaction_type":"database-asserted only","direction_and_effect":"Direction and effect (agonist or antagonist) not reported in our evidence. The only support is an IntAct record of association by anti-tag coimmunoprecipitation [DB:IntAct EBI-21797268].","molecular_requirements":"Receptor is listed as a two-chain complex; whether both chains, or either alone, are required is not reported in our evidence. ","affinity_potency":[],"species_and_systems":"Pair is human; the experimental system of the IntAct record is not reported in our evidence.","localisation_and_range":"Ligand is flagged secreted [flag]; the receptor chains are flagged as receptors, with LRP chain transmembrane [flag]. Range is not otherwise reported in our evidence.","caveats":"Only one paper row, judged review-only; the pair rests on the database record alone.","key_references":[],"covers":["LR010779"]},"LR006666":{"pair":"WNT10B -> FZD4","headline":"Functional evidence from an abstract: WNT-10B stimulation dissociated a FZD4-G protein complex in live human cells.","interaction_type":"functional only","direction_and_effect":"The FZD4-Galpha12/13 complex dissociates upon stimulation with WNT-3A, WNT-5A, WNT-7A and WNT-10B, so WNT10B acts on FZD4 as an activating ligand in this readout [PMID:27458145].","molecular_requirements":"FZD4 assembles with Galpha12/13 in a DVL-independent manner, not with Galphai1, Galphao, Galphas or Galphaq; LRP involvement not reported in our evidence [PMID:27458145].","affinity_potency":[],"species_and_systems":"Live-cell FRAP imaging in HEK293 cells with human FZD4 [PMID:27458145]; mouse pair is ortholog-inferred.","localisation_and_range":"Ligand flagged secreted [flag]; range not otherwise reported.","caveats":"Indirect readout of receptor engagement, no binding measurement. Abstract only was read. Several other WNTs gave the same effect, so this is not specific to WNT10B.","key_references":[{"PMID":"27458145","why":"WNT-10B dissociates the FZD4-Galpha12/13 complex in live cells"}],"covers":["LR003466","LR006666"]},"LR008079":{"pair":"WNT10B -> FZD6:LRP6","headline":"Co-IP in HEK293T supports Wnt10b with Fzd6 and with LRP6 separately, enhanced by SMOC-2; complex not tested as a unit.","interaction_type":"direct binding","direction_and_effect":"SMOC-2 enhanced the interaction between Wnt3a/Wnt10b and LRP6 and between Wnt10b and Fzd6, and activated WNT/beta-catenin signalling [PMID:30594556].","molecular_requirements":"Fzd6 and LRP6 were each tested as separate HA-tagged receptors, not as a pre-formed complex [PMID:30594556].","affinity_potency":[],"species_and_systems":"Co-cultured HEK293T cells with tagged proteins; the abstract describes endometrial cancer cells (AN3CA) [PMID:30594556].","localisation_and_range":"Ligand flagged secreted [flag].","caveats":"Binding was shown per chain, and was measured mainly as enhancement by SMOC-2. The first paper was abstract only; a second paper was review-only.","key_references":[{"PMID":"30594556","why":"Wnt10b co-IP with Fzd6 and LRP6, enhanced by SMOC-2"}],"covers":["LR008079"]},"LR007485":{"pair":"WNT11 -> FZD1:LRP5","headline":"WNT11 to a FZD1:LRP5 complex is database-asserted only; no verified paper.","interaction_type":"database-asserted only","direction_and_effect":"Reactome lists a generic WNT:FZD complex at the plasma membrane [DB:Reactome]; no experiment on the FZD1:LRP5 combination is available.","molecular_requirements":"The receptor is annotated as a FZD1 plus LRP5 complex [flag]; whether both chains are needed is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Not reported in our evidence.","localisation_and_range":"Ligand is flagged secreted; LRP5 is flagged transmembrane [flag].","caveats":"One review-only and five abstract_insufficient rows; nothing verified. The Reactome entry does not distinguish this pairing from other WNT:FZD complexes [DB:Reactome].","key_references":[],"covers":["LR007485"]},"LR006675":{"pair":"WNT11 -> MUSK","headline":"WNT11 is reported to bind the MuSK extracellular domain directly, based on an abstract-level read.","interaction_type":"direct binding","direction_and_effect":"Wnt11 binds the extracellular domain of MuSK, inducing MuSK dimerization and tyrosine phosphorylation; Wnt11 induced acetylcholine receptor clustering (agonist) [PMID:22309736].","molecular_requirements":"Wnt-induced AChR clustering requires LRP4, so LRP4 acts alongside MuSK [PMID:22309736].","affinity_potency":[],"species_and_systems":"Mammalian Wnts screened for AChR clustering in muscle cells; the dossier labels species as human, and the mouse pair is not ortholog-inferred [PMID:22309736].","localisation_and_range":"Wnt11 is flagged secreted [flag]; it is expressed in developing muscle [PMID:22309736].","caveats":"Abstract only; the binding assay and cell type are not reported in our evidence. Wnt11 effect was non-additive with agrin. No affinity.","key_references":[{"PMID":"22309736","why":"Wnt9a and Wnt11 bind MuSK ectodomain, require LRP4"}],"covers":["LR003475","LR006675"]},"LR006684":{"pair":"WNT3 -> FZD10","headline":"Functional: Wnt3/Wnt3a signalled via all FZDs in HEK293T rescue assays; six other papers were abstract-insufficient.","interaction_type":"functional only","direction_and_effect":"Wnt3/Wnt3a induced signalling via all FZDs, unlike more selective Wnts [PMID:28733458].","molecular_requirements":"Tested by rescuing FZD-mutant HEK293T cells; FZD10 clusters with FZD4 in the reported map [PMID:28733458].","affinity_potency":[],"species_and_systems":"Human HEK293T CRISPR mutant cells with TCF4/Wnt luciferase [PMID:28733458].","localisation_and_range":"Localisation not reported in our evidence.","caveats":"Broad, non-selective result across all FZDs; no direct binding shown for FZD10. Six judged papers were abstract_insufficient and are not used.","key_references":[{"PMID":"28733458","why":"Wnt3/3a signal through all FZDs in rescue assay"}],"covers":["LR003484","LR006684"]},"LR004983":{"pair":"WNT3 -> FZD5","headline":"Wnt3 induced signalling through FZD5 in a human cell reporter screen, a generic functional result; mouse pair is projected.","interaction_type":"functional only","direction_and_effect":"Agonist-type signalling: the paper states \"Wnt3/Wnt3a induced signaling via all FZDs, in contrast to other Wnts that were more selective\" [PMID:28733458]. Our annotation lists a stimulatory modulatory effect for this pair.","molecular_requirements":"Co-receptor and subunit requirements are not reported in our evidence.","affinity_potency":[],"species_and_systems":"HEK293T FZD1,2,7 (and FZD1,2,4,5,7,8) CRISPR-mutant cells, TCF4/Wnt luciferase [PMID:28733458]; mouse pair is ortholog-inferred.","localisation_and_range":"Ligand is flagged secreted [flag]; range not reported in our evidence.","caveats":"The sentence is generic across FZDs; specifics sit in a figure matrix not in the dossier. Functional rescue only, no binding. Many other papers were abstract_insufficient.","key_references":[{"PMID":"28733458","why":"Wnt-FZD rescue map in CRISPR FZD-mutant HEK293T cells"}],"covers":["LR001594","LR004983"]},"LR008169":{"pair":"WNT3 -> FZD7:LRP5","headline":"WNT3-FZD7 is supported by two abstract-level studies; LRP5 as a complex partner is not tested in our evidence.","interaction_type":"functional only","direction_and_effect":"Wnt3 binding to FZD7 decreases when both Wnt3 N-glycosylation sites (Asn90 and Asn301) are mutated, with reduced Wnt/beta-catenin proteins [PMID:38994173]. Fzd7 is reported as the Wnt3 receptor in Wnt3-regulated Foxp2 mRNA translation in neocortex; Fzd7 is required for Wnt3-induced Foxp2 translation [PMID:33525513].","molecular_requirements":"FZD7 is the evidenced subunit; LRP5 is not mentioned in the evidence shown. Glycosylation of Wnt3 at Asn90/Asn301 affects FZD7 binding [PMID:38994173].","affinity_potency":[],"species_and_systems":"HCC cells (species not stated in the dossier) [PMID:38994173]; developing neocortex neurons, species not stated in the dossier [PMID:33525513]. Both read as abstracts only. IntAct holds FZD7-related co-IP and pull-down records [DB:IntAct].","localisation_and_range":"Ligand is flagged secreted [flag]; range not reported in our evidence.","caveats":"Both papers are abstract-only and tested FZD7, not the complex; the curated assay_class direct_binding for the glycosylation paper rests on confocal co-localisation.","key_references":[{"PMID":"38994173","why":"Wnt3 glycosylation sites affect FZD7 binding in HCC cells"},{"PMID":"33525513","why":"Fzd7 as Wnt3 receptor for Foxp2 translation"}],"covers":["LR008169"]},"LR003489":{"pair":"WNT3A -> APP","headline":"One abstract-level paper reports APP binds Wnt3a via its cysteine-rich domain, promoting APP stability; thin support.","interaction_type":"direct binding","direction_and_effect":"Wnt3a binding promotes full-length APP recycling and stability, in contrast to Wnt5a, which promotes lysosomal targeting [PMID:34515635]. APP is therefore treated as a Wnt receptor whose levels Wnt3a raises (agonist label from curators).","molecular_requirements":"A conserved cysteine-rich domain in the APP extracellular region is required for Wnt binding; deleting it abrogates Wnt effects on full-length APP [PMID:34515635]. Co-receptors are not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human APP constructs, mouse embryonic primary cortical neurons and HEK293T cells; Drosophila APPL used for the Wnt5 work [PMID:34515635]. Both human and mouse interactions are ortholog-inferred.","localisation_and_range":"APP is flagged secreted, receptor and transmembrane [flag]; WNT3A is flagged secreted [flag].","caveats":"The full-text excerpts shown in our evidence document co-IP with Wnt5a, not Wnt3a; the Wnt3a binding claim rests on the abstract. No affinity reported. The readout is APP trafficking, not classical downstream signalling.","key_references":[{"PMID":"34515635","why":"APP binds Wnt3a and Wnt5a via its CRD; Wnt3a stabilises APP"}],"covers":["LR003489","LR006689"]},"LR004974":{"pair":"WNT3A -> FZD1","headline":"Supported by co-IP, binding-affinity mapping and functional rescue studies; WNT3A activates canonical signalling through FZD1.","interaction_type":"direct binding","direction_and_effect":"WNT3A activates canonical beta-catenin signalling: Hfz1 enhanced WNT3A-induced TCF-dependent transcription in a dose-dependent way [PMID:10557084]. Curators label it agonist, and a CRISPR rescue map shows WNT3A signals through a broad spectrum of FZDs [PMID:28733458].","molecular_requirements":"Truncating the Hfz1 carboxy terminus markedly reduced its capacity to enhance Wnt signalling [PMID:10557084]. The FZD cysteine-rich domain is described as required for Wnt binding [PMID:28733458]. Co-receptor need for FZD1 specifically is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human Hfz1 co-immunoprecipitated with Wnt-3a in transfected cells [PMID:10557084]; bio-layer interferometry with purified WNTs and FZD cysteine-rich domains in a separate study [PMID:25605717]; multiplex FZD1/FZD2/FZD7 mutant HEK293T cells [PMID:28733458]. BioGRID records Affinity Capture-Western [DB:BioGRID].","localisation_and_range":"WNT3A is flagged secreted and not transmembrane [flag], so signalling is expected to be paracrine or autocrine; range is not measured in our evidence.","caveats":"All three papers were read as abstracts (the third has full-text excerpts that concern FZD1 only as a targeted gene). Wnt-5a also co-precipitated with Hfz1 without TCF signalling, so binding alone does not predict activation [PMID:10557084]. No affinity value is given for FZD1 in our abstracts.","key_references":[{"PMID":"10557084","why":"Hfz1 co-IP with Wnt-3a and TCF signalling enhancement"},{"PMID":"25605717","why":"bio-layer interferometry WNT-FZD binding map"},{"PMID":"28733458","why":"CRISPR FZD rescue map of Wnt ligands"}],"covers":["LR001585","LR004974"]},"LR006693":{"pair":"WNT3A -> GPC5","headline":"GPC5 is reported to bind Wnt3a at the cell surface and suppress Wnt/beta-catenin signalling; evidence is a single abstract-only paper.","interaction_type":"functional only","direction_and_effect":"GPC5 suppresses Wnt/beta-catenin signalling by binding Wnt3a at the cell surface, acting as an antagonist or sequestering decoy [PMID:27157618].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Lung adenocarcinoma cells and tissue, human; in vivo tumour growth reported [PMID:27157618]. Mouse version projected from human.","localisation_and_range":"Both partners are flagged secreted [flag]; the paper places the binding at the cell surface [PMID:27157618].","caveats":"Read as abstract only; the binding assay is not described in our evidence, no affinity given. No database records.","key_references":[{"PMID":"27157618","why":"GPC5 binds Wnt3a and suppresses Wnt signalling in lung adenocarcinoma"}],"covers":["LR003493","LR006693"]},"LR001599":{"pair":"WNT4 -> FZD2","headline":"WNT4 binds FZD2 directly but does not activate canonical signalling in 32D cells; a co-IP in MC3T3 cells also found Wnt4-Fzd2.","interaction_type":"direct binding","direction_and_effect":"Bio-layer interferometry shows WNT-4 binds the FZD2 CRD, but did not activate the WNT-beta-catenin pathway through FZD2 [PMID:25605717]. DVL isoform effects suggest non-canonical output.","molecular_requirements":"CRD binding suffices in the assay [PMID:25605717]. Wnt4-LRP5, Wnt4-LRP6 and Wnt4-Fzd2 complexes also found [PMID:31216173].","affinity_potency":[],"species_and_systems":"32D cells, human labelled [PMID:25605717]; co-IP in MC3T3 (mouse) cells [PMID:31216173]. Human pair ortholog-inferred.","localisation_and_range":"Ligand flagged secreted [flag].","caveats":"Abstract-only for 25605717; 31216173 browser-read and not spot-checked. Affinity values not in our evidence. The 'agonist' label conflicts with non-activation of canonical signalling.","key_references":[{"PMID":"25605717","why":"BLI binding of WNT-4 to FZD2 CRD"},{"PMID":"31216173","why":"Wnt4-Fzd2 co-IP"}],"covers":["LR001599","LR004988"]},"LR003498":{"pair":"WNT4 -> FZD4","headline":"WNT4 binds FZD4 in purified protein and co-IP assays but does not activate canonical beta-catenin signalling through it.","interaction_type":"direct binding","direction_and_effect":"Bio-layer interferometry shows WNT-4 directly binds the FZD4 cysteine-rich domain, but in 32D cells WNT-4 did not activate the WNT-beta-catenin pathway through it; effects on DVL2 vs DVL3 phosphorylation suggest non-canonical output [PMID:25605717].","molecular_requirements":"The CRD of the Frizzled is sufficient for binding in the assay [PMID:25605717].","affinity_potency":[],"species_and_systems":"Bio-layer interferometry and 32D cells, human labelled [PMID:25605717]. Mouse version listed directly; human is ortholog-inferred.","localisation_and_range":"Ligand flagged secreted [flag].","caveats":"Abstract only; affinity values are in a table not shown in our evidence. Curator effect label 'agonist' conflicts with the non-activation of canonical signalling.","key_references":[{"PMID":"25605717","why":"WNT-FZD CRD binding kinetics and signalling"}],"covers":["LR003498","LR006698"]},"LR004992":{"pair":"WNT5A -> FZD4","headline":"Wnt5a is supported for FZD4 by binding, structural-BRET and signalling studies; Wnt5a stimulates FZD4 CRD dimerization and dissociates FZD4-G12/13.","interaction_type":"direct binding","direction_and_effect":"WNT5A stimulated dimerization of membrane-anchored FZD4 CRDs and oligomerization of full-length FZD4 in BRET [PMID:28546512]. The FZD4-G protein complex dissociated on WNT-5A stimulation [PMID:27458145]. Xfz4 interacts with Xwnt5A to activate the beta-catenin pathway in Xenopus [PMID:10990458].","molecular_requirements":"Oligomerization required the integrity of the CRD palmitoleoyl-binding residues [PMID:28546512]. FZD4 assembles with Ga12/13 specifically, independent of DVL [PMID:27458145]. LRP involvement is not reported for this pair, see the FZD4:LRP5 dossier.","affinity_potency":[{"value":"KD = 22\u201326 nm","assay":"Bio-layer interferometry, WNT-5A binding to FZD CRD-Fc, reported jointly for the FZD1/2/4 CRDs","system":"mouse proteins, in vitro","cite":"PMID:25605717"}],"species_and_systems":"Human FZD4 BRET and G-protein work in cells [PMID:28546512][PMID:27458145]; mouse proteins for BLI [PMID:25605717]; Xenopus for the pathway study [PMID:10990458].","localisation_and_range":"WNT5A is flagged secreted and not transmembrane [flag], so signalling would be paracrine or autocrine by this annotation.","caveats":"Most papers were read as abstracts only. Recombinant WNT5A protein did not significantly increase full-length FZD4 interactions, whereas transfected WNT5A DNA did [PMID:28546512]. The affinity quote is from a browser read, spot-check pending [PMID:25605717].","key_references":[{"PMID":"25605717","why":"BLI binding of WNT-5A to FZD CRDs"},{"PMID":"28546512","why":"WNT5A stimulates FZD4 CRD dimerization and oligomerization"},{"PMID":"27458145","why":"WNT-5A dissociates FZD4-G12/13 complex"}],"covers":["LR001603","LR004992"]},"LR007683":{"pair":"WNT5A -> FZD4:LRP6","headline":"No paper evidence for WNT5A with FZD4:LRP6; database records are on single chains.","interaction_type":"database-asserted only","direction_and_effect":"Not reported in our evidence; the only judged paper was review-only. UniProt notes that in the presence of FZD4, activates beta-catenin signaling [DB:UniProt].","molecular_requirements":"BioGRID records LRP6 - WNT5A Affinity Capture-Western [DB:BioGRID]. Whether both subunits are needed is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Not reported in our evidence.","localisation_and_range":"WNT5A is flagged secreted and not transmembrane [flag], so signalling would be paracrine or autocrine by this annotation.","caveats":"Database-only. Elsewhere in this batch, Wnt5a with Fz4 required LRP5 and was reported not to work with LRP6 (see the FZD4:LRP5 dossier), which does not support this combination.","key_references":[],"covers":["LR007683"]},"LR007692":{"pair":"WNT5A -> FZD8:RYK","headline":"Functional evidence for RYK dependence in human cells; FZD8 is not named in the paper.","interaction_type":"functional only","direction_and_effect":"WNT5A-bearing extracellular vesicles linger in early endocytic structures; this rerouting depends on RYK expression [PMID:42536732]. Curated as agonist.","molecular_requirements":"RYK is described as an established WNT5A co-receptor; FZD8 is not individually tested [PMID:42536732]. Reactome lists a WNT5A:RYK:VANGL2 complex, not FZD8 [DB:Reactome R-HSA-4551548].","affinity_potency":[],"species_and_systems":"Genetic screen of 300 surfaceome genes, human; details beyond the abstract not reported in our evidence [PMID:42536732].","localisation_and_range":"Membrane receptor complex flag [flag]; ligand carried on extracellular vesicles in this study [PMID:42536732].","caveats":"Paper read as abstract only. The readout is vesicle trafficking, not binding, and supports RYK alone; the FZD8 subunit is unsupported.","key_references":[{"PMID":"42536732","why":"RYK-dependent WNT5A-EV trafficking; no FZD8 data"}],"covers":["LR007692"]},"LR006729":{"pair":"WNT7B -> LRP6","headline":"WNT7B is blocked by anti-LRP6 antibodies, implying LRP6 involvement; no direct binding data.","interaction_type":"functional only","direction_and_effect":"Wnt7b signalling was among those inhibited by Wnt1-class anti-LRP6 Fab fragments (A1-Fab, A2-Fab) [PMID:20713706].","molecular_requirements":"LRP6 first propeller is implicated; Wnt1-class antibodies bind it [PMID:20713706]. Frizzled requirement is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human ligand and receptor; SuperTopFlash reporter in HEK293 cells [PMID:20713706]. The mouse pair is projected from human.","localisation_and_range":"WNT ligand is flagged secreted and not transmembrane [flag], so signalling would be paracrine or autocrine; no paper in our evidence measured range.","caveats":"Antibody blockade shows pathway dependence, not direct Wnt7b-LRP6 binding. Curator read of the full text was done in a browser with the quote unverified (spot-check pending); the abstract in the dossier is truncated.","key_references":[{"PMID":"20713706","why":"Anti-LRP6 Fabs inhibit Wnt1-class signalling including Wnt7b"}],"covers":["LR003529","LR006729"]},"LR008097":{"pair":"WNT8A -> FZD8:LRP6","headline":"WNT8A signalling via FZD8:LRP6 supported by one functional paper; LRP6 co-receptor is not tested.","interaction_type":"functional only","direction_and_effect":"Wnt8a induced signalling via FZD5 and FZD8 in reporter cells [PMID:28733458].","molecular_requirements":"Evidence concerns the Frizzled chain only; LRP6 involvement is not reported in our evidence.","affinity_potency":[],"species_and_systems":"HEK293-type reporter cells with FZD knockouts [PMID:28733458]; species not stated in this record.","localisation_and_range":"WNT ligand is flagged secreted and not transmembrane [flag], so signalling would be paracrine or autocrine; no paper in our evidence measured range.","caveats":"The complex pair rests on a FZD-only result, so it is chain-only evidence; other judged papers were review_only or abstract_insufficient.","key_references":[{"PMID":"28733458","why":"Wnt-FZD functional interaction map"}],"covers":["LR008097"]},"LR008178":{"pair":"WNT8B -> FZD8:LRP5","headline":"WNT8B activates FZD8 signalling in a reporter-cell rescue map; one functional paper, no binding data.","interaction_type":"functional only","direction_and_effect":"WNT8B induced canonical (TCF/Wnt-reporter) signalling via FZD8, i.e. ligand-to-receptor agonism in a functional readout [PMID:28733458].","molecular_requirements":"The receptor is listed as FZD8 plus LRP5; the paper's statement names only the Frizzled, and a requirement for LRP5 is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Experiments used reporter cells in a rescue design with FZD-mutant lines [PMID:28733458]; species of the cells is not stated in the excerpts.","localisation_and_range":"Secreted ligand per the entity annotation flag [flag]; paracrine range is inferred from that flag only, not reported in the papers.","caveats":"Functional reporter readout only; no direct binding shown. Paper is a genetic rescue map of Wnt-FZD pairs, so paralog FZDs differ in specificity [PMID:28733458].","key_references":[{"PMID":"28733458","why":"Multiplex CRISPR FZD-knockout rescue map of Wnt-Frizzled signalling (full text read)."}],"covers":["LR008178"]},"LR010689":{"pair":"WNT9B -> FZD1:LRP6","headline":"Database-asserted WNT9B to FZD1:LRP6 complex; no curator-verified paper supports the complex as a unit.","interaction_type":"database-asserted only","direction_and_effect":"Direction and effect are not reported in our evidence. UniProt subunit notes assert that FZD-family O14905 (WNT9B) interacts directly in the complex with LRP6 and that LRP6 (via beta-propeller regions 1 and 2) interacts with WNT9B [DB:UniProt].","molecular_requirements":"The complex is the FZD1 plus LRP6 pair; no experiment in our evidence tests the combination. Support is from UniProt notes about WNT9B and LRP6 only [DB:UniProt].","affinity_potency":[],"species_and_systems":"Not reported in our evidence; the UniProt records cite PMID 20093360 and PMID 11357136 but no dossier paper was verified for this complex [DB:UniProt].","localisation_and_range":"WNT9B is flagged as secreted [flag], so signalling would be paracrine; the receptor is a membrane receptor [flag].","caveats":"Rests on database records alone; the notes do not name the Frizzled chain. Papers were judged only as review_only or abstract_insufficient. Treat as a projection from WNT9B-LRP6 evidence.","key_references":[],"covers":["LR010689"]},"LR006747":{"pair":"WNT9B -> LRP6","headline":"WNT9B binds the E1E2 region of the LRP6 extracellular domain, shown with purified proteins.","interaction_type":"direct binding","direction_and_effect":"Wnt9b binds a different part of the LRP6 extracellular domain, E1E2, than Wnt3a (E3E4), and both bind LRP6 at the same time; curators label it agonist [PMID:20093360]. Dkk1 competes with both for LRP6 [PMID:20093360].","molecular_requirements":"Soluble Fz8-CRD and LRP6 ectodomain inhibit Wnt/beta-catenin signalling in cell assays; the Fz8 CRD.Wnt3a.LRP6 complex was reconstituted with Wnt3a [PMID:20093360]. UniProt records the direct interaction [DB:UniProt].","affinity_potency":[],"species_and_systems":"Insect-cell expressed mouse Fz8 CRD and human LRP6 ectodomain, purified proteins; mouse and human pairs are ortholog-inferred [PMID:20093360].","localisation_and_range":"WNT9B is flagged as secreted [flag], so signalling would be paracrine; the receptor is a membrane receptor [flag].","caveats":"Read as abstract only; no Wnt9b-LRP6 affinity appears in our excerpts. Agonist label is a curator inference.","key_references":[{"PMID":"20093360","why":"Wnt9b binds LRP6 E1E2, independently of Wnt3a"}],"covers":["LR003547","LR006747"]},"LR005388":{"pair":"ZP3 -> CHRNA7","headline":"One abstract-read paper reports ZP3 binding to alpha7 nAChR in a mouse sperm system; human pair is inferred from mouse.","interaction_type":"direct binding","direction_and_effect":"A microfluidic affinity in vitro assay showed alpha7 nAChR interacted with ZP3; isolated zona pellucida or alpha7 agonists induced the acrosome reaction in wild-type but not alpha7-null sperm, suggesting ZP activates alpha7 (agonist) [PMID:22577141].","molecular_requirements":"Activation of alpha7 was proposed to lead to SFK-dependent EGFR activation, Ca2+ influx and the acrosome reaction, so EGFR acts downstream [PMID:22577141].","affinity_potency":[],"species_and_systems":"Mouse sperm (wild type and Chrna7-knockout) and egg zona pellucida [PMID:22577141]. The human pair is ortholog-inferred, not tested.","localisation_and_range":"ZP3 is flagged secreted [flag]; in the paper it is a component of the egg zona pellucida matrix that contacts sperm, so signalling is contact-dependent [PMID:22577141].","caveats":"Abstract only; the identity of the sperm ZP receptor is described as uncertain [PMID:22577141]. No affinity reported. Human evidence is projected from mouse.","key_references":[{"PMID":"22577141","why":"Microfluidic assay: ZP3 interacts with alpha7 nAChR; Chrna7-null sperm"}],"covers":["LR002062","LR005388"]},"LR004299":{"pair":"IL17A -> IL17RA","headline":"IL-17A binds IL-17RA, a chain of the IL-17RA/IL-17RC complex; direct binding reported in two abstract-read papers.","interaction_type":"direct binding","direction_and_effect":"Agonist. IL-17A activity is inhibited by soluble IL-17RA, and IL-17 antibodies to the receptor blocked IL-17-induced cytokine production in human fibroblasts [PMID:18684971][PMID:9367539].","molecular_requirements":"Signalling by the cytokines depends on the IL-17RA/IL-17RC complex [PMID:18684971]. UniProt describes IL17RA and IL17RC as forming complexes with 2:1 receptor-to-cytokine stoichiometry and an asymmetric IL17A homodimer with one IL17RA [DB:UniProt].","affinity_potency":[],"species_and_systems":"Human cytokine and human receptor; SPR and bronchial epithelial cell assays [PMID:18684971]; human receptor cloned from a T cell library, foreskin fibroblasts [PMID:9367539]. Mouse pair listed, not ortholog-inferred.","localisation_and_range":"Ligand flagged secreted [flag]; paracrine range follows from that annotation only.","caveats":"Both papers were read as abstracts. The 1997 binding was low affinity [PMID:9367539]; SPR affinities for IL-17RA differ between cytokines but values are not reported in our evidence [PMID:18684971]. The receptor name in the entity is given as interleukin-17C receptor [flag].","key_references":[{"PMID":"18684971","why":"SPR and soluble receptor data for IL-17A with IL-17RA/RC"},{"PMID":"9367539","why":"Cloning of human IL-17R and low-affinity IL-17 binding"}],"covers":["LR000869","LR004299"]},"LR000879":{"pair":"IL1A -> IL1R2","headline":"IL-1 alpha binds the type II IL-1 receptor, a decoy-type receptor; direct binding shown in one abstract-read paper.","interaction_type":"direct binding","direction_and_effect":"Soluble and cell-surface type II IL-1 receptor bind IL-1 alpha and IL-1 beta; the soluble form acts as a specific inhibitor of IL-1 beta activity [PMID:7878046]. This indicates a decoy/inhibitory role rather than signalling, though the dossier labels the pair Stimulatory [flag].","molecular_requirements":"Not reported in our evidence beyond the receptor itself; binding was to the same regions on IL-1 beta for soluble and cell-surface forms [PMID:7878046].","affinity_potency":[],"species_and_systems":"Human Raji B cell line, radioligand competition binding [PMID:7878046]. Mouse pair is projected from human evidence.","localisation_and_range":"Ligand annotated as secreted [flag]; the receptor exists as membrane-bound and released soluble forms [PMID:7878046].","caveats":"Abstract-only reading. The paper's detail concerns IL-1 beta more than IL-1 alpha. IntAct (coimmunoprecipitation) and Reactome records support binding [DB:IntAct][DB:Reactome]. One further paper is pending.","key_references":[{"PMID":"7878046","why":"Competition binding of IL-1 alpha and beta to type II receptor, soluble and cell-surface"}],"covers":["LR000879","LR004309"]},"LR004389":{"pair":"KNG1 -> PLAUR","headline":"High-molecular-mass kininogen binds soluble uPAR in a domain-mapping binding study; one abstract-read paper plus databases.","interaction_type":"direct binding","direction_and_effect":"Biotinylated high-molecular-mass kininogen (HK) binds soluble uPAR, with binding inhibited by HK, 56HKa and 46HKa [PMID:14764580]. Effect on signalling is not reported in our evidence.","molecular_requirements":"Two suPAR-binding sites were mapped on kininogen: a higher-affinity site in the light chain and a lower-affinity site in the heavy chain; suPAR domains 2 and 3 are mainly involved. HK binds uPAR as part of a multiprotein receptor complex on HUVEC [PMID:14764580].","affinity_potency":[],"species_and_systems":"Soluble uPAR and HUVEC cells; competitive binding assay and peptide mapping [PMID:14764580]. Mouse pair is projected from human evidence.","localisation_and_range":"Ligand annotated as secreted; PLAUR as secreted and transmembrane [flag]; uPAR is described as GPI-linked [PMID:14764580].","caveats":"Abstract-only reading; the paper concerns the HK protein, not bradykinin peptide. BioGRID reconstituted complex and Reactome records agree [DB:BioGRID][DB:Reactome].","key_references":[{"PMID":"14764580","why":"Maps kininogen-suPAR binding sites by competition binding"}],"covers":["LR000967","LR004389"]}};